The transmitted signal of the DFBS in the time slot $ l $ is
\begin{align}
	{\bf{x}}[l] = \sum\limits_{k = 1}^K {{{\bf{w}}_k}[l]{s_{k}}[l]} + {{\bf{w}}_\vartheta}[l]{s_\vartheta}[l],
\end{align}
where $ {s_{k}}[l] \in \mathbb{C} $ denotes the communication signal for the $ k $-th L-UAV, which satisfies $ \mathbb{E}\{ {{{\left| {{s_{k}[l]}} \right|}^2}} \} = 1 $. The corresponding beamforming vector is $ {{\bf{w}}_k}[l] \in {\mathbb{C}^{M \times 1}} $. $ {s_{\vartheta}[l]} \in \mathbb{C} $ is the sensing signal and meets $ \mathbb{E}\{ {{{\left| {{s_{\vartheta}[l]}} \right|}^2}} \} = 1 $, and $ {{\bf{w}}_\vartheta}[l] \in {\mathbb{C}^{M \times 1}} $ represents the sensing beamforming vector at the DFBS.

\subsection{Communication Model}
The received signal at the $ k $-th L-UAV in the $ l $-th time slot can be expressed as
\begin{align}
	{y_{k}}[l] = ({\bf{h}}_{d,k}^{\mathsf{H}}[l] + {\bf{h}}_{\mathrm{r},k}^{\mathsf{H}}[l]{\bf{\Phi}}[l]{\bf{G}}[l]){\bf{x}}[l] + {n_k}[l],
\end{align}
where $ {\bf{h}}_{d,k}[l] \in {\mathbb{C}^{M \times 1}} $ denotes the channel vector between the DFBS and the $k$-th L-UAV, $ {\bf{h}}_{\mathrm{r},k}[l] \in {\mathbb{C}^{N \times 1}} $ represents the channel vector between the RIS and the $k$-th L-UAV, and $ {\bf G}[l] \in {\mathbb{C}^{N \times M}} $ denotes the channel matrix from the DFBS to the RIS. $ {\bf{\Phi }}[l] \buildrel \Delta \over = \mathrm{diag}\{ {\phi _1[l]},{\phi _2[l]},...,{\phi _N[l]}\} \in {\mathbb{C}^{N \times N}} $ with $ {\phi _n[l]} = {e^{\mathrm{j}{\theta _n[l]}}} $ represents the phase shift matrix of the RIS, where $ {\theta _n[l]} \in \left[ {0,2\pi } \right) $. $ {n_k}[l] \sim {\cal C}{\cal N}(0,\sigma _k^2) $ denotes the additive white Gaussian noise (AWGN). 

We assume that the channels $ {\bf{G}}[l] $, $ {{\bf{h}}_{d,k}}[l] $, and $ {{\bf{h}}_{\mathrm{r},k}}[l] $ are modeled as Rician fading. Then, we can obtain
\begin{align}
    {\bf{G}}[l] = {\beta _{\mathrm{G}}}\left(\sqrt {\frac{\kappa_{\mathrm{G}} }{{\kappa_{\mathrm{G}} + 1}}}{\bm{\alpha }} _{\mathrm{G}}^{\mathrm{LoS}} + \sqrt {\frac{1}{{\kappa_{\mathrm{G}} + 1}}} {\bm{\alpha }} _{\mathrm{G}}^{\mathrm{NLoS}}[l]\right),
\end{align}
{\small \begin{align}
    {{\bf{h}}_{\mathrm{d},k}}[l] = {\beta _{\mathrm{d},k}}[l]\left(\sqrt {\frac{{{\kappa _{\mathrm{d},k}}}}{{{\kappa _{\mathrm{d},k}} + 1}}} {\bm{\alpha }}_{\mathrm{d},k}^{\mathrm{LoS}}[l] + \sqrt {\frac{1}{{{\kappa _{\mathrm{d},k}} + 1}}} {\bm{\alpha }}_{\mathrm{d},k}^{\mathrm{NLoS}}[l]\right),
\end{align}}%
and
{\small \begin{align}
    {{\bf{h}}_{\mathrm{r},k}}[l] = {\beta _{\mathrm{r},k}}[l]\left(\sqrt {\frac{{{\kappa _{\mathrm{r},k}}}}{{{\kappa _{\mathrm{r},k}} + 1}}} {\bm{\alpha }}_{\mathrm{r},k}^{\mathrm{LoS}}[l] + \sqrt {\frac{1}{{{\kappa _{\mathrm{r},k}} + 1}}} {\bm{\alpha }}_{\mathrm{r},k}^{\mathrm{NLoS}}[l]\right),
\end{align}}%
where 
$\beta _{\mathrm{G}} = \frac{\beta_0}{\Vert {\bf{q}}_{\mathrm{BS}} - {\bf{q}}_{\mathrm{RIS}}\Vert}$,
$\beta _{\mathrm{d},k} [l] = \frac{\beta_0}{\Vert {\bf{q}}_{\mathrm{BS}} - {\bf{q}}_{k}[l]\Vert}$
% $ {\beta _{\Gamma }}[l]$ $(\Gamma \in \{ G, \{ d,k\}, \{ r,k\}) $ 
$\beta _{\mathrm{r},k} [l] = \frac{\beta_0}{\Vert {\bf{q}}_{\mathrm{RIS}} - {\bf{q}}_{k}[l]\Vert}$
represent the distance dependent path loss, and $\beta_0$ denotes the path loss at the reference distance $1 \mathrm{m}$. $ {{\bm{\alpha }}^{\mathrm{LoS}}_{\mathrm{G}}} = {\bf{a}}_N({\theta _{\mathrm{R,B}}}){{\bf{a}}_M^{\mathsf{H}}}({\theta _{\mathrm{B, R}}}) $ is the LoS component with the steering vectors $ {{\bf{a}}_N}({\theta _{\mathrm{R,B}}}) = {[1,{e^{ - {\mathrm{j}}\pi \sin {\theta _{\mathrm{R,B}}}}},...,{e^{ - {\mathrm{j}}(N - 1)\pi \sin {\theta _{\mathrm{R,B}}}}}]^{\mathsf{H}}} $, and $ {{\bf{a}}_M}({\theta _{\mathrm{B, R}}}) = {[1,{e^{ - {\mathrm{j}}\pi \sin {\theta _{\mathrm{B, R}}}}},...,{e^{ - {\mathrm{j}}(M - 1)\pi \sin {\theta _{\mathrm{B, R}}}}}} ]^{\mathsf{H}} $, where $ {\theta _{\mathrm{R,B}}}$ and $ {\theta _{\mathrm{B, R}}} $ denote the direct-of-arrival (DoA) and direct-of-departure of channel $ {\bf{G}} $, respectively. 
Meanwhile, $ \alpha _{{\rm{d}},k}^{{\rm{LoS}}}[l] = {\bf{a}}_M^{\mathsf{}}({\theta _{{\rm{BS}},k}}[l]) $ and $ {{\bm{\alpha }}^{\mathrm{LoS}}_{\mathrm{r},k}[l]} = {\bf{a}}_N^{\mathsf{}}({\theta _{{\rm{RIS}},k}}[l]) $ are the steering vectors from the DFBS to the $ k $-th L-UAV, and from the RIS to the $ k $-th L-UAV, respectively, where $ {\theta _{\mathrm{BS}, k}[l]} $ and $ {\theta _{\mathrm{RIS}, k}[l]} $ are the DoAs at the $ k $-th L-UAV corresponding to the direct link by the DFBS, and the reflecting link by the RIS, respectively.
$ {{\bm{\alpha }}^{\mathrm{NLoS}}_{\mathrm{G}}[l]} $, $ {{\bm{\alpha }}^{\mathrm{NLoS}}_{\mathrm{r},k}[l]} $, and $ {{\bm{\alpha }}^{\mathrm{NLoS}}_{\mathrm{d},k}[l]} $ represent the NLoS components, having a zero mean and unit variance. $ \kappa_{\mathrm{G}} $, $\kappa_{\mathrm{d},k}$, and $\kappa _{\mathrm{r},k}$ are the Rician factor. 

The decoded signal-to-interference-plus-nois-ratio of the $k$-th L-UAV can be denoted as
\begin{align}
	{\gamma _k}[l] = \frac{{{{\left| {{\bf{H}}_k^{\mathsf{H}}[l]{{\bf{w}}_k[l]}} \right|}^2}}}{{\sum\limits_{i = 1,i \ne k}^K {{\left| {{\bf{H}}_k^{\mathsf{H}}[l]{{\bf{w}}_i[l]}} \right|^2}} + {{\left| {{\bf{H}}_k^{\mathsf{H}}[l]{{\bf{w}}_\vartheta[l] }} \right|}^2} + \sigma_k^2}},
\end{align}
where $ {\bf{H}}_k^{\mathsf{H}}[l] \buildrel \Delta \over = {\bf{h}}_{\mathrm{d},k}^{\mathsf{H}}[l] + {\bf{h}}_{\mathrm{r},k}^{\mathsf{H}}[l]{\bf{\Phi}}[l] {\bf{G}}[l] $. Then, the data rate of the $ k $-th L-UAV can be expressed as
\begin{align}
	{R_k}[l] = {\log _2}(1 + {\gamma _k}[l]).
\end{align}

\subsection{Sensing Model}
The DFBS utilizes the same signals for performing communication services and sensing detections. Thus, the echo signal coming from the U-UAV in time slot $ l $ can be written as 
\begin{align}
	{{\bf {y}}_{t}}[l] = {{\bf{G}}_t}[l]{\bf{x}}[l] + {{\bf{n}}_{t}}[l],
\end{align}
where $ {{\bf{G}}_t}[l] \buildrel \Delta \over = ({{\bf{g}}_{\mathrm{d},t}}[l] + {{\bf{G}}^{\mathsf{H}}[l]}{\bf{\Phi }}[l]{{\bf{g}}_{\mathrm{r},t}}[l])({\bf{g}}_{\mathrm{d},t}^{\mathsf{H}}[l] + {\bf{g}}_{\mathrm{r},t}^{\mathsf{H}}[l]{\bf{\Phi}}[l]\\ {\bf{G}}[l]) $, $ {\bf{g}}_{\mathrm{d},t}[l] \in {\mathbb{C}^{M \times 1}} $ and $ {\bf{g}}_{\mathrm{r},t}[l] \in {\mathbb{C}^{N \times 1}} $ represent the channel vectors from the DFBS to the U-UAV and from the RIS to the U-UAV, respectively. Adopting a common assumption in radar sensing \cite{10364735,luoRISAided2023}, we model the propagation paths between the DFBS/RIS and the U-UAV as LoS channels. Specifically, these channels can be expressed as $ {{\bf{g}}_{\mathrm{d},t}}[l] = {\beta _{\mathrm{d},t}[l]}{{\bf{a}}_M^{\mathsf{}}}(\theta _t^1[l]) $ and $ {{\bf{g}}_{\mathrm{r},t}}[l] = {\beta _{\mathrm{r},t}[l]}{{\bf{a}}_N^{\mathsf{}}}(\theta _t^2[l]) $,
where $\theta _t^1[l] $ and $ \theta _t^2[l] $ denote the DoAs of the U-UAV with respect to the DFBS and the RIS, respectively. $ {\beta _{\mathrm{d},t}}[l] = \frac{{{\beta _0}}}{{\left\| {{{\bf{q}}_{{\rm{BS}}}} - {{\bf{q}}_{\rm{U}}}[l]} \right\|}} $ and $ {\beta _{\mathrm{r},t}}[l] = \frac{{{\beta _0}}}{{\left\| {{{\bf{q}}_{{\rm{RIS}}}} - {{\bf{q}}_{\rm{U}}}[l]} \right\|}} $ denote the corresponding distance dependent path loss.
$ {{\bf{n}}_{t}}[l] \sim {\cal C}{\cal N}({\bf{0}},\sigma_{t}^2{{\bf{I}}_M}) $ denotes the AWGN. Then, the radar sensing SNR for the U-UAV is given by
\begin{align}
	{\rm{SN}}{{\rm{R}}_t}[l] = \frac{{\sum\limits_{i = 1}^K {{{\left| {{\bf{G}}_t^{\mathsf{H}}[l]{{\bf{w}}_i[l]}} \right|}^2}}  + {{\left| {{\bf{G}}_t^{\mathsf{H}}[l]{{\bf{w}}_\vartheta[l] }} \right|}^2}}}{{\sigma _t^2}}.
\end{align}\(\)

% For the successful detection of the U-UAV, only when the sensing SNR of the U-UAV is higher than a specific threshold will its effective decoding ability of legitimate signals pose a substantial security threat.
%The presence of the U-UAV poses a significant security threat only when its sensing SNR exceeds a specific threshold.
%Hence, this paper optimizes the resource allocation of the system under the premise of satisfying the SNR constraint of the U-UAV, effectively improving the system communication performance in the presence of unauthorized intruders and providing a solution for the security design for the LANs.

The presence of the U-UAV poses a significant security threat only when its sensing SNR exceeds a specific threshold. Therefore, this paper focuses on optimizing the system's resource allocation while ensuring that the U-UAV's SNR constraint is satisfied. This approach effectively enhances the system's communication performance in the presence of unauthorized intruders and offers a viable solution for the security design of LANs.

