\subsection{Problem Formulation}
% A joint optimization framework for RIS-assisted ISAC systems is proposed in this paper, 
We aim to optimize the sum-rate of all L-UAVs, by co-designing the communication beamforming ${\bf{w}}_k[l]$, the sensing beamforming ${\bf{w}}_\vartheta[l]$, and the RIS phase shift parameters ${\bf{\Phi }}[l]$.
Then, the optimization problem can be formulated as
\begin{subequations}
	\begin{align}
		{\rm{P1}}:& \mathop {\max }\limits_{{\bf{w}}_k[l], {\bf{w}}_\vartheta[l], {\bf{\Phi }}[l]}\ \frac{1}{L}\sum\limits_{l = 1}^L {\sum\limits_{k = 1}^K {{R_k}[l]} }, \label{27a}\\
		\mathrm{s.t.}&\ \ \frac{{\sum\limits_{i = 1}^K {{{\left| {{\bf{G}}_t^{\mathsf{H}}[l]{{\bf{w}}_i[l]}} \right|}^2}}  + {{\left| {{\bf{G}}_t^{\mathsf{H}}[l]{{\bf{w}}_\vartheta[l] }} \right|}^2}}}{{\sigma _t^2}} \ge {\Gamma}, \forall{l}, \label{27b} \\
		&\left| {{\phi _n}[l]} \right| = 1, n \in {\cal N}, \forall{l}, \label{27d}\\
		&{\sum\limits_{k = 1}^K {\left\| {\bf{w}}_k[l] \right\|^2} + \left\| {\bf{w}}_\vartheta[l] \right\|^2} \le P_{\max}, \forall{l}, \label{27e}
	\end{align}
\end{subequations}
where \(\Gamma\) denotes the pre-defined radar sensing SNR requirement and \(P_{\max}\) is the maximum transmit power of the DFBS.
Constraint \eqref{27b} represents the sensing requirement.
Constraint \eqref{27d} is the physical constriant of the element phase parameters of the RIS.
Lastly, constraint \eqref{27e} denotes the transmit power constraint of the DFBS.

Evidently, problem P1 exhibits non-convexity. The reason is that the variables are coupled in both the objective function and constraint (\ref{27b}).
Moreover, the constraint of the RIS phase parameters to unitary modes exacerbates the challenge of solving P1.

\section{Coordinated Beamforming For RIS-Empowered ISAC System}
% Consequently, i
In the subsequent discussion, we put forward the employment of FP and AO methods to convert problem P1 into three sub-problems, which we solve through an iterative process. 

\subsection{Transformation of Objective Function}
In the optimization problem P1, due to the coupling relationship between the optimization variables in the numerator and denominator of the objective function, the problem is difficult to solve directly. Therefore, according to \cite{8310563}, we utilize the FP method to handle this obstacle. Specifically, we first introduce the auxiliary variable ${\bf{r}}[l] \buildrel \Delta \over = {[{r_1[l]},{r_2[l]},...,{r_K[l]}]^{\mathsf{T}}}$, and then restructure the objective function as
\begin{align}
    f =&\ \frac{1}{L}\sum\limits_{l = 1}^L \left( \sum\limits_{k = 1}^K {{{\log }_2}(1 + {r_k}[l])} - \sum\limits_{k = 1}^K {{r_k}[l]} \notag \right.\\
    &+ \left. \sum\limits_{k = 1}^K {\frac{{(1 + {r_k}[l]){{\left| {{\bf{H}}_k^{\mathsf{H}}[l]{{\bf{w}}_k}[l]} \right|}^2}}}{{\sum\limits_{i = 1}^K {{{\left| {{\bf{H}}_k^{\mathsf{H}}[l]{{\bf{w}}_i}[l]} \right|}^2}} + {{\left| {{\bf{H}}_k^{\mathsf{H}}[l]{{\bf{w}}_\vartheta }[l]} \right|}^2} + \sigma _k^2}}} \right). \label{21}
\end{align}

\begin{Proposition}
The original optimization problem is mathematically equivalent to the following reformulated problem
\begin{subequations}
	\begin{align}
		{\rm{P2}}: \mathop {\max }\limits_{{\bf{w}}_k[l], {\bf{w}}_\vartheta[l], {\bf{\Phi }}[l], {\bf{r}}[l]}\ &\eqref{21} \nonumber \\
		\mathrm{s.t.}\qquad\quad &\eqref{27b}\text{-}\eqref{27e} \nonumber.
	\end{align}
\end{subequations}
\begin{proof} 
    Notice that when \( {\bf w}[l] \) is fixed, the function in \eqref{21} is a differentiable concave function with respect to \( {\bf r}[l] \). As such, the optimal solution for \( {\bf r}[l] \) can be derived by setting each \( \frac{\partial f}{\partial {\bf r}[l]} \) to zero. Once the optimized \( {\bf r}[l] \) is substituted back into \eqref{21}, the objective function in \eqref{27a} is precisely recovered. This process confirms the equivalence between the two problems {\rm{P1}} and {\rm{P2}}.
    %The detailed proof of this equivalence can be found in \cite{8310563}.
\end{proof}
\end{Proposition}

