To efficiently solve the problem P2, we decouple it into three disjoint subproblems and target to find the solution of each subproblem. Detailed information are given as follows.

\subsection{Block Update}

\subsubsection{Closed-Form Optimal Solution for $ {\bf r}[l] $} When other variables are fixed, the optimal value of $ {\bf{r}}[l] $ can be derived by solving $ \frac{{\partial f}}{{\partial {\bf{r}}[l]}} = 0 $, leading to the expression
\begin{align}
	r_k^*[l] = \frac{{{{\left| {{\bf{H}}_k^{\mathsf{H}}[l]{{\bf{w}}_k[l]}} \right|}^2}}}{{\sum\limits_{i = 1,i \ne k}^K {{{\left| {{\bf{H}}_k^{\mathsf{H}}[l]{{\bf{w}}_i[l]}} \right|}^2}}  + {{\left| {{\bf{H}}_k^{\mathsf{H}}[l]{{\bf{w}}_\vartheta[l] }} \right|}^2} + \sigma _k^2}}. \label{n9}
\end{align}

\subsubsection{Update Active Beamforming} Given fixed $ {\bf r}[l] $ and $ {\bf{\Phi}}[l] $, the optimization problem for active beamforming can be derived by isolating relevant terms, resulting in the following problem P3

\begin{subequations}
	{\small \begin{align} 
            {\rm{P3}}:&\mathop {\max }\limits_{{{\bf{w}}_k[l]},{{\bf{w}}_\vartheta[l] }} \;\frac{1}{L}\sum\limits_{l = 1}^L {\sum\limits_{k = 1}^K {\frac{{(1 + {r_k[l]}){{\left| {{\bf{H}}_k^{\mathsf{H}}[l]{{\bf{w}}_k}[l]} \right|}^2}}}{{\sum\limits_{i = 1}^K {{{\left| {{\bf{H}}_k^{\mathsf{H}}[l]{{\bf{w}}_i}[l]} \right|}^2}}  + {{\left| {{\bf{H}}_k^{\mathsf{H}}[l]{{\bf{w}}_\vartheta }[l]} \right|}^2} + \sigma _k^2}}} }, \\
            \mathrm{s.t.}& \quad \frac{{\sum\limits_{i = 1}^K {{{\left| {{\bf{G}}_t^{\mathsf{H}}[l]{{\bf{w}}_i[l]}} \right|}^2}}  + {{\left| {{\bf{G}}_t^{\mathsf{H}}[l]{{\bf{w}}_\vartheta[l] }} \right|}^2}}}{{\sigma _t^2}} \ge {\Gamma}, \forall{l},\label{12b}\\
            &\quad \sum\limits_{k = 1}^K {{{\left\| {{{\bf{w}}_k[l]}} \right\|}^2}} + {\left\| {{{\bf{w}}_\vartheta[l] }} \right\|^2} \le {P_{\max}},\forall{l}.
	\end{align}}%
\end{subequations}
Since the objective function of problem P3 exhibits a sum-of-ratio structure, we utilize the quadratic transformation method and introduce the auxiliary variables $ {\bf{c}}[l] \buildrel \Delta \over = {[{c_1}[l],{c_2}[l],...,{c_K}[l]]^{\mathsf{T}}} $. Then, we can reformulate the objective function as
\begin{align}
    &{\cal F}({\bf{w}},{\bf{c}}) \buildrel \Delta \over = \frac{1}{L}\sum\limits_{l = 1}^L \sum\limits_{k = 1}^K \Bigg(2\sqrt {1 + {r_k}[l]} \Re \{ c_k^*[l]{\bf{H}}_k^{\mathsf{H}}[l]{{\bf{w}}_k}[l]\} \notag \\
    & -\left. {{\left| {{c_k}[l]} \right|}^2}\left(\sum\limits_{i = 1}^K {{{\left| {{\bf{H}}_k^{\mathsf{H}}[l]{{\bf{w}}_i}[l]} \right|}^2}}  + {{\left| {{\bf{H}}_k^{\mathsf{H}}[l]{{\bf{w}}_\vartheta }[l]} \right|}^2} + \sigma _k^2\right)\right),
\end{align}
where 
\begin{align}
    c_k^*[l] = \frac{{\sqrt {1 + {r_k[l]}} {\bf{H}}_k^{\mathsf{H}}[l]{{\bf{w}}_k[l]}}}{{\sum\limits_{i = 1}^K {{{\left| {{\bf{H}}_k^{\mathsf{H}}[l]{{\bf{w}}_i[l]}} \right|}^2}}  + {{\left| {{\bf{H}}_k^{\mathsf{H}}[l]{{\bf{w}}_\vartheta[l] }} \right|}^2} + \sigma _k^2}}. \label{n12}
\end{align}
To handle the quadratic terms in (\ref{12b}), we introduce the following Proposition 2.
\begin{Proposition}
For the quadratic term defined by
\begin{align}
    I({\bf{w}}[l]) = {\left| {{\bf{G}}_t^{\mathsf{H}}[l]{{\bf{w}}}[l]} \right|^2},\label{nn15}
\end{align}
its first-order Taylor expansion to the point $ {\widehat {\bf{w}}}[l] $ is given by
\begin{align}
    \widehat I({\bf{w}}[l],\widehat {\bf{w}}[l]) =&\ 2\Re \{\widehat {\bf{w}}^{\mathsf{H}}[l]{{\bf{G}}_t[l]}{\bf{G}}_t^{\mathsf{H}}[l]{{\bf{w}}[l]}\} \notag \\
    &- \Re \{\widehat {\bf{w}}^{\mathsf{H}}[l]{{\bf{G}}_t[l]}{\bf{G}}_t^{\mathsf{H}}[l]{\widehat {\bf{w}}[l]}\}.
\end{align}
Therefore, $ I({\bf{w}}[l]) $ can be approximated by $ \widehat I({\bf{w}}[l],\widehat {\bf{w}}[l]) $ at point $ {\widehat {\bf{w}}}[l] $.
\end{Proposition}
\begin{proof}
Using the Taylor series approximation, the quadratic term defined in \eqref{nn15} satisfies
\begin{align}
    I({\bf{w}}[l]) \ge I(\widehat {\bf{w}}[l]) + {\left. {\frac{{\partial I}}{{\partial {\bf{w}}[l]}}} \right|_{\widehat {\bf{w}}[l]}}({\bf{w}}[l] - \widehat {\bf{w}}[l]).
\end{align}
Then, we have
\begin{align}
    I({\bf{w}}[l]) \ge&\ {\widehat {\bf{w}}^{\mathsf{H}}}[l]{{\bf{G}}_t}[l]{\bf{G}}_t^{\mathsf{H}}[l]\widehat {\bf{w}}[l] \notag \\
    &+ 2{\widehat {\bf{w}}^{\mathsf{H}}}[l]{{\bf{G}}_t}[l]{\bf{G}}_t^{\mathsf{H}}[l]({\bf{w}}[l] - \widehat {\bf{w}}[l])\notag \\
    \ge&\ 2{\widehat {\bf{w}}^{\mathsf{H}}}[l]{{\bf{G}}_t}[l]{\bf{G}}_t^{\mathsf{H}}[l]{\bf{w}}[l] \notag \\
    &- {\widehat {\bf{w}}^{\mathsf{H}}}[l]{{\bf{G}}_t}[l]{\bf{G}}_t^{\mathsf{H}}[l]\widehat {\bf{w}}[l].
\end{align}
Considering the real characteristic of $ I({\bf{w}}[l]) $, \eqref{nn15} can be rewritten as
\begin{align}
    I({\bf{w}}[l]) \ge&\ 2\Re \{ {\widehat {\bf{w}}^{\mathsf{H}}}[l]{{\bf{G}}_t}[l]{\bf{G}}_t^{\mathsf{H}}[l]{\bf{w}}[l]\} \notag \\
    &- \Re \{ {\widehat {\bf{w}}^{\mathsf{H}}}[l]{{\bf{G}}_t}[l]{\bf{G}}_t^{\mathsf{H}}[l]\widehat {\bf{w}}[l]\} \notag \\
    \buildrel \Delta \over =&\ \widehat I({\bf{w}}[l],\widehat {\bf{w}}[l]).
\end{align}
The proof is completed.
\end{proof}
%we concentrate on the quadratic term $ {{{\left| {{\bf{G}}_t^H[l]{{\bf{w}}_i[l]}} \right|}^2}} $. The first-order Taylor approximation of this term around $\widehat {\bf{w}}_i[l]$ can be formulated as 
%\begin{align}
    %{\left| {{\bf{G}}_t^H[l]{{\bf{w}}_i[l]}} \right|^2} &= 2\Re \{\widehat {\bf{w}}_i^H[l]{{\bf{G}}_t[l]}{\bf{G}}_t^H[l]{{\bf{w}}_i[l]}\} \notag \\
    %&- \Re \{\widehat {\bf{w}}_i^H[l]{{\bf{G}}_t[l]}{\bf{G}}_t^H[l]{\widehat {\bf{w}}_i[l]}\},
%\end{align}
\noindent Then, (\ref{12b}) can be reformulated as
{\small \begin{align}
	&\sum\limits_{i = 1}^K {2\Re \{\widehat {\bf{w}}_i^{\mathsf{H}}[l]{{\bf{G}}_t[l]}{\bf{G}}_t^{\mathsf{H}}[l]{{\bf{w}}_i[l]}\} - \Re \{\widehat {\bf{w}}_i^{\mathsf{H}}[l]{{\bf{G}}_t[l]}{\bf{G}}_t^{\mathsf{H}}[l]{{\widehat {\bf{w}}}_i[l]}\}} \notag \\
	&+ 2\Re \{\widehat {\bf{w}}_\vartheta ^{\mathsf{H}}[l]{{\bf{G}}_t[l]}{\bf{G}}_t^{\mathsf{H}}[l]{{\bf{w}}_\vartheta[l] }\} - \Re \{\widehat {\bf{w}}_\vartheta ^{\mathsf{H}}[l]{{\bf{G}}_t[l]}{\bf{G}}_t^{\mathsf{H}}[l]{\widehat {\bf{w}}_\vartheta[l] }\} \notag \\
    & \ge \Gamma \sigma _t^2.
\end{align}}%
Based on the derivatives and transformations above, the optimization problem P3 has been transformed into a convex one.

\subsubsection{Passive Beamforming Optimization}
Define $ {{\bf{v}}^{\mathsf{H}}[l]} = [{v_1}[l],{v_2}[l],...,{v_N}[l]] $ where $ {v_n}[l] = {e^{\mathrm{j}{\theta _n}[l]}} $, we can reconstruct the complex channel as
\begin{align}
    \begin{array}{l}
    ({\bf{h}}_{\mathrm{d},i}^{\mathsf{H}}[l] + {\bf{h}}_{\mathrm{r},i}^{\mathsf{H}}[l]{\bf{\Phi }}[l]{\bf{G}}[l]){{\bf{w}}_j}[l] = \\
    \underbrace {\left[ {{\bf{h}}_{\mathrm{r},i}^{\mathsf{H}}[l]{\rm{diag}}({\bf{G}}[l]{{\bf{w}}_j}[l])\ \ {\bf{h}}_{\mathrm{d},i}^{\mathsf{H}}[l]{{\bf{w}}_j}[l]} \right]}_{\widetilde {\bf{H}}_{i,j}^{\mathsf{H}}[l]}\underbrace {\left[ {\begin{array}{*{20}{l}}
    {{\bf{v}}[l]}\\
    {\;1}
    \end{array}} \right]}_{\widetilde {\bf{v}}[l]},i,j \in \{ K,\vartheta \},
    \end{array}
\end{align}
and
\begin{align}
    &{\bf{G}}_t^{\mathsf{H}}[l]{{\bf{w}}_i}[l] \notag \\ 
    &=\left( {\underbrace {\left[ {{{\bf{G}}^{\mathsf{H}}}[l]{\rm{diag}}({{\bf{g}}_{\mathrm{r},t}}[l])\ \ {{\bf{g}}_{\mathrm{d},t}}[l]} \right]}_{{{\widetilde {\bf{G}}}_t}[l]}\widetilde {\bf{v}}[l]} \right)\left( {{{\widetilde {\bf{v}}}^{\mathsf{H}}}[l]\widetilde {\bf{G}}_t^{\mathsf{H}}[l]} \right){{\bf{w}}_i}[l] \notag \\
    &= {\widetilde {\bf{G}}_t}[l]\widetilde {\bf{v}}[l]{\widetilde {\bf{v}}^{\mathsf{H}}}[l]\widetilde {\bf{G}}_t^{\mathsf{H}}[l]{{\bf{w}}_i}[l], i \in \{ K,\vartheta \},
\end{align}
Then, the passive beamforming optimization problem can be written as
\begin{subequations}
	\begin{align}
		&{\rm{P4}}:\mathop {\max }\limits_{\widetilde{\bf{v}}[l]} \;         {\cal F}(\widetilde{\bf{v}}[l]),\\
		&\mathrm{s.t.}\ \sum\limits_{i = 1}^K {{{\left| {{\bf{w}}_i^{\mathsf{H}}[l]           {{\widetilde {\bf{G}}}_t[l]}\widetilde {\bf{v}}[l]{{\widetilde       {\bf{v}}}^{\mathsf{H}}[l]}\widetilde {\bf{G}}_t^{\mathsf{H}}[l]} \right|}^2}}           \notag \\
            &\qquad + {\left| {{\bf{w}}_\vartheta ^{\mathsf{H}}[l]{{\widetilde {\bf{G}}}_t[l]}\widetilde {\bf{v}}[l]{{\widetilde {\bf{v}}}^{\mathsf{H}}[l]}\widetilde {\bf{G}}_t^{\mathsf{H}}[l]} \right|^2} \ge \Gamma \sigma _t^2, \label{52e}\\
		&\qquad \left| {{v_n}[l]} \right| = 1,n \in {\cal N}, \label{52h}
	\end{align}
\end{subequations}
where 
\begin{align}
