\title{Run-Time Power Modelling in Embedded GPUs with Dynamic Voltage and Frequency Scaling}

\author{Jose Nunez-Yanez, Kris Nikov, Kerstin Eder, Mohammad Hosseinabady}
\email{{j.l.nunez-yanez,kris.nikov,kerstin.eder}@bristol.ac.uk,  mohammad@hosseinabady.com}
