    \subfigure[]
    {\includegraphics[width=0.47\textwidth]{figure/bmk/voltage.png}\label{fig:bmk_v_a}}
    \hspace{0.01\textwidth}
    \subfigure[]
    {\includegraphics[width=0.47\textwidth]{figure/bmk/RMSE.png}\label{fig:bmk_v_b}} 
