\section{Appendix A. Adjoint sensitivity analysis}
\label{app_adj}

\setcounter{equation}{0} 
\setcounter{figure}{0} 
\setcounter{table}{0} 
Consider the objective function with multi-time responses, we first transfer the optimization problem (\ref{eq_inv}) into an unconstrained problem by constructing the following Lagrangian function:
\begin{align}\label{eq_lag}
    \widehat{\mathcal{L}} = \mathcal{L} + \sum_{i=1}^N\left(\boldsymbol{\lambda}^i\right)^{\textrm{T}}\boldsymbol{R}^i+\left(\boldsymbol{\lambda}^0\right)^{\textrm{T}}\left[\boldsymbol{g}\left(\boldsymbol{\theta}\right)-\boldsymbol{U}^0\right]
\end{align}
where $\boldsymbol{\lambda}$ denotes the Lagrangian multiplier. The necessary condition for the optimality of $\widehat{\mathcal{L}}$ can be obtained by seeking its stationary points, according to which the derivative of $\widehat{\mathcal{L}}$ with respect to $\boldsymbol{\lambda}$ and $\boldsymbol{U}$ should satisfy:
\begin{align}\label{eq_dLdl0}
    \frac{\partial\widehat{\mathcal{L}}}{\partial\boldsymbol{\boldsymbol{\lambda}}^0} = \boldsymbol{g}\left(\boldsymbol{\theta}\right)-\boldsymbol{U}^0=\boldsymbol{0}
\end{align}
\begin{align}\label{eq_dLdl}
    \frac{\partial\widehat{\mathcal{L}}}{\partial\boldsymbol{\boldsymbol{\lambda}}^k} = \boldsymbol{R}^k=\boldsymbol{0},\quad k=1,\cdots,N
\end{align}
\begin{align}\label{eq_dLdU0}
    \frac{\partial\widehat{\mathcal{L}}}{\partial\boldsymbol{\boldsymbol{U}}^0} = \left(\boldsymbol{\lambda}^1\right)^{\textrm{T}}\frac{\partial\boldsymbol{R}^1}{\partial\boldsymbol{U}^0}-\left(\boldsymbol{\lambda}^0\right)^{\textrm{T}}=\boldsymbol{0}
\end{align}
\begin{align}\label{eq_dLdU}
    \frac{\partial\widehat{\mathcal{L}}}{\partial\boldsymbol{\boldsymbol{U}}^k} = \frac{\partial\mathcal{L}}{\partial\boldsymbol{\boldsymbol{U}}^k} + \sum_{i=1}^N\left(\boldsymbol{\lambda}^i\right)^{\textrm{T}}\frac{\partial\boldsymbol{R}^i}{\partial\boldsymbol{U}^k}=\boldsymbol{0},\quad k=1,\cdots,N
\end{align}
where (\ref{eq_dLdl0}) corresponds to the initial condition, and (\ref{eq_dLdl}) is the equilibrium equation at each time step. The derivative of $\widehat{\mathcal{L}}$ with respect to $\boldsymbol{\theta}$ can be expressed as:
\begin{align}\label{eq_dLdt}
     \frac{\partial\widehat{\mathcal{L}}}{\partial\boldsymbol{\theta}} = \frac{\partial\mathcal{L}}{\partial\boldsymbol{\theta}} + \sum_{i=1}^N\left(\boldsymbol{\lambda}^i\right)^{\textrm{T}}\frac{\partial\boldsymbol{R}^i}{\partial\boldsymbol{\theta}}+\left(\boldsymbol{\lambda}^0\right)^{\textrm{T}}\frac{\textrm{d}\boldsymbol{g}}{\textrm{d}\boldsymbol{\theta}}
\end{align}

Then we will prove that if (\ref{eq_dLdl0}) and (\ref{eq_dLdl}) are satisfied, and the Lagrange multipliers are obtained through (\ref{eq_dLdU0}) and (\ref{eq_dLdU}), the total derivative $\frac{\textrm{d}\mathcal{L}}{\textrm{d}\boldsymbol{\theta}}$ is equal to (\ref{eq_dLdt}). Substitute (\ref{eq_dLdU}) into (\ref{eq_inv_chain_multi}), we have:
\begin{align}\label{eq_dLdt_simp1}
    \frac{\textrm{d}\mathcal{L}}{\textrm{d}\boldsymbol{\theta}} = \frac{\partial\mathcal{L}}{\partial\boldsymbol{\theta}} - \sum_{i=1}^N\left(\boldsymbol{\lambda}^i\right)^{\textrm{T}}\left(\sum_{k=1}^{N}\frac{\partial\boldsymbol{R}^i}{\partial\boldsymbol{U}^k}\frac{\textrm{d}\boldsymbol{U}^k}{\textrm{d}\boldsymbol{\theta}}\right)
\end{align}
Then we take the derivative of the equilibrium equation $\boldsymbol{R}^i=\boldsymbol{0}$ with respect to $\boldsymbol{\theta}$:
\begin{align}\label{eq_dR}
    \frac{\textrm{d}\boldsymbol{R}^i}{\textrm{d}\boldsymbol{\theta}} = \frac{\partial\boldsymbol{R}^i}{\partial\boldsymbol{\theta}} + \sum_{k=1}^N\frac{\partial\boldsymbol{R}^i}{\partial\boldsymbol{U}^k}\frac{\textrm{d}\boldsymbol{U}^k}{\textrm{d}\boldsymbol{\theta}} + \frac{\partial\boldsymbol{R}^i}{\partial\boldsymbol{U}^0}\frac{\textrm{d}\boldsymbol{g}}{\textrm{d}\boldsymbol{\theta}} =\boldsymbol{0},\quad i=1,\cdots,N
\end{align}
Substitute (\ref{eq_dR}) into (\ref{eq_dLdt_simp1}), we have:
\begin{align}\label{eq_dLdt_simp2}
     \frac{\textrm{d}\mathcal{L}}{\textrm{d}\boldsymbol{\theta}}= \frac{\partial\mathcal{L}}{\partial\boldsymbol{\theta}} + \sum_{i=1}^N\left(\boldsymbol{\lambda}^i\right)^{\textrm{T}}\left[\frac{\partial\boldsymbol{R}^i}{\partial\boldsymbol{\theta}}+\frac{\partial\boldsymbol{R}^i}{\partial\boldsymbol{U}^0}\frac{\textrm{d}\boldsymbol{g}}{\textrm{d}\boldsymbol{\theta}}\right]
\end{align}
Since $\boldsymbol{U}^0$ only contributes to $\boldsymbol{R}^1$, with (\ref{eq_dLdU0}), we obtain: 
\begin{align}\label{eq_dLdt_simp3}
     \frac{\textrm{d}\mathcal{L}}{\textrm{d}\boldsymbol{\theta}}= \frac{\partial\widehat{\mathcal{L}}}{\partial\boldsymbol{\theta}} = \frac{\partial\mathcal{L}}{\partial\boldsymbol{\theta}} + \sum_{i=1}^N\left(\boldsymbol{\lambda}^i\right)^{\textrm{T}}\frac{\partial\boldsymbol{R}^i}{\partial\boldsymbol{\theta}}+\left(\boldsymbol{\lambda}^0\right)^{\textrm{T}}\frac{\textrm{d}\boldsymbol{g}}{\textrm{d}\boldsymbol{\theta}}
\end{align}
which has the same form as (\ref{eq_inv_chain5_single}), with the Lagrangian multipliers corresponding to the adjoint vectors.

The Lagrangian multipliers in (\ref{eq_dLdt_simp3}) can be obtained via (\ref{eq_dLdU0}) and (\ref{eq_dLdU}). Note that $\boldsymbol{U}^N$ only contributes to $\boldsymbol{R}^N$, we can derive the adjoint equation for $\boldsymbol{\lambda}^N$ via (\ref{eq_dLdU}):
\begin{align}\label{eq_ad_it_N}
    \left(\frac{\partial\boldsymbol{R}^N}{\partial\boldsymbol{U}^N}\right)^{\textrm{T}}\boldsymbol{\lambda}^N = -\left(\frac{\partial\mathcal{L}}{\partial\boldsymbol{\boldsymbol{U}}^N}\right)^{\textrm{T}}
\end{align}
For $i=N-1$ to $i=1$, $\boldsymbol{U}^{i}$ contributes to $\boldsymbol{R}^i$ and $\boldsymbol{R}^{i+1}$, with which (\ref{eq_dLdU}) can be simplified as:
\begin{align}\label{eq_dLdU_simp}
    \frac{\partial\mathcal{L}}{\partial\boldsymbol{\boldsymbol{U}}^i} + \left(\boldsymbol{\lambda}^i\right)^{\textrm{T}}\frac{\partial\boldsymbol{R}^i}{\partial\boldsymbol{U}^i} + \left(\boldsymbol{\lambda}^{i+1}\right)^{\textrm{T}}\frac{\partial\boldsymbol{R}^{i+1}}{\partial\boldsymbol{U}^{i}}=0,\quad i=N-1,\cdots,1 
\end{align}
Then the corresponding Lagrangian multipliers can be solved in a backward recurrence with the following adjoint equation:
\begin{align}\label{eq_ad_it}
     \left(\frac{\partial\boldsymbol{R}^i}{\partial\boldsymbol{U}^i}\right)^{\textrm{T}}\boldsymbol{\lambda}^i =-\left[\frac{\partial\mathcal{L}}{\partial\boldsymbol{\boldsymbol{U}}^i}+\left(\boldsymbol{\lambda}^{i+1}\right)^{\textrm{T}}\frac{\partial\boldsymbol{R}^{i+1}}{\partial\boldsymbol{U}^{i}}\right]^{\textrm{T}},\quad i=N-1,\cdots,1 
\end{align}
Finally, $\boldsymbol{\lambda}^0$ can be obtained via (\ref{eq_dLdU0}):
\begin{align}\label{eq_ad_it_0}
    \boldsymbol{\lambda}^0 = \left(\frac{\partial\boldsymbol{R}^1}{\partial\boldsymbol{U}^0}\right)^{\textrm{T}}\boldsymbol{\lambda}^1
\end{align}
We observe that the derivation yields the same expression for $\frac{\partial\mathcal{L}}{\partial\boldsymbol{\theta}}$, and the adjoint equations are consistent with those in the customized reverse-mode AD, further confirming the validity of the AD-based sensitivity analysis framework.

