\begin{definition}[1-Wasserstein Distance of Node Heterophily Distributions]
Let $ G = (\mathcal{V}, \mathcal{E}, A, X, Y) $ and $ G' = (\mathcal{V}', \mathcal{E}', A', X', Y') $ be two graphs with node heterophily distributions:
\begin{equation}
    h_G \sim P_V, \quad h_{G'} \sim P_{V'}.
\end{equation}
We define their 1-Wasserstein Distance as:
\begin{equation}
    W_1(h_G, h_{G'}) = \inf_{\gamma \in \Pi(P_V, P_{V'})} \mathbb{E}_{(h,h') \sim \gamma} [|h - h'|],
\end{equation}
where:
\begin{itemize}
    \item $ \Pi(P_V, P_{V'}) $ denotes the set of all joint distributions $ \gamma(h, h') $ whose marginal distributions are $ P_V $ and $ P_{V'} $, respectively.
    \item This distance measures the minimum transportation cost required to transform the distribution $ P_V $ into $ P_{V'} $, where the transportation cost is given by $ |h - h'| $.
\end{itemize}

This metric characterizes the optimal transport distance between the node heterophily distributions of two graphs and enables the comparison of their overall heterophily structures. Specifically:
\begin{itemize}
    \item If $ W_1(h_G, h_{G'}) \approx 0 $, the two graphs have very similar heterophily distributions.
    \item If $ W_1(h_G, h_{G'}) $ is large, the heterophily structures of the two graphs are significantly different.
\end{itemize}
\end{definition}
\begin{corollary}[Wasserstein-1 Distance for Feature Distributions]
\label{cor:feature-wasserstein}
Let $ P_S^F $ and $ P_T^F $ be the empirical distributions of node features $ f $ in the source graph $ G^S $ and target graph $ G^T $, respectively. The 1-Wasserstein distance between these distributions is given by:
\begin{equation}
    W_1(P_S^F, P_T^F) = \inf_{\gamma^F \in \Pi(P_S^F, P_T^F)} \mathbb{E}_{(i,j) \sim \gamma^F} [\|f_i - f_j\|],
\end{equation}
where $ \Pi(P_S^F, P_T^F) $ is the set of all joint distributions $ \gamma^F(i,j) $ with marginals $ P_S^F $ and $ P_T^F $. This measures the minimum transportation cost required to transform the feature distribution of $ G^S $ into that of $ G^T $.
\end{corollary}

\begin{corollary}[Wasserstein-1 Distance for Node Heterophily Distributions]
\label{cor:heterophily-wasserstein}
Let $ P_S^H $ and $ P_T^H $ be the empirical distributions of node heterophily values $ h $ in the source graph $ G^S $ and target graph $ G^T $, respectively. The 1-Wasserstein distance between these distributions is given by:
\begin{equation}
    W_1(P_S^H, P_T^H) = \inf_{\gamma^H \in \Pi(P_S^H, P_T^H)} \mathbb{E}_{(i,j) \sim \gamma^H} [|h_i - h_j|],
\end{equation}
where $ \Pi(P_S^H, P_T^H) $ is the set of all joint distributions $ \gamma^H(i,j) $ with marginals $ P_S^H $ and $ P_T^H $. This quantifies the minimum transportation cost to align the heterophily distribution between the two graphs.
\end{corollary}
