\begin{lemma}[Upper Bound on 1-Wasserstein Distance via KL Divergence]~\cite{bobkov1999exponential}
\label{lemma:W1-KL}
Let $ P $ and $ Q $ be two probability distributions on a metric space $ (\mathcal{X}, d) $, where $ P \ll Q $ (i.e., $ P $ is absolutely continuous with respect to $ Q $). Assume that:
\begin{itemize}
    \item $ \mathcal{X} $ has bounded support with diameter $ D $, i.e., $ d(x,y) \leq D $ for all $ x,y \in \mathcal{X} $,
    \item There exists a constant $ C_0 > 0 $ such that all 1-Lipschitz functions $ f: \mathcal{X} \to \mathbb{R} $ satisfy the concentration inequality:
    \begin{equation}
        \sup_{f \in \mathcal{F}_L} \Big| \mathbb{E}_{x \sim P}[f(x)] - \mathbb{E}_{x \sim Q}[f(x)] \Big| \leq C_0 \sqrt{D_{\text{KL}}(P \| Q)}.
    \end{equation}
\end{itemize}
Then, the 1-Wasserstein distance satisfies the following upper bound:
\begin{equation}
    W_1(P, Q) \leq C_0 \sqrt{D_{\text{KL}}(P \| Q)}.
\end{equation}
The constant $ C $ depends on the geometry of the space $ \mathcal{X} $ and the metric $ d $.
\end{lemma}
\begin{definition} [Expected Loss Discrepancy]
Given a distribution $P$ over  a function family $\gH$, for any $\lambda > 0$ and $\gamma \ge 0$, for any $G^S$ and $G^T$, define the expected loss discrepancy between $\mathcal{V}^S$ and $\mathcal{V}^T$  as
 $
D^{\gamma}_{S, T}(P;\lambda) := \ln \E_{\phi\sim P} e^{\lambda \sbra \Lgh_T(\phi) - \Lg_{S}(\phi)\sket},
$
where $\Lgh_T(\phi)$ and $\Lg_{S}(\phi)$ follow the definition of Eq.~(\ref{eq:margin-loss}).
\end{definition}

\begin{lemma}[Adaptation from ~\cite{ma2021subgroup}] 
Let $ \Phi $ be a family of classification functions. For any classifier $ \phi $ in $ \Phi $, and for any parameters $ \lambda > 0 $ and $ \gamma \geq 0 $, consider any prior distribution $ P $ over $\Phi $ that is independent of the training data $ \mathcal{V}^S $. With a probability of at least $ 1 - \delta $ over the sample $ Y^S $, for any distribution $ Q $ on $\Phi$ such that 
$\Pr_{\phi \sim Q} \left[ \max_{i \in \mathcal{V}^S \cup \mathcal{V}^T} \| \phi_i(X, G) - \phi_i(X, G) \|_{\infty} < \frac{\gamma}{8} \right] > \frac{1}{2}$, the following inequality holds:
\[
    \risk_T(\phi) \leq \hLg_S(\phi) + \frac{1}{\lambda} \left[ 2(\KL(Q \| P) + 1) + \ln \frac{1}{\delta} + \frac{\lambda^2}{4N_S} + D^{\gamma/2}_{S, T}(P;\lambda) \right].
\]
\end{lemma}


\begin{proposition}[Bound for $D^{\gamma}_{S, T}(P;\lambda)$, Adaptation from ~~\cite{ma2021subgroup,mao2024demystifying,fang2025benefits}]
    For any $\gamma \ge 0$, and under the assumption that the prior distribution $P$ over the classification function family $\Phi$ is defined, we establish a bound for the domain discrepancy measure $ D^{\gamma/2}_{S, T}(P;\lambda) $.
    Specifically, we have the following inequality:
    \begin{equation}
        \begin{aligned}
            D^{\gamma/2}_{S, T}(P;\lambda) & 
            \leq \frac{1}{\max(N_S, N_T)} \sum_{i \in V_S} \frac{1}{N_T} \sum_{j \in V_T} \left[
            \ln 3 +  \frac{\lambda \rho C}{\sqrt{2\pi}\sigma}   (\|f_i - f_j\|+ |h_i - h_j|\cdot \rho)\right] \\ & \leq\frac{\lambda \rho C}{\sqrt{2\pi}\sigma\cdot N_S\cdot N_T}\cdot W_1(P_S^F, P_T^F) +  W_1(P_S^H, P_T^H)\\
            & \leq\frac{\lambda \rho C C_0}{\sqrt{2\pi}\sigma\cdot N_S\cdot N_T}\cdot \left[\sqrt{D_{\text{KL}}(P_S^F \| P_T^F)} +
            \sqrt{D_{\text{KL}}(P_S^H \| P_T^H)} \right]
        \end{aligned}
    \end{equation}
    \label{equ: Proposition}
where $f$ is the unspecified operator of first-order aggregation ( considering $f= AX$ and $f=LX$ two easy cases), $C$ is the number of classes, and $\rho,\sigma$ are constants controlled by the node feature distribution of different classes.
\end{proposition}
\begin{proof}
We will prove the proposition by establishing the two key inequalities in the given equation.

\noindent\textbf{ Proof of the First Inequality (Using Prior Works):} \\
From the cited works~\cite{ma2021subgroup, mao2024demystifying, fang2025benefits}, it follows that the expected loss discrepancy measure $ D^{\gamma/2}_{S, T}(P;\lambda) $ can be bounded by:
\begin{equation}
    D^{\gamma/2}_{S, T}(P;\lambda)  
    \leq \frac{1}{\max(N_S, N_T)} \sum_{i \in V_S} \frac{1}{N_T} \sum_{j \in V_T} 
    \left[
    \ln 3 +  \frac{\lambda C\rho}{\sqrt{2\pi}\sigma}   (\|f_i - f_j\|+ |h_i - h_j|\cdot \rho)
    \right].
\end{equation}
This follows from existing domain adaptation literature, where the domain discrepancy measure can be controlled by a sum over pairwise differences of node features and heterophily values.

\noindent\textbf{ Proof of the Second Inequality:} \\
We now show that:
\begin{align}
    &\frac{1}{\max(N_S, N_T)} \sum_{i \in V_S} \frac{1}{N_T} \sum_{j \in V_T} 
    \left[
    \ln 3 +  \frac{\lambda C\rho}{\sqrt{2\pi}\sigma}   (\|f_i - f_j\|+ |h_i - h_j|\cdot \rho)
    \right]\\
    &\leq \frac{\lambda C\rho}{\sqrt{2\pi}\sigma\cdot N_S\cdot N_T} \left(W_1(P_S^F, P_T^F) + \rho W_1(P_S^H, P_T^H) \right).
\end{align}


From \textbf{Corollary~\ref{cor:feature-wasserstein}}, we know that the Wasserstein-1 distance between the node feature distributions is:
\begin{equation}
    W_1(P_S^F, P_T^F) = \inf_{\gamma^F \in \Pi(P_S^F, P_T^F)} \mathbb{E}_{(i,j) \sim \gamma^F} [\|f_i - f_j\|].
\end{equation}
Since the sum over all node pairs approximates an expectation over a joint coupling of the distributions, we approximate:
\begin{equation}
    \sum_{i \in V_S} \sum_{j \in V_T} \|f_i - f_j\| \approx N_S N_T W_1(P_S^F, P_T^F).
\end{equation}
Substituting this into our sum, we obtain:
\begin{equation}
    \sum_{i \in V_S} \sum_{j \in V_T} \frac{1}{N_T} \|f_i - f_j\| \leq N_S W_1(P_S^F, P_T^F).
\end{equation}


Similarly, from \textbf{Corollary~\ref{cor:heterophily-wasserstein}}, we have:
\begin{equation}
    W_1(P_S^H, P_T^H) = \inf_{\gamma^H \in \Pi(P_S^H, P_T^H)} \mathbb{E}_{(i,j) \sim \gamma^H} [|h_i - h_j|].
\end{equation}
Following the same argument as before, we approximate:
\begin{equation}
    \sum_{i \in V_S} \sum_{j \in V_T} |h_i - h_j| \approx N_S N_T W_1(P_S^H, P_T^H).
\end{equation}
Thus:
\begin{equation}
    \sum_{i \in V_S} \sum_{j \in V_T} \frac{1}{N_T} |h_i - h_j| \leq N_S W_1(P_S^H, P_T^H).
\end{equation}


Now substituting these bounds into our sum:
\begin{equation}
    \sum_{i \in V_S} \sum_{j \in V_T} \left[ \ln 3 +  \frac{\lambda C\rho}{\sqrt{2\pi}\sigma}   (\|f_i - f_j\|+ |h_i - h_j|\cdot \rho) \right]
\end{equation}
\begin{equation}
    \leq \sum_{i \in V_S} \sum_{j \in V_T} \ln 3 + \frac{\lambda C\rho}{\sqrt{2\pi}\sigma} N_S (W_1(P_S^F, P_T^F) + \rho W_1(P_S^H, P_T^H)).
\end{equation}

Dividing by $ \max(N_S, N_T) $, we obtain:
\begin{equation}
    \frac{1}{\max(N_S, N_T)} \sum_{i \in V_S} \sum_{j \in V_T} \left[ \ln 3 +  \frac{\lambda C\rho}{\sqrt{2\pi}\sigma}   (\|f_i - f_j\|+ |h_i - h_j|\cdot \rho) \right]
\end{equation}
\begin{equation}
    \leq \frac{\lambda C\rho}{\sqrt{2\pi}\sigma\cdot N_S\cdot N_T} (W_1(P_S^F, P_T^F) + \rho W_1(P_S^H, P_T^H)).
\end{equation}

\noindent\textbf{ Proof of the Third Inequality:} \\
From \textbf{Lemma~\ref{lemma:W1-KL}} (Bobkov-Götze Inequality)~\cite{bobkov1999exponential}, we have:
\begin{equation}
    W_1(P_S^F, P_T^F) \leq C_0 \sqrt{D_{\text{KL}}(P_S^F \| P_T^F)},
\end{equation}
\begin{equation}
    W_1(P_S^H, P_T^H) \leq C_0 \sqrt{D_{\text{KL}}(P_S^H \| P_T^H)}.
\end{equation}

Using these bounds in:
\begin{equation}
    \frac{\lambda \rho C}{\sqrt{2\pi}\sigma\cdot N_S\cdot N_T} \cdot W_1(P_S^F, P_T^F) + \rho W_1(P_S^H, P_T^H),
\end{equation}
we obtain:
\begin{equation}
    \frac{\lambda \rho C C_0}{\sqrt{2\pi}\sigma\cdot N_S\cdot N_T} \cdot \left[\sqrt{D_{\text{KL}}(P_S^F \| P_T^F)} +
    \sqrt{D_{\text{KL}}(P_S^H \| P_T^H)} \right].
\end{equation}
Combining both inequalities, we establish the bound:
\begin{equation}
    D^{\gamma/2}_{S, T}(P;\lambda)  
     \leq\frac{\lambda \rho C C_0}{\sqrt{2\pi}\sigma\cdot N_S\cdot N_T}\cdot \left[\sqrt{D_{\text{KL}}(P_S^F \| P_T^F)} +
            \sqrt{D_{\text{KL}}(P_S^H \| P_T^H)} \right]
\end{equation}

This completes the proof. \qed
\end{proof}
\begin{corollary}[KL Divergence Decomposition of Feature Distributions]
\label{cor:KL-decomposition}
Let $ P_S^F $ and $ P_T^F $ be the feature distributions in the source and target domains, respectively. Suppose that node features $ X $ undergo transformations defined by the adjacency matrix $ A $ and Laplacian matrix $ L $, i.e.,
\begin{equation}
    P_S^F = P(A^S X^S, L^S X^S | X^S) P(X^S), \quad P_T^F = P(A^T X^T, L^T X^T | X^T) P(X^T).
\end{equation}
Then, the KL divergence between the feature distributions satisfies:
\begin{equation}
    D_{\text{KL}}(P_S^F \| P_T^F) \leq D_{\text{KL}}(A^S X^S \| A^T X^T) + D_{\text{KL}}(X^S \| X^T) + D_{\text{KL}}(L^S X^S \| L^T X^T).
\end{equation}
\end{corollary}

\begin{proof}
Using the chain rule for KL divergence, we decompose:
\begin{equation}
    D_{\text{KL}}(P_S^F \| P_T^F) = D_{\text{KL}}(P(A^S X^S, L^S X^S | X^S) P(X^S) \| P(A^T X^T, L^T X^T | X^T) P(X^T)).
\end{equation}
Applying the chain rule:
\begin{equation}
    D_{\text{KL}}(P_S^F \| P_T^F) = D_{\text{KL}}(P(X^S) \| P(X^T)) + \mathbb{E}_{P(X^S)} D_{\text{KL}}(P(A^S X^S, L^S X^S | X^S) \| P(A^T X^T, L^T X^T | X^T)).
\end{equation}
Assuming conditional independence between adjacency and Laplacian transformations:
\begin{equation}
    D_{\text{KL}}(P(A^S X^S, L^S X^S | X^S) \| P(A^T X^T, L^T X^T | X^T)) \leq D_{\text{KL}}(A^S X^S \| A^T X^T) + D_{\text{KL}}(L^S X^S \| L^T X^T).
\end{equation}
Thus, combining the results:
\begin{equation}
    D_{\text{KL}}(P_S^F \| P_T^F) \leq D_{\text{KL}}(A^S X^S \| A^T X^T) + D_{\text{KL}}(X^S \| X^T) + D_{\text{KL}}(L^S X^S \| L^T X^T).
\end{equation}
This completes the proof. \qed
\end{proof}

 \begin{lemma}\label{lemma:general-deterministic}
[Domain Adaptation Bound for Deterministic Classifiers]
    Let $ \Phi $ be a family of classification functions. For any classifier $ \phi $ in $ \Phi $, and for any parameters $ \lambda > 0 $ and $ \gamma \geq 0 $, consider any prior distribution $ P $ over $ \Phi $ that is independent of the training data $ \mathcal{V}^S $. With a probability of at least $ 1 - \delta $ over the sample $ Y^S $, for any distribution $ Q $ on $ \Phi $ 
    such that
the following inequality holds:
\begin{align}
    \risk_T(\phi) \leq \hLg_S(\phi)& + \frac{1}{\lambda} \left[ 2(\KL(Q \| P) + 1) + \ln \frac{1}{\delta}\right]\\ & + \frac{\lambda}{4N_S} + D^{\gamma/2}_{S, T}(P;\lambda) \label{eq:general-deterministic}
\end{align}

 \end{lemma}

\begin{theorem}
\label{prop:DA-KL}
Let $ \Phi $ be a family of classification functions. For any classifier $ \phi \in \Phi $, and for any parameters $ \lambda > 0 $ and $ \gamma \geq 0 $, consider any prior distribution $ P $ over $ \Phi $ that is independent of the training data $ \mathcal{V}^S $. With probability at least $ 1 - \delta $ over the sample $ Y^S $, for any distribution $ Q $ on $ \Phi $, we have:
\begin{equation}
    \begin{aligned}
        \risk_T(\phi) \leq \hLg_S(\phi) &+ \frac{1}{\lambda} \left[ 2(\KL(Q \| P) + 1) + \ln \frac{1}{\delta} \right] + \frac{\lambda}{4N_S} 
        + \frac{\lambda \rho C C_0}{\sqrt{2\pi}\sigma\cdot N_S\cdot N_T}\cdot\\ 
        & 
        \left[\sqrt{D_{\text{KL}}(A^S X^S \| A^T X^T)} +
            \sqrt{D_{\text{KL}}(X^S \| X^T)} +
            \sqrt{D_{\text{KL}}(L^S X^S \| L^T X^T)} +\sqrt{D_{\text{KL}}(P_S^H \| P_T^H)} \right].
    \end{aligned}
\end{equation}
\end{theorem}
\begin{proof}
By Lemma~\ref{lemma:general-deterministic}, the domain adaptation bound is given by:
\begin{equation}
    \risk_T(\phi) \leq \hLg_S(\phi) + \frac{1}{\lambda} \left[ 2(\KL(Q \| P) + 1) + \ln \frac{1}{\delta} \right] + \frac{\lambda}{4N_S} + D^{\gamma/2}_{S, T}(P;\lambda).
\end{equation}
From Proposition~\ref{equ: Proposition}, we substitute the bound on $ D^{\gamma/2}_{S, T}(P;\lambda) $:
\begin{equation}
    D^{\gamma/2}_{S, T}(P;\lambda) \leq \frac{\lambda \rho C C_0}{\sqrt{2\pi}\sigma\cdot N_S\cdot N_T} \left[\sqrt{D_{\text{KL}}(P_S^F \| P_T^F)} +
    \sqrt{D_{\text{KL}}(P_S^H \| P_T^H)} \right].
\end{equation}
Applying Corollary~\ref{cor:KL-decomposition} to decompose $ D_{\text{KL}}(P_S^F \| P_T^F) $, we obtain:
\begin{equation}
    D_{\text{KL}}(P_S^F \| P_T^F) \leq D_{\text{KL}}(A^S X^S \| A^T X^T) + D_{\text{KL}}(X^S \| X^T) + D_{\text{KL}}(L^S X^S \| L^T X^T).
\end{equation}
Similarly, for the heterophily-based KL divergence:
\begin{equation}
    D_{\text{KL}}(P_S^H \| P_T^H) \leq D_{\text{KL}}(A^S X^S \| A^T X^T) + D_{\text{KL}}(X^S \| X^T) + D_{\text{KL}}(L^S X^S \| L^T X^T).
\end{equation}
Thus, we obtain:
\begin{equation}
    D^{\gamma/2}_{S, T}(P;\lambda) \leq \frac{\lambda \rho C C_0}{\sqrt{2\pi}\sigma\cdot N_S\cdot N_T} \left[\sqrt{D_{\text{KL}}(A^S X^S \| A^T X^T)} +
            \sqrt{D_{\text{KL}}(X^S \| X^T)} +
            \sqrt{D_{\text{KL}}(L^S X^S \| L^T X^T)} \right].
\end{equation}
Substituting this into the original bound for $ \risk_T(\phi) $, we conclude:
\begin{equation}
    \begin{aligned}
        \risk_T(\phi) \leq \hLg_S(\phi) &+ \frac{1}{\lambda} \left[ 2(\KL(Q \| P) + 1) + \ln \frac{1}{\delta} \right] + \frac{\lambda}{4N_S} 
        \\ 
        &+ \frac{\lambda \rho C C_0}{\sqrt{2\pi}\sigma\cdot N_S\cdot N_T} 
        \left[\sqrt{D_{\text{KL}}(A^S X^S \| A^T X^T)} +
            \sqrt{D_{\text{KL}}(X^S \| X^T)} +
            \sqrt{D_{\text{KL}}(L^S X^S \| L^T X^T)} \right].
    \end{aligned}
\end{equation}
This completes the proof. \qed
\end{proof}

\section{Experimental Setup}
The experiments are implemented in the PyTorch platform using an Intel(R) Xeon(R) Silver 4210R CPU @ 2.40GHz, and GeForce RTX A5000 24G GPU.
