% We continue by modeling the communication between the edge server and VR users, as well as users' buffer dynamics.




\begin{figure}[t]
    \centering
    \includegraphics[width=.9\linewidth, trim={4.3cm 5.3cm 4.3cm 3.8cm},clip]{figs/multi-layer-video-model.pdf}
    \caption{Multi-layer $360^\circ$ video model (lower left corner): Viewport-specific enhancement layers combined with a wide $360^\circ$ panorama baseline layer are transmitted to a VR headset via a mmWave wireless link. As the number of added enhancement layers increases, the video bitrate and the video quality delivered to the VR user increase.}
    \label{fig:video-model}
    % \vspace{-.25in}
