\textbf{Policy Optimization:}
In the policy training phase, we update the actor and critic networks.
The policy network is trained by dual-clip proximal policy optimization (PPO) \cite{schulman-2017-proximal}:
\begin{equation}
\small
\label{eq:d-clip-loss}
    \begin{aligned}
        \mathcal{L}^{DClip} = \hat{\mathbb{E}}
            \Big[ \indicator(\hat{A}^m < 0)\max(\mathcal{L}^{PPO}, c\hat{A}^m) + 
            \indicator(\hat{A}^m \geq 0)\mathcal{L}^{PPO} \Big].
    \end{aligned}
\end{equation}
Here, $\indicator(.)$ is a binary indicator function and $\hat{A}^m = r^m + \gamma V_{\omega_v}(s^{m+1}) - V_{\omega_v}(s^m)$ is the advantage function calculated based on the current state value estimate and the discount factor $\gamma = 0.99$, and $\mathcal{L}^{PPO}$ is the surrogate vanilla PPO loss:
% function introduced in  \cite{schulman-2017-proximal} 
% that is:
\begin{equation}
\small
\label{eq:ppo-loss}
    \begin{aligned}
        \mathcal{L}^{PPO} = \mathcal{L}^{Clip}(\pi_{\omega}, \hat{A}^m) + \kappa H_{\omega}(s^m) + \mathcal{L}^{Value},
    \end{aligned}
\end{equation}
where $H_{\omega}(s^m)$ is the entropy of all the policies and $\kappa$ is the entropy weight.
The entropy loss and its associated weight balance the trade-off between exploration and exploitation in the learning process.
$\mathcal{L}^{Value}$ is the value network loss:
\begin{equation}
\small
\label{eq:value-loss}
    \begin{aligned}
        \mathcal{L}^{Value} &= \mathbb{E}_m\left[ 
            \frac{1}{2}
            (V_{\omega_v}(s^m) - V_{targ}(s^m))^2 
        \right],
    \end{aligned}
\end{equation}
and $\mathcal{L}^{Clip}$ is the single-clip policy loss defined as: 
\begin{equation}
\small
\label{eq:clip-loss}
    \begin{aligned}
        \mathcal{L}^{Clip} = \min \Big[ &\rho(\pi_{\omega}, \pi_{\omega_{old}}) \odot \hat{A}^m, \\ 
 & clip(\rho(\pi_{\omega}, \pi_{\omega_{old}}), 1 \pm \varepsilon) \odot \hat{A}^m \Big].
    \end{aligned}
\end{equation}
Here $\odot$ is the element-wise multiplication, and $\rho(\pi_{\omega}, \pi_{\omega_{old}}) \odot \hat{A}^m$ measures the gained/lost reward as the policy for each user changes, which determines how a change in one user's policy affects other users reward, (\ie perceived QoE).
The change in users' policies w.r.t. their old policy is measured via 
% $\rho(.,.)$
$\rho(\pi_{\omega}, \pi_{\omega_{old}}) = \left[\rho_1, \rho_2, \dotsb, \rho_n \right]$, which is a vector of size $N$.
% that measures the changes in the new policy w.r.t. the old policy:
% \ie the joint probability ratio of the new policy to the old policy for all the users:
% \begin{equation*}
% \small
%     \begin{aligned}
%          \rho(\pi_{\omega}, \pi_{\omega_{old}}) = \left[\rho_1, \rho_2, \dotsb, \rho_n \right].
%     \end{aligned}
% \end{equation*}
Each element of this vector $\rho_i$ measures the changes for one user in the environment (\ie the joint probability ratio of the new policy to the old policy for both computation distribution and rate allocation action):
\begin{equation}
\label{eq:rho-i}
\small
    \begin{aligned}
        \rho_i =
        % \prod_{n=1}^{N}
        \frac{
            \pi_{\omega}^{\phi} (\phi^m_i|s^m)
        }{
            \pi_{\omega_{old}}^{\phi} (\phi^m_i|s^m)
        } 
        % \odot
        \frac{
            \pi_{\omega}^{e} (e^m_i|s^m)
        }{
            \pi_{\omega_{old}}^{e} (e^m_i|s^m)
        }.
    \end{aligned}
\end{equation}
% $$
% \normalsize
% Note that both $\rho(.,.)$ and $\hat{A}_m$ are vectors of size $N$

\textbf{Auxiliary Training Phase:}
In the auxiliary phase, we further optimize the actor and critic networks according to a joint loss function $\mathcal{L}^{Joint}$ on all the experiences.
The joint loss function $\mathcal{L}^{Joint}$ is composed of a behavioral cloning loss and an auxiliary value loss:
% Due to space limitation, details on auxiliary training phase are omitted.
% Interested readers can refer to \cite{cobbe-2020-ppg}.
% for more details.
% on the auxiliary training phase.
% The $\mathcal{L}^{Value}$, in Eq. \eqref{eq:ppo-loss}, updates the critic network by minimizing the mean squared error between the state value estimate by the critic and the target state value:
% % We incorporate a similar loss function to update the critic network as well during the policy training phase.
% \begin{equation}
% \small
% \label{eq:value-loss}
%     \begin{aligned}
%         \mathcal{L}^{Value} &= \mathbb{E}_m\left[ 
%             \frac{1}{2}
%             (V_{\omega_v}(s_m) - V_{targ}(s_m))^2 
%         \right].
%     \end{aligned}
% \end{equation}
% During the auxiliary phase, we further optimize the actor network according to the joint objective function, which composed of behavioral cloning loss and auxiliary value loss:
\begin{equation}
\small
\label{eq:joint-loss}
    \begin{aligned}
        \mathcal{L}^{Jonit} = 
        \mathbb{E}_m
        \Bigg[ 
            % \sum_{n=1}^N 
            & \mathbf{KL} \left(\pi_{\omega_{old}}^{\phi} (s^m), \pi_{\omega}^{\phi} (s^m)\right)  \\ 
            & + \mathbf{KL} \left(\pi_{\omega_{old}}^{e} (s^m), \pi_{\omega}^{e} (s^m)\right) 
            % & \mathbf{KL} \left(\pi_{\omega_{old}}^{\theta^n} (s_m), \pi_{\omega}^{\theta^n} (s_m)\right)
            % \mathbf{KL} \left[\pi_{\omega_{old}}^{\zeta^n} (s_m), \pi_{\omega}^{\zeta^n} (s_m)\right]
        \Bigg] 
        + \mathcal{L}^{Aux}.
    \end{aligned}
\end{equation}
Here, $\mathbf{KL}(.,.)$ is the behavioral cloning loss, representing the KL-divergence between the original policy and the updated policy.
The $\mathcal{L}^{Aux}$, in Eq. \eqref{eq:joint-loss}, updates the auxiliary value by minimizing the mean squared loss function:
\begin{equation}
\small
\label{eq:aux-loss}
    \begin{aligned}
        \mathcal{L}^{Aux} &= \mathbb{E}_m\left[ 
            \frac{1}{2}
            (V_{\omega}(s^m) - V_{targ}(s^m))^2 
        \right].
    \end{aligned}
\end{equation}
% where $V_{targ} (s_m) = r_m + \gamma V_{\omega_v}(s_{m+1})$ is the current state value estimate using the critic network.



