\begin{algorithm}[t]
\caption{MTRC Training Process}
\label{alg:training-alg}
% \textbf{Inputs:} \\
% \hspace*{\algorithmicindent}  $Q$ \;\,: A neural network initialized by $\theta_0$ \\
% \hspace*{\algorithmicindent}  $\mathcal{E}$ \,\,: Number of training epochs \\
