\begin{algorithmic}[1]
    \STATE Initialize $\mathcal{B} \leftarrow \varnothing$, $\mu_0 = 0.1$, $\mu_1 = 0.1$, $\lambda = 0.01$
    \FOR{episode $=1,2,...$}
    \FOR{$m=1,2,...$}
        \STATE $\phi^m \sim \pi_{\omega}^{\phi} (\phi^m|s^m)$ 
        \COMMENT{Sample actions}
        % \COMMENT{Sample computation distribution action for all users}
        \STATE $e^m \sim \pi_{\omega}^{e} (e^m|s^m)$ 
        % \COMMENT{Sample rate adaptation action for all users}
        \STATE $s^{m+1}$, $r^{m+1}$  = ACT($\phi^m$, $e^m$) 
        % \COMMENT{Perform selected actions and update users state}
        \COMMENT{Apply actions}
        \STATE $\mathcal{B} \leftarrow \mathcal{B} \cup \{s^m, (\phi^m, e^m), r^{m+1}, s^{m+1}, V_{targ}(s^m)\}$ 
        % \COMMENT{ Store the transition in replay buffer}
        % \STATE $\bar{\mathcal{B}} \leftarrow \bar{\mathcal{B}} \cup \{s^m, V_{targ}(s^m)\}$ \COMMENT{Store the target values for auxilary phase}
    \ENDFOR
    \STATE $\mu_0 \leftarrow \mu_0 + \lambda \nabla_{\mu_0}\mathcal{L}^{\mu_0}$ 
    \COMMENT{Update QoE coefficients}
    \STATE $\mu_1 \leftarrow \mu_1 + \lambda \nabla_{\mu_1}\mathcal{L}^{\mu_1}$ 
    % \COMMENT{Update quality variation coefficient}
    \IF{episode $ \%$ $N_{update} = 0 $}
        \FOR{$i = 1,2,..., N_{Policy}$} 
        \COMMENT{Policy training phase}
            \STATE Optimize $\mathcal{L}^{DClip}$ (\ie Eq. \eqref{eq:d-clip-loss}) w.r.t. $\omega, \omega_{v}$
            % , on a random batch from $\mathcal{B}$ 
        \ENDFOR
        \FOR{$i = 1,2,..., N_{aux}$} \COMMENT{Auxilary training phase}
            \STATE Optimize $\mathcal{L}^{Value}$ (\ie Eq. \eqref{eq:value-loss}) w.r.t. $\omega_v$
            % , on all data in $\mathcal{B}$ 
            \STATE Optimize $\mathcal{L}^{Joint}$ (\ie Eq. \eqref{eq:joint-loss}) w.r.t. $\omega$
            % , on all data in $\mathcal{B}$
        \ENDFOR
        \STATE $\mathcal{B} \leftarrow \varnothing$ \COMMENT{Clear replay buffer}
        \STATE $\omega_{old} \leftarrow \omega$, $\omega_{v_{old}} \leftarrow \omega_v$ \COMMENT{Update target network}
    \ENDIF
    \ENDFOR
\end{algorithmic}
