\section{Preliminaries}
\label{sec:preliminaries}

Throughout this section, we will consider a polynomial ODE system, that is, a system of differential equations
\begin{equation}\label{eq:mainode}
\bx' = \bp(\bx),
\end{equation}
where $\bx = \bx(t) = (x_1(t), \ldots, x_n(t))$ is a vector of unknown functions and $\bp = (p_1, \ldots, p_n)$ is a vector of $n$-variate polynomials $p_1, \ldots, p_n \in \mathbb{R}[\bx]$.

\begin{definition}[Quadratization]\label{def:quadr}
    For a system~\eqref{eq:mainode}, \emph{quadratization} is a pair consisting of
    \begin{itemize}
        \item a list of new variables
        \[
          y_1 = g_1(\bx), \ldots, y_m = g_m(\bx)
        \]
        \item and two lists 
        \[
        \bq_1(\bx, \by) = (q_{1, 1}(\bx), \ldots, q_{1, n}(\by)) \quad\text{ and }\quad \bq_2(\bx, \by) = (q_{2, 1}(\bx, \by), \ldots, q_{2, m}(\bx, \by))
        \]
        of $m + n$-variate polynomials in $\bx$ and $\by = (y_1, \ldots, y_m)$
    \end{itemize}
    such that  the degree of each of of $\bq_1$ and $\bq_2$ is at most two and 
    \begin{equation}\label{eq:resulting_quadr}
      \bx' = \bq_1(\bx, \by) \quad \text{ and } \quad \by' = \bq_2(\bx, \by).
    \end{equation}
    If all the polynomials $g_1, \ldots, g_m$ are monomials, the quadratization is called \emph{monomial quadratization}.
\end{definition}

Note that unlike, for example, \cite[Definition~1]{bychkov2021optimal}, by \emph{quadratization} we mean not just the set of new variables but also the quadratic ODE system~\eqref{eq:resulting_quadr}.
The reason for this is that, for a fixed set of new variables, there may be many different systems of the shape (see Example~\ref{ex:quadratization}) prescribed by~\eqref{eq:resulting_quadr} exhibiting different numerical behaviors (see Example~\ref{ex:stability}).

\begin{example}[Quadratization] \label{ex:quadratization}
    Consider the following scalar ODE
    \[
    x' = -x + x^3.
    \]
    Here we have $n = 1$ and $p_1(x) = -x + x^3$.
    Consider $y = g_1(x) = x^2$. 
    Then we can write
    \begin{align*}
    x' &= -x + x^3 = -x + xy,\\
    y' &= 2xx' = -2x^2 + 2x^4 = -2y + 2y^2.
    \end{align*}
    Therefore, one possible quadratization is given by
    \[
     g_1(x) = x^2, \quad q_{1, 1}(x, y) = -x + xy, \quad q_{2, 1}(x, y) = -2y + 2y^2.
    \]
    As we have mentioned above, there may be different $\bq$'s corresponding to the same $\bg$.
    In this example, we could take, for example, $q_{2, 1} = -2y + 2y^2 + 2(y - x^2) = -2x^2 + 2y^2$ or  $q_{2, 1} = y - 3x^2 + 2y^2$.
    As we will see in Example~\ref{ex:stability}, such choices may have a dramatic impact on the numerical properties of the resulting ODE system.
\end{example}

\begin{definition}[Equilibrium]
    For a polynomial ODE system~\eqref{eq:mainode}, a point $\bx^\ast \in \mathbb{R}^n$ is called an \emph{equilibrium} if $\bp(\bx^\ast) = 0$.
\end{definition}

\begin{definition}[Dissipativity]
    An ODE system~\eqref{eq:mainode} is called \emph{dissipative} at an equilibrium point $\bx^\ast$ if all the eigenvalues of the Jacobian $J(\bp)|_{\bx = \bx^\ast}$ of $\bp$ and $\bx^\ast$ have negative real part.

    It is known that a system which is dissipative at an equilibrium point $\bx^\ast$ is~\emph{asymptotically stable} at $\bx^\ast$~\cite[Theorem 8.2.2]{Hubbard}, that is, any trajectory starting in a small enough neighborhood of $\bx^\ast$ will converge to $\bx^\ast$ exponentially fast.

    Note that if $\bx^\ast = 0$, then the Jacobian at this point is simply the matrix of the linear part of $\bp(\bx)$.
\end{definition}

Assume that $\bx^\ast \in \mathbb{R}^n$ is an equilibrium of $\bx' = \bp(\bx)$, and consider a quadratization of this system as in Definition~\ref{def:quadr}.
Then a direct computation shows that $(\bx^\ast, \bg(\bx^\ast))$ is an equilibrium point of the resulting quadratic system~\eqref{eq:resulting_quadr}.

\begin{definition}[Dissipative quadratization]
    Assume that a system~\eqref{eq:mainode} is dissipative at an equilibrium point $\bx^\ast \in \mathbb{R}^n$.
    Then a quadratization given by $\bg, \bq_1$ and $\bq_2$ (see Definition~\ref{def:quadr}) is called~\emph{dissipative at~$\bx^\ast$} if the system
    \[
      \bx' = \bq_1(\bx, \by), \quad \by' = \bq_2(\bx, \by)
    \]
    is dissipative at a point $(\bx^\ast, \bg(\bx^\ast))$.
\end{definition}

The following example shows that, even for the same new variables $\by = \bg(\bx)$, different quadratizations may have significantly different stability properties. 

\begin{example}[Stable and unstable quadratizations]\label{ex:stability} 
Consider the scalar ODE $x' = -x + x^3$ from Example \ref{ex:quadratization}. 
We have already found a quadratization for it using a new variable $y = g_1(x) = x^2$ with the resulting quadratic system being
\begin{equation}\label{eq:stable}
    x' = -x + xy\quad \text{ and } y' = -2y + 2y^2.
\end{equation}
We notice that we can add/subtract $y - x^2$ with any coefficients from the right-hand sides of the system. 
For example, we can obtain:
\begin{equation}\label{eq:unstable}
    x' = -x + xy\quad \text{and} \quad y' = -2y + 2y^2 + 12(y - x^2) = 10y - 12x^2 + 2y^2.
\end{equation}
Both systems above are quadratizations of the original system and, thus, mathematically, for any initial condition $(x_0, y_0)$ satisfying $y_0^2 = x_0^2$, they must follow the same trajectory.
However, \eqref{eq:stable} is stable at $(0, 0)$ while~\eqref{eq:unstable} is not.
By numerically integrating them, we can observe in Figure~\ref{fig:stability} that in practice \eqref{eq:stable} reflects the dynamics of the original equation accurately and~\eqref{eq:unstable} heavily suffers from numerical instability.

\begin{figure}[h!]
    \centering
    \includegraphics[width=1.0\textwidth]{figures/example2.png}
    \caption{Plot of the original equation, \eqref{eq:stable}, and~\eqref{eq:unstable} with initial condition $\mathcal{X}_0 = [x_{0}, y_{0}=x_{0}^{2}]=[0.1, 0.01]$. Numerical method: ``LSODA'' (uses hybrid Adams/BDF method with automatic stiffness detection) in scipy.integrate.solve\_ivp package \cite{hindmarsh1983odepack,petzold1983automatic}.}
    \label{fig:stability}
\end{figure}
\end{example}

