\section{Existence of dissipativity-preserving quadratizations}\label{sec:theory}

The main result of this section is the following theorem.
Its proof is constructive and is used to design an algorithm in Section~\ref{sec:alg}.

\begin{theorem}\label{thm:main}
    For every polynomial ODE system $\bx' = \bp(\bx)$, there exists a quadratization that is dissipative at all the dissipative equilibria of $\bx' = \bp(\bx)$.
\end{theorem}

\begin{remark}
    In fact, the key ingredients of the proof, Propositions~\ref{prop:inner_exists} and~\ref{prop:gauging}, imply a stronger statement: for every set of finitely many equilibria, there is a quadratization such that the number of nonnegative eigenvalues of the Jacobian of the quadratic system at these points is the same as for the original system.
\end{remark}

The rest of the section will be devoted to proving Theorem~\ref{thm:main}. 
The main technical notion will be an \emph{inner-quadratic} set of polynomials.
\begin{definition}[Inner-quadratic set]\label{def:inner_quadr}
As finite set $g_1(\bx), \ldots, g_m(\bx) \in \mathbb{R}[\bx]$ of nonconstant polynomials in $\bx = (x_1, \ldots, x_n)$ is called \emph{inner-quadratic} if, for every $1 \leqslant i \leqslant m$, there exist (not necessarily distinct) $a, b \in \{x_1, \ldots, x_n, g_1, \ldots, g_m\}$ such that $g_i = ab$.

A quadratization will be called~\emph{inner-quadratic} if the set of new variables $\bg$ is inner-quadratic.
We will also always assume that the new variables are sorted by degree, that is, $\deg g_1 \leqslant \deg g_2 \leqslant \ldots \leqslant \deg g_m$.
\end{definition}

The rationale behind the notion of inner-quadratic quadratization is that at most quadratic relations between the new variables give us the flexibility to ``tune'' the right-hand side of the resulting quadratic system in the same fashion as we added a multiple of $y - x^2$ in~Example~\ref{ex:stability}.
These additional terms force the trajectory to stay on the image of the map $\bx \to (\bx, \by)$, on which the properties of the original dynamics (such as dissipativity) are preserved.
The following definition formalizes this observation.

\begin{definition}[Stabilizers]\label{def:stabilizer}
    Consider a polynomial ODE system $\bx' = \bp(\bx)$ and its inner-quadratic quadratization given by $m$ new variables $\by = \bg(\bx)$ and right-hand side $\bq_1(\bx, \by), \bq_2(\bx, \by)$ of the resulting quadratic system as in Definition~\ref{def:quadr}.
    For every $1 \leqslant i \leqslant m$, by the definition of inner-quadratic set, there exist $a_i, b_i \in \{\bx, y_1, \ldots, y_{i - 1}\}$ such that the equality $y_i = a_ib_i$ holds if we replace each $y_j$ with $g_j(\bx)$.
    We define \emph{the $i$-th stabilizer} by $h_i(\bx, \by) := y_i - a_ib_i$.

    Since each stabilizer is at most quadratic and vanishes under the substitution $\by = \bg(\bx)$, adding any stabilizer to any of $\bq_1, \bq_2$ still yields a quadratization of $\bx' = \bp(\bx)$.
\end{definition}

\begin{example}[Stabilizers]\label{eg:stabilizer_example}
   Let us give an example of the stabilizers. Consider a system:
    $$
    x_1^{\prime}=-3 x_1+x_2^4 , \quad 
    x_2^{\prime}=-2 x_2+x_1^2.
    $$
    By applying \textbf{Algorithm \ref{alg:inner-quadratization}}, we introduce the following new variables to obtain an inner-quadratic quadratization:
    $$
    y_1=x_1^2, \quad
    y_2=x_2^2, \quad
    y_3=x_1 x_2, \quad
    y_4=x_2^3 = x_{2}y_{2}.
    $$
    Then the corresponding stabilizers, according to the definition above, will be:
    \begin{align*}
    h_{1}(\bx, \by) &=y_1-x_1^2, & h_{2}(\bx, \by) &=y_2-x_2^2,\\
    h_{3}(\bx, \by) &=y_3-x_1 x_2, &
    h_{4}(\bx, \by) &= y_4-x_{2}y_{2}
    \end{align*}
\end{example}

Theorem~\ref{thm:main} follows directly from the following two properties of inner-quadratic quadratizations:
\begin{itemize}
    \item every polynomial ODE system has an inner-quadratic quadratization (Proposition~\ref{prop:inner_exists});
    \item for any inner-quadratic quadratization, one can modify the right-hand sides of the quadratic system (but not the new variables) using the stabilizers in order to obtain a dissipativity-preserving quadratization (Proposition~\ref{prop:gauging}).
\end{itemize}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\begin{proposition}\label{prop:inner_exists}
    Every polynomial ODE system $\bx' = \bp(\bx)$ admits an inner-quadratic quadratization.
    Furthermore, it can be chosen to be a monomial quadratization.
\end{proposition}

\begin{proof}
    We will show that the quadratization which is typically used to prove the existence of a quadratization for every polynomial ODE system (see, e.g.~\cite[Theorem~1]{Carothers2005}) is in fact inner-quadratic.
    For every $1 \leqslant i \leqslant n$, we introduce $d_i = \max\limits_{1 \leqslant j \leqslant n} \deg_{x_i} p_j$.
    Then it is proven in~\cite[Theorem~1]{Carothers2005}  that the following set of new variables yields a quadratization of $\bx' = \bp(\bx)$:
    \[
    \mathcal{M} = \{x_1^{i_1}\ldots x_n^{i_n} \mid \forall j\colon 0 \leqslant i_j \leqslant d_j, \; \sum i_j > 1\}.
    \]
    Let $g \in \mathcal{M}$. Then there exists $1 \leqslant j \leqslant n$ such that $\deg_{x_j} g > 0$. 
    Then we can write $g = (g / x_j) \cdot x_j$, where $g / x_j$ is either in $\mathcal{M}$ or belongs to $\{x_1, \ldots, x_n\}$.
    Thus, $\mathcal{M}$ is an inner-quadratic set.
\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\begin{proposition}\label{prop:gauging}
    Consider a system $\bx' = \bp(\bx)$ and its inner-quadratic quadratization defined by new variables $\bg(\bx)$ and the new right-hand side $\bq_1, \bq_2$ as in Definition~\ref{def:quadr}.
    Let $\bx_1^*, \ldots, \bx_\ell^*$ be a finite subset of the equilibria of the system.
    Then there exist vectors of quadratic polynomials $\br_1(\bx, \by), \br_2(\bx, \by)$ such that $\bg, \br_1, \br_2$ define a quadratization for which the eigenvalues of the Jacobian at each equilibrium point of the form $(\bx_i^\ast, \bg(\bx_i^*))$ are the union of the eigenvalues of $J(\bp)|_{\bx = \bx_i^*}$ and a set of numbers with negative real part.
\end{proposition}

\begin{corollary}\label{cor:gauging}
    Consider a system $\bx' = \bp(\bx)$ and its inner-quadratic quadratization defined by new variables $\bg(\bx)$ and the new right-hand side $\bq_1, \bq_2$ as in Definition~\ref{def:quadr}.
    Then there exist vectors of quadratic polynomials $\br_1(\bx, \by), \br_2(\bx, \by)$ such that $\bg, \br_1, \br_2$ define a quadratization which is dissipative at every dissipative equilibrium of $\bx'=\bp(\bx)$.
\end{corollary}

\begin{proof}[Proof of Corollary~\ref{cor:gauging}]
    Since each dissipative equilibrium of the system is an isolated root of the polynomial system obtained by equating the right-hand side to zero, there are only finitely many of them.
    So we apply Proposition~\ref{prop:gauging} to this finite set of equilibria and obtain the desired quadratization.
\end{proof}

Before proving Proposition~\ref{prop:gauging}, we establish a useful linear-algebraic lemma.

\begin{lemma}\label{lem:add_triang}
    Let $A \in \mathbb{R}^{n\times n}$ be a square matrix and $B \in \mathbb{R}^{n\times n}$ be an upper triangular matrix with ones on the diagonal.
    Then there exists $\lambda_0 \in \mathbb{R}$ such that, for every $\lambda > \lambda_0$, the real parts of all the eigenvalues of $A - \lambda B$ are negative.
\end{lemma}

\begin{proof}
    Consider the characteristic polynomial of $A - \lambda B$.
    It can be written as 
    \[
    \operatorname{det}(A - \lambda B - t I) = (-\lambda)^n \operatorname{det} (B - A/\lambda + (t/\lambda I)).
    \]
    We set $T = t/\lambda$ and rewrite the latter determinant as $Q(T, 1/\lambda) := \operatorname{det}((B + T \cdot I) - A/\lambda)$.
    Since $Q$ is the determinant of a matrix with the entries linear in $T$ and $1/\lambda$, it is a bivariate polynomial in $T$ and $1/\lambda$ of total degree at most $n$.
    Furthermore, if we set $\lambda = \infty$ (equivalently, if we set $1/\lambda = 0$), we have $Q(T, 0) = \operatorname{det}(B + T\cdot I)$.
    Since $B$ is upper-triangular with ones on the diagonal, this determinant is equal to $\operatorname{det}(B + T\cdot I) = (T + 1)^n$, so $Q(T, 1/\lambda)$ can be written as $Q(T, 1/\lambda) = (T + 1)^n + \frac{1}{\lambda} p\left(T + 1, \frac{1}{\lambda}\right)$, where $p$ is a bivariate polynomial of the total degree at most $n - 1$ in $T + 1$ and $\frac{1}{\lambda}$.
    Let $C$ be an upper bound for the absolute value of the coefficients of $p$. 
    Then, for $\lambda > 1$, we can bound:
    \[
     \left\lvert p\left(T + 1, \frac{1}{\lambda}\right)\right\rvert < C n^2 \max(|T + 1|^{n - 1}, 1). 
    \]
    Let $T_0$ be any root of $Q(T, 1/\lambda)$.
    Then we have
    \[
     |T_0 + 1|^n \leqslant \frac{1}{\lambda} C n^2 \max(|T_0 + 1|^{n - 1}, 1). 
    \]
    Let us take $\lambda > Cn^2$.
    Then
    \[
    |T_0 + 1|^n < \max(|T_0 + 1|^{n - 1}, 1) \implies |T_0 + 1| < 1.
    \]
     So, in this case, the real part of any root of $Q$ will be negative.
    Then the same is true for the characteristic polynomial of $A - \lambda B$ because these two polynomials differ by scaling by a positive number $\lambda$.
    Therefore, $\lambda_0$ can be taken to be $\max(1, Cn^2)$.
\end{proof}

We will also use the following folklore analytic lemma.
\begin{lemma}\label{lem:conjugate}
    Let $\bx' = \Bf(\bx)$ a system of polynomial differential equations of dimension $n$ with an equilibrium point $\bx^\ast$.
    Let $\varphi \colon \mathbb{R}^n \to \mathbb{R}^n$ be an invertile change of coordinates, and let $\by' = \bg(\by)$ be the image of the system under the coordinate change. 
    Then the matrices $J_\bx(\Bf)|_{\bx = \bx^\ast}$ and $J_{\by}(\bg)|_{\by = \varphi(\bx^\ast)}$ are conjugate.
    In particular, they have the same eigenvalues.
\end{lemma}
\begin{proof}
    By the chain rule, we have
    \[
    \by' = (\varphi(\bx))' = J_{\bx}(\varphi) \bx' = J_{\bx}(\varphi)|_{\bx = \varphi^{-1}(\by)} f(\varphi^{-1}(\by)) = \bg(\by).
    \]
    Then we can write $J_\by(\bg)$ as
    \[
    J_{\bx}(\varphi)|_{\bx = \varphi^{-1}(\by)} J_{\bx}(f)|_{\bx = \varphi^{-1}(\by)} J_{\by}(\varphi^{-1}) + \sum\limits_{i = 1}^n A_i f_i(\varphi^{-1}(\by)),
    \]
    where $A_i$ is the Jacobian of the $i$-th column of $J_{\bx}(\varphi)|_{\bx = \varphi^{-1}(\by)}$.
    If we plug $\varphi(\bx^\ast)$ for $\by$, since $\Bf(\bx^\ast) = 0$, the latter sum will vanish, so we get
    \[
    J_{\bx}(\varphi)|_{\bx = \bx^\ast} J_{\bx}(f)|_{\bx = \bx^\ast} J_{\by}(\varphi^{-1})|_{\by = \varphi(\bx^{\ast})}.
    \]
    By the chain rule, the matrices $J_{\bx}(\varphi)|_{\bx = \bx^\ast}$ and $J_{\by}(\varphi^{-1})|_{\by = \varphi(\bx^{\ast})}$  are inverses to each other, so the Jacobians are indeed conjugated.
\end{proof}

\begin{proof}[Proof of Proposition~\ref{prop:gauging}]
    Before starting the proof, we would like to point at Example~\ref{eg:compute_proof2} in the Appendix illustrating the main steps of the proof.

    We define a map $\varphi\colon\mathbb{R}^{n + m} \to \mathbb{R}^{n + m}$ from a space with coordinates $(\bx, \by)$ to a space with coordinates $(\bx, \bz)$, where $\bz = (z_1, \ldots, z_m)$, by
    \begin{align*}
    &\varphi_i(\bx, \by) = x_i \quad \text{ for } 1 \leqslant i \leqslant n,\\
    &\varphi_{n + j}(\bx, \by) = y_j - g_j(\bx)\quad \text{ for } 1\leqslant j \leqslant m.
    \end{align*}
This map is invertible with the inverse given by $(\varphi^{-1})_i(\bx, \bz) = x_i$ for $1 \leqslant i \leqslant n$ and $(\varphi^{-1})_{n + j}(\bx, \bz) = z_j + g_j(\bx)$ for $1 \leqslant j \leqslant m$, so $\varphi$ is bijective.
Note that $\varphi(\bx^\circ, \bg(\bx^\circ)) = (\bx^\circ, \mathbf{0})$ for every $\bx^\circ \in \mathbb{R}^n$.
We apply a change of coordinates defined by $\varphi$ to the quadratic system~$\bx' = \bq_1(\bx, \by), \; \by' = \bq_2(\bx, \by)$ and obtain a (not necessarily quadratic) system of the form:
\begin{equation}\label{eq:transformed}
  \bx' = \widetilde{\bq}_1(\bx, \bz) \quad \text{ and } \quad \bz' = \widetilde{\bq}_2(\bx, \bz),
\end{equation}
where $\widetilde{q}_1 = q_1(\bx, \bz + \bg(\bz))$ and $\widetilde{q}_2$ can be found using the chain rule as follows:
\begin{equation}\label{eq:qtilde}
\bz' = (\by - \bg(\bx))' = q_2(\bx, \bz + \bg(\bx)) - J_{\bx}(\bg) \bx' = q_2(\bx, \bz + \bg(\bx)) - J_{\bx}(\bg) q_1(\bx, \bz + \bg(\bx)).
\end{equation}
Since the variety $\{(\bx^\circ, \bg(\bx^\circ)) \mid \bx^\circ \in \mathbb{R}^n\}$ was an invariant variety of~$\bx' = \bq_1(\bx, \by), \; \by' = \bq_2(\bx, \by)$ by construction, the linear space $\{(\bx^\circ, \mathbf{0}) \mid \bx^\circ\in \mathbb{R}^n \}$ is invariant for~\eqref{eq:transformed} and the restriction of~\eqref{eq:transformed} to this space coincides with the original system~$\bx' = \bp(\bx)$.
This implies the following constraints on~$\widetilde{\bq}_1$ and~$\widetilde{\bq}_2$:
\begin{itemize}
    \item $\widetilde{\bq}_1(\bx, \bz) = \bp(\bx) + \mathcal{O}(\bz)$, where $\mathcal{O}(\bz)$ stands for a polynomial with each monomial containing at least one of the $\bz$;
    \item $\widetilde{\bq}_2(\bx, \bz) = \mathcal{O}(\bz)$.
\end{itemize}
Due to these constraints, for every $\bx^{\circ} \in \mathbb{R}^n$, the Jacobian of $(\widetilde{\bq}_1, \widetilde{\bq}_2)$ at $(\bx^\circ, \mathbf{0})$ is of the form
\begin{equation}\label{eq:Jac_extended}
J_{\bx, \bz}(\widetilde{\bq}_1, \widetilde{\bq}_2)|_{\bx = \bx^{\circ}, \bz = \mathbf{0}} = \begin{pmatrix}
    J_{\bx}(\bp)|_{\bx = \bx^\circ} & \ast \\
    0 & J_{\bz}(\widetilde{\bq}_2)|_{\bx = \bx^\circ, \bz = \mathbf{0}}
\end{pmatrix}
\end{equation}
Let $h_1(\bx, \by), \ldots, h_m(\bx, \by)$ be the stabilizers of the quadratization (see Definition~\ref{def:stabilizer}).
We take an arbitrary parameter $\lambda \in \mathbb{R}$ and consider $\bq_{2, \lambda}(\bx, \by)$ defined~by
\begin{equation}\label{eq:q2lambda}
  \bq_{2, \lambda}(\bx, \by) = \bq_{2}(\bx, \by) - \lambda \bh(\bx, \by).
\end{equation}
Since the $h_i$'s are stabilizers, $\bg, \bq_{1}, \bq_{2, \lambda}$ is a quadratization of the original system for any value of $\lambda$ (see Definition~\ref{def:stabilizer}).
By using $q_{2, \lambda}$ instead of $q_2$ in~\eqref{eq:qtilde}, we
obtain $\widetilde{\bq}_{2, \lambda} = \widetilde{\bq}_2 - \lambda \bh(\bx, \bz + \bg(\bx))$.
Then, as in~\eqref{eq:Jac_extended}, we get
\begin{equation}\label{eq:Jac_lambda}
J_{\bx, \bz}(\widetilde{\bq}_1, \widetilde{\bq}_{2, \lambda})|_{\bx = \bx^{\circ}, \bz = \mathbf{0}} = \begin{pmatrix}
    J_{\bx}(\bp)|_{\bx = \bx^\circ} & \ast \\
    0 & (J_{\bz}(\widetilde{\bq}_2) - \lambda J_{\bz}(\bh))|_{\bx = \bx^\circ, \bz = \mathbf{0}}
\end{pmatrix}
\end{equation}
Observe that, since every $g_i$ is of the form $z_i$ plus polynomial in $\bx$ and $z$'s with smaller indices, 
$J_{\bz}(\bh)$ is a lower-triangular matrix with ones on the diagonal.

Having such a convenient expression for the Jacobian, we consider the given equilibria $\bx^\ast_1, \ldots, \bx^\ast_\ell$.
For any $\bx^\circ \in \{\bx_1^\ast, \ldots, \bx_\ell^\ast\}$, the eigenvalues of the Jacobian~\eqref{eq:Jac_lambda} are the union of the eigenvalues of $J_{\bx}(\bp)|_{\bx = \bx^\circ}$ and the eigenvalues of $(J_{\bz}(\widetilde{\bq}_2) - \lambda J_{\bz}(\bh))|_{\bx = \bx^\circ, \bz = \mathbf{0}}$.
Applying Lemma~\ref{lem:add_triang} to $\ell$ pairs of matrices $A = J_{\bz}(\widetilde{\bq}_2)|_{\bx = \bx_i^\ast, \bz = 0}$ and $B = J_{\bz}(\bh)|_{\bx = \bx_i^\ast, \bz = 0}$, we choose $\lambda$ to be larger than any of the $\lambda_0$'s provided by the lemma.
Then all the eigenvalues of this block will also have negative real parts.
By Lemma~\ref{lem:conjugate}, the same true for the Jacobian of $\bx' = \bq_1(\bx, \by),\; \by' = \bq_{2, \lambda}(\bx, \by)$.
\end{proof}



\section{Algorithms} \label{sec:alg}

Based on the proof of Theorem~\ref{thm:main}, finding a dissipativity-preserving quadratization can be done in two following steps:
\begin{enumerate}[label=\textbf{(Step \arabic*)}, leftmargin=16mm]
    \item finding an inner-quadratic quadratization
    \item modifying the corresponding quadratic system to achieve dissipativity at the given equilibria.
\end{enumerate}
In this section, we give algorithms for both steps.
Section~\ref{sec:inner} shows how to modify the quadratization algorithm from~\cite{bychkov2021optimal} to search for inner-quadratic quadratizations.
Using this algorithm as a building block, we give a general algorithm for computing dissipativity-preserving quadratizations in Section~\ref{sec:many_equilibria}.

\subsection{Computing inner-quadratic quadratization}\label{sec:inner}
Our algorithm follows the general  \emph{Branch-and-Bound (B\&B)} paradigm ~\cite{morrison2016branch} and is implemented based on the optimal monomial quadratization algorithm from~\cite[Section 4]{bychkov2021optimal}.
Therefore, we will describe the algorithm briefly, mainly focusing on the differences with the algorithm from~\cite{bychkov2021optimal}.

We define each subproblem~\cite[Definition 3.3]{bychkov2021optimal} as a set of new monomial variables $\{y_1(\bx), \ldots, y_{\ell}(\bx)\}$, and the subset of the \textit{search space}~\cite[Definition 3.1]{bychkov2021optimal} for the subproblem will be the set of all \textit{quadratizations} including these new variables. 
To each subproblem $\{y_1(\bx), \ldots, y_{\ell}(\bx)\}$, the algorithm from~\cite{bychkov2021optimal} assigns a set of generalized variables $\mathrm{V}$ (new variables, $\bx$'s, and $1$) and a set of nonsquares $\mathrm{NS}$ (monomials in the right-hand side which are not quadratic in the generalized variables~\cite[Definition 4]{bychkov2021optimal}). 
Additionally, we define the set of non-inner-quadratic new variables $\mathrm{NQ}$ which consist of all the monomials among $y_1(\bx), \ldots, y_{\ell}(\bx)$ which are not quadratic in $\{y_1(\bx), \ldots, y_{\ell}(\bx), x_1, \ldots, x_n\}$.
In particular, a subproblem is an inner-quadratic quadratization \textit{if and only if} $\mathrm{NS}=\varnothing$ and $\mathrm{NQ}=\varnothing$.
Note that $\mathrm{NS}$ and $\mathrm{NQ}$ are disjoint since $\mathrm{NQ} \subseteq \mathrm{V}$ and $\mathrm{V} \cap \mathrm{NS} = \varnothing$. 
\begin{example}
The notation previously introduced will now be demonstrated through the system $x'=x^{4}+x^{3}$ (taken from~\cite[Example 4]{bychkov2021optimal}, to display the difference between two algorithms).
We consider a subproblem with one already added new variable $y_{1}(x) := x^{3}$ (so, $y_{1}'=3x^{2}x'=3x^{6}+3x^{5}$). 
In this case, we have
$$
V=\{1, x, x^{3}\}, \quad V^{2}= \left\{1, x, x^2, x^3, x^4, x^6\right\}, \quad NS=\{x^{5}\}, \quad \underline{{NQ}=\{x^{3}\}}.
$$
\end{example}

\indent The algorithm starts from the subproblem $\varnothing$. For every iteration, we select one element $m$ from $\mathrm{NS} \cup \mathrm{NQ}$ (using a heuristic score function~\cite[Section 4.1]{bychkov2021optimal}) and compute all the decompositions of the form $m=m_{1}m_{2}$, where $m_1$ and $m_2$ are monomials. 
If $m \in \mathrm{NS}$, for every such decomposition, we create a new subproblem by adding the elements of $\left\{m_1, m_2\right\} \backslash V$ and at least one new variable will be added due to the property of $\mathrm{NS}$. 
If $m \in \mathrm{NQ}$, we only do this for the decompositions with $m_1 \neq 1$ and $m_2\neq 1$.

We apply this operation recursively and stop when $\mathrm{NS} \cup \mathrm{NQ}=\varnothing$ for each branch. 
Therefore, we can find all the possible inner-quadratic quadratization of the system. 
To improve the efficiency, we do not consider branches with more new variables than in already found answers and use versions of domain-specific pruning rules from~\cite{bychkov2021optimal}. 
The algorithm is summarized as Algorithm~\ref{alg:inner-quadratization}.
{\small
\begin{algorithm}[!h]
\caption{Computing optimal inner-quadratic quadratization }\label{alg:inner-quadratization}
\begin{description}
    \item[Input] 
    \begin{itemize}
        \item[]
        \item[-] polynomial ODEs system~$\bx' = \bp(\bx)$.
        \item[-] a set of already chosen new variables $y_1(\bx), \ldots, y_{\ell}(\bx)$ (at the first call, $\varnothing$).
        \item[-] the order $N$ of the smallest inner-quadratic quadratization found so far (at the first call, $N = \infty$).
    \end{itemize}
    \item[Output] a more optimal inner-quadratic  quadratization containing $y_1(\bx), \ldots, y_{\ell}(\bx)$ if such quadratization exists.
\end{description}

\begin{enumerate}[label = \textbf{(Step~\arabic*)}, leftmargin=*, align=left, labelsep=2pt, itemsep=0pt]
    \item If $y_1(\bx), \ldots, y_{\ell}(\bx)$ is a inner-quadratic quadratization, that is, $\mathrm{NS}=\varnothing$ and $\mathrm{NQ}=\varnothing$, and $\ell < N$, \textbf{return} $y_1, \ldots, y_\ell$.
    \item Select the element $m \in \mathrm{NS} \cup \mathrm{NQ}$ with the smallest \textit{score}, compute all the decompositions $m=m_{1}m_{2}$ as a product of two monomials. If $m \in NQ$, we only consider the decompositions with $m_{1} \neq 1$ and $m_{2} \neq 1$.
    \item For each decomposition $m = m_1m_2$ from the previous step, we consider a subproblem $\{z_1, \ldots, z_\ell\} \cup (\{m_1, m_2\} \setminus V)$.
    If its size is less than $N$ and none of the pruning rules apply, we run recursively on this subproblem and update $N$ if a more optimal inner-quadratic quadratization has been found by the recursive call.
\end{enumerate}
\end{algorithm}}

