\subsection{Computing dissipativity-preserving quadratization}\label{sec:many_equilibria}

Based on the proof of Theorem~\ref{thm:main}, the main idea behind the search for dissipativity-preserving quadratization is to start with any inner-quadratic quadratization, and replace the right-hand side for the new variables, $\bq_2(\bx, \by)$, by $\bq_2(\bx, \by) - \lambda \bh(\bx, \by)$ (see~\eqref{eq:q2lambda}) for increasing values of $\lambda$ until the desired quadratization is found.
The detailed algorithm is given as Algorithm~\ref{alg:multi_dissipativity}, the proof of its correctness and termination is provided by Proposition~\ref{prop:algo_correctness}, and a step-by-step example is given in Example~\ref{ex:algo}.

{\small
\begin{algorithm}[!h]
\caption{Computing a quadratization dissipative at all provided equilibria}\label{alg:multi_dissipativity}
\begin{description}
    \item[Input] polynomial ODE system~$\bx' = \bp(\bx)$ and a list of its dissipative equilibria $\bx^\ast_1, \ldots, \bx_\ell^\ast$;
    \item[Output] a quadratization of the system which is dissipative at $\bx_1^\ast, \ldots, \bx_\ell^\ast$.
\end{description}

\begin{enumerate}[label = \textbf{(Step~\arabic*)}, leftmargin=*, align=left, labelsep=2pt, itemsep=0pt]
    \item\label{step:compute_quadr} Compute an inner-quadratic quadratization of~$\bx' = \bp(\bx)$ using \textbf{Algorithm~\ref{alg:inner-quadratization}}. Let the introduced variables be $y_1 = g_1(\bx), \ldots, y_m = g_m(\bx)$. Let $\bq_1(\bx, \by)$ and $\bq_2(\bx, \by)$ be the right-hand sides of the quadratic system as in Definition~\ref{def:quadr}.
    If the corresponding quadratic system is dissipative at $\bx_1^\ast, \ldots, \bx_\ell^\ast$, \textbf{return} it.
    \item\label{step:stabilizer} Construct the stabilizers $\bh(\bx, \by)$ for the quadratization from~\ref{step:compute_quadr} as in Definition~\ref{def:stabilizer}, and set $\lambda = 1$.
    \item\label{step:while} While \textbf{True}
    \begin{enumerate}
        \item\label{step:form_system} Construct a quadratic system $\Sigma_\lambda$
        \[
          \bx' = \bq_1(\bx, \by), \; \by' = \bq_2(\bx, \by) - \lambda \bh(\bx, \by).
        \]
        \item\label{step:check_return} Check if $\Sigma_\lambda$ is dissipative at $(\bx_i^\ast, \bg(\bx_i^\ast))$ for every $1 \leqslant i \leqslant \ell$ (using the Routh-Hurwitz criterion~\cite[Chapter~XV]{Gantmacher}).
        If yes, \textbf{return} quadratization defined by $\bg(\bx), \bq_1(\bx, \by), \bq_2(\bx, \by) - \lambda \bh(\bx, \by)$.
        Otherwise, set $\lambda = 2\lambda$.
    \end{enumerate}
\end{enumerate}
\end{algorithm}}

\begin{proposition}\label{prop:algo_correctness}
    Algorithm~\ref{alg:multi_dissipativity} always terminates and produces a correct output.
\end{proposition}

\begin{proof}
    We will start with proving the correctness. 
    Note that since $\bg, \bq_1, \bq_2$ computed in~\ref{step:compute_quadr} yield a quadratization of the input system, and $\bh$ vanishes if $\by$ is replaced with $\bg(\bx)$, then $\bg, \bq_1, \bq_2 - \lambda \bh$ yield a quadratization of the original system as well.
    Furthermore, if the algorithm returned at~\ref{step:check_return}, then this quadratization is dissipative at $\bx_1^\ast, \ldots, \bx_\ell^\ast$.

    The termination of the algorithm follows from the proof of Proposition~\ref{prop:gauging}.
    We observe that the constructed $\bq_2 - \lambda \bh$ is exactly $\bq_{2, \lambda}$ in the notation of the proof, and it is shown that there exists $\lambda_0$ such that, for every $\lambda > \lambda_0$, $\bg, \bq_1, \bq_{2, \lambda}$ is dissipative at $\bx_1^\ast, \ldots, \bx_\ell^\ast$.
    Since $\lambda$ in the algorithm is doubled on each iteration of the while loop, it will at some point exceed $\lambda_0$, and the algorithm will terminate.
\end{proof}

\begin{example}\label{ex:algo}
We will illustrate how Algorithm \ref{alg:multi_dissipativity} works with the following differential equation:
\begin{equation}\label{eq:large_lambda}
    x' = -x (x - a) (x - 2a)
\end{equation}
where $a$ is a positive scalar parameter. 
The system's equilibria are $0, a, 2a$, and, among them, $x=0$ and $x=2a$ are dissipative.
Regardless of the value of $a$, Algorithm~\ref{alg:inner-quadratization} called at~\ref{step:compute_quadr} will produce an inner-quadratic quadratization with one new variable $y = x^2$ and quadratic system:
\[
\begin{cases}
    x' = -xy + 3ax^{2} -2a^2x, \\
    y' = -2y^{2}+6axy-4a^2x^{2}
\end{cases}
\]
The stabilizer computed at~\ref{step:stabilizer} will be $h(x, y) = y - x^2$.

Now let us fix $a = 1$ and continue with~\ref{step:while}.
At~\ref{step:form_system}, we form a new quadratic system $\Sigma_\lambda$:
\[
\begin{cases}
    x' = -xy + 3x^{2} -2x, \\
    y' = -2y^{2}+6xy-4x^{2} - \lambda (y-x^{2})
\end{cases}
\]
For $\lambda = 1, 2, 4, 8, \ldots$ we check the eigenvalues of its Jacobian at points $(0, 0)$ and $(2, 4)$. 
The Jacobian of $\Sigma_\lambda$ is
\[
J=\left[\begin{array}{cc}
-y+6 x-2 & -x \\
6 y+2 \lambda x-8 x\;\; & -4 y-\lambda+6 x
\end{array}\right]
\]
The eigenvalues we get on different iterations of the while-loop are summarized in Table~\ref{tab:eigenvalues} (the ones with nonnegative real parts are bold).
