\section{Preliminaries}

\subsection{Notations and quantum divergences}

Let $\density(A)$ denote the set of all density operators on a finite-dimensional Hilbert space $\cH_A$. Let $\mathscr{L}(A)$ represent the set of all linear operators. Let $\HERM(A)$, $\PSD(A)$ and $\PD(A)$ be the set of all hermitian operators, positive semidefinite operators and positive definite operators on $\cH_A$, respectively. The set of completely positive maps from $\mathscr{L}(A)$ to $\mathscr{L}(B)$ is denoted by $\CP(A\!:\!B)$. A quantum channel $\cN_{A\to B}$ is a linear map from $\mathscr{L}(A)$ to $\mathscr{L}(B)$ that is both completely positive and trace-preserving. The set of all such maps is denoted by $\CPTP(A\!:\!B)$.  A quantum divergence is a functional $\DD:\density \times \PSD \to \RR$ that satisfies the data-processing inequality, characterizing the ``distinguishability'' or ``distance'' between two quantum states. There are a few quantum divergences used throughout this work.

\begin{definition}(Umegaki relative entropy~\cite{umegaki1962conditional}.)
For any $\rho\in \density$ and $\sigma \in \PSD$, the Umegaki relative entropy is defined by
\begin{align}\label{eq: Umegaki}
    D(\rho\|\sigma):= \tr[\rho(\log \rho - \log \sigma)],
\end{align}
if $\supp(\rho) \subseteq \supp(\sigma)$ and $+\infty$ otherwise.
\end{definition}

\begin{definition}(Sandwiched \Renyi divergence~\cite{muller2013quantum,wilde2014strong}.)
Let $\alpha \in (0,1) \cup (1,+\infty)$. For any $\rho\in \density$ and $\sigma \in \PSD$, the sandwiched \Renyi divergence is defined by
\begin{align}\label{eq: Sandwiched}
    D_{\Sand,\alpha}(\rho\|\sigma) := \frac{1}{\alpha-1}\log\tr\left[\sigma^{\frac{1-\alpha}{2\alpha}}\rho\sigma^{\frac{1-\alpha}{2\alpha}}\right]^\alpha,
\end{align}
if $\supp(\rho) \subseteq \supp(\sigma)$, and $+\infty$ otherwise.
\end{definition}



When $\alpha \to 1$, $D_{\Sand,\alpha}$ converge to the Umegaki relative entropy~\cite{muller2013quantum,wilde2014strong},
\begin{align}\label{eq: state Renyi continuous}
\lim_{\alpha \to 1} D_{\Sand,\alpha}(\rho\|\sigma) = D(\rho\|\sigma).
\end{align}
When $\alpha \to \infty$, the sandwiched \Renyi divergence converges to the max-relative entropy~\cite{datta2009min,renner2005security},
\begin{align}\label{eq: definition of Dmax}
\lim_{\alpha \to \infty} D_{\Sand,\alpha}(\rho\|\sigma) = D_{\max}(\rho\|\sigma):= \log\inf\big\{t \in \RR \;:\; \rho \leq t\sigma \big\}\;,
\end{align}
if $\supp(\rho) \subseteq \supp(\sigma)$ and $+\infty$ otherwise. 

\begin{definition}(Petz \Renyi divergence~\cite{petz1986quasi}.)
Let $\alpha \in (0,1) \cup (1,+\infty)$. For any $\rho\in \density$ and $\sigma \in \PSD$, the Petz \Renyi divergence is defined by
\begin{align}\label{eq: Petz}
    D_{\Petz,\alpha}(\rho\|\sigma) := \frac{1}{\alpha-1}\log\tr\left[\rho^\alpha\sigma^{1-\alpha}\right],
\end{align}
if  $\supp(\rho) \subseteq \supp(\sigma)$, and $+\infty$ otherwise. 
\end{definition}

\begin{definition}(Hypothesis testing relative entropy.)
Let $\ve \in [0,1]$. For any $\rho\in \density$ and $\sigma \in \PSD$, the quantum hypothesis testing relative entropy is defined by $D_{\Hypo, \ve}(\rho\|\sigma) := -\log \beta_{\ve}(\rho\|\sigma)$
where
\begin{align}
    \beta_\ve(\rho\|\sigma): = \min_{0\leq M \leq I} \left\{\tr[\sigma M]: \tr[\rho(I-M)] \leq \ve\right\}.
\end{align}
\end{definition}

\begin{definition}(Measured relative entropy~\cite{donald1986relative,hiai1991proper}.)
For any $\rho \in \density$, $\sigma \in \PSD$, the measured relative entropy is defined by
\begin{align}
D_{\Meas} (\rho\|\sigma) := \sup_{(\cX,M)} D(P_{\rho,M}\|P_{\sigma,M}),
\end{align}
where $D$ is the Kullback–Leibler divergence and the optimization is over finite sets $\cX$ and positive operator valued measures $M$ on $\cX$ such that $M_x \geq 0$ and $\sum_{x \in \cX} M_x = I$, $P_{\rho,M}$ is a measure on $\cX$ defined via the relation $P_{\rho,M}(x) = \tr[M_x\rho]$ for any $x \in \cX$.    
\end{definition}

\begin{definition}(Measured \Renyi divergence~\cite{Berta2017}.)
Let $\alpha \in (0,1) \cup (1,\infty)$.  For any $\rho \in \density$ and $\sigma \in \PSD$, the {measured \Renyi divergence} is defined as
\begin{align}\label{eq: definition DM alpha}
D_{\Meas, \alpha} (\rho\|\sigma) := \sup_{(\cX,M)} D_{\alpha}(P_{\rho,M}\|P_{\sigma,M}),
\end{align}
where $D_{\alpha}$ is the classical \Renyi divergence. 
\end{definition}
When $\alpha \to 1$, the measured \Renyi divergence converges to the measured relative entropy. 

\subsection{Minimum output channel divergence}

The quantum divergence between two quantum states can be naturally extended to two sets of quantum states. 

\begin{definition}(Quantum divergence between two sets of states.)
For any subsets $\sA \subseteq \density$ and $\sB \subseteq \PSD$, their divergence is defined as 
\begin{align}
\DD(\sA\|\sB) := \inf_{\rho \in \sA, \sigma \in \sB} \DD(\rho\|\sigma),
\end{align} 
which represents the minimum ``distance'' between the sets.
\end{definition}

\begin{definition}(Minimum output channel divergence.)
    Let $\cN \in \CPTP(A\!:\!B)$ and $\cM \in \CP(A\!:\!B)$. The {minimum output channel divergence} is defined by
\begin{align}
\DD^{\inf}(\cN\|\cM) := \inf_{\rho, \sigma \in \density(A)} \DD(\cN(\rho)\| \cM(\sigma)),
\end{align}
which conceptually captures the worst-case scenario where different test states are chosen to minimize the distinguishability between the given channels.
\end{definition}
 It is also useful to see this as a divergence between two sets of quantum states, expressed as 
\begin{align}
    \DD^{\inf}(\cN\|\cM) = \DD(\cN(\density)\|\cM(\density)),
\end{align}
where $\cL(\density) := \{\cL(\rho): \rho \in \density\}$ denotes the image set of $\density$ under the linear map $\cL$. We also define the regularized channel divergence as
\begin{align}
\DD^{\inf,\reg}(\cN\|\cM) := \lim_{n \to \infty} \frac{1}{n} \DD^{\inf}(\cN^{\ox n}\|\cM^{\ox n}),
\end{align}
which accounts for the asymptotic behavior of the channel divergence over multiple uses.


\begin{remark}
    As proved in the main text that the image sets satisfy all assumptions in~\cite[Assumption 24]{fang2024generalized}.
    Note that the measured \Renyi divergence coincides with the sandwiched \Renyi divergence at $\alpha \in \{1/2, +\infty\}$. Thus, by applying the superadditivity in~\cite[Lemma 21]{fang2024generalized} and the subadditivity in~\cite[Lemma 26]{fang2024generalized}, we conclude that the minimum output channel divergence is additive for these cases, that is,
    \begin{align}
        D^{\inf}_{\Sand,1/2}(\cN_1\ox \cN_2\|\cM_1\ox \cM_2) & = D^{\inf}_{\Sand,1/2}(\cN_1\|\cM_1) + D^{\inf}_{\Sand,1/2}(\cN_2\|\cM_2)\\
        D_{\max}^{\inf}(\cN_1\ox \cN_2\|\cM_1\ox \cM_2) & = D_{\max}^{\inf}(\cN_1\|\cM_1) + D_{\max}^{\inf}(\cN_2\|\cM_2),
    \end{align}
    where the first equality recovers Watrous' result~\cite[Corollary 3.60]{watrous2018theory}. 
\end{remark}

\section{Chain rules}
\label{sec: Tightness of the chain rules}

\subsection{Proof of the chain rules}

We have the following chain rules for measured \Renyi divergences and sandwiched \Renyi divergences, which can also be seen as an enhancement of the data processing inequality under partial trace. The proof of these chain rules requires the notion of (reverse) polar sets.

\begin{definition}
Let $\cvxset \subseteq \HERM$ be a convex set. Its polar set is defined by
\begin{align}
\cvxset^\circ:= \{X: \tr[XY] \leq 1,  \forall\, Y\in \cvxset\} = \{X : h_{\cvxset}(X) \leq 1\}
\end{align} 
where $h_{\cvxset}$ is the support function of $\cvxset$:
\begin{align}
    h_{\cvxset}(\omega) := \sup_{\sigma \in \cvxset} \tr[\omega \sigma].
\end{align}
Let $\polarPSD{\cvxset}:= \cvxset^\circ \cap \PSD$ and  $\polarPD{\cvxset}:= \cvxset^\circ \cap \PD$ be the intersections with positive semidefinite operators and positive definite operators, respectively.

Similarly, the reverse polar set of $\cvxset$ is defined as:
\begin{align}
    \cvxset^{\star} &:= \{X : \tr[XY] \geq 1, \forall\, Y \in \cvxset \} = \{X : \revh_{\cvxset}(X) \geq 1\}
\end{align}
where $\revh_{\cvxset}$ is the reverse support function of $\cvxset$:
\begin{align}
    \revh_{\cvxset}(\omega) := \inf_{\sigma \in \cvxset} \tr[\omega \sigma].
\end{align}
\end{definition}

\begin{lemma}(Chain rules.)\label{lem: chain rule DM}
Let $\rho \in \density(RA)$, $\sigma \in \PSD(RA)$, $\cN \in \CPTP(A\!:\!B)$ and $\cM \in \CP(A\!:\!B)$. Let $\rho^\cN_{RB}=\cN(\rho_{RA})$ and $\sigma^\cM_{RB} = \cM (\sigma_{RA})$ be the channel output states.  Then it holds, for any $\alpha \in (0,+\infty)$, that
\begin{align}\label{eq: chain rule DM}
D_{\Meas,\alpha}(\rho^\cN_{RB}\|\sigma^\cM_{RB}) \geq D_{\Meas,\alpha}(\rho_R\|\sigma_R) + D_{\Meas,\alpha}^{\inf}(\cN\|\cM).
\end{align} 
Moreover, it holds, for any $\alpha \in [1/2,\infty)$, that
\begin{align}\label{eq: chain rule DS}
D_{\Sand,\alpha}(\rho^\cN_{RB}\|\sigma^\cM_{RB}) \geq D_{\Sand,\alpha}(\rho_R\|\sigma_R) + D_{\Sand,\alpha}^{\inf,\reg}(\cN\|\cM).
\end{align}
When $\alpha=1$, the chain rules represent the results for the measured and Umegaki relative entropies, respectively.
\end{lemma} 


\begin{proof}
The proof utilizes the superadditivity of the divergence between two sets of quantum states, as established in~\cite[Lemma 21, 23]{fang2024generalized}. To this end, we consider the following sets:
\begin{alignat}{3}
 \sA_1 & = \{\rho_R\}, \quad \sA_2 &= \cN(\density), \quad \sA_3 & = \{\rho_{RB}^{\cN}\},\\
 \sB_1 & = \{\sigma_R\}, \quad \sB_2 & = \cM(\density), \quad \sB_3 & = \{\sigma_{RB}^\cM\},
\end{alignat}
and verify that they meet the required assumptions. We do this for $\{\sA_1, \sA_2, \sA_3\}$ and the same argument works for $\{\sB_1, \sB_2, \sB_3\}$. 
For any $Y_B \in \polarPSD{(\sA_{2})}$, we have $\tr[Y_B \cN(\rho)] \leq 1$ for any $\rho \in \density(A)$. This implies that $\cN^\dagger(Y_B) \leq I_A$, with $\cN^\dagger$ being the adjoint map of $\cN$. Therefore, for any $X_R \in \polarPSD{(\sA_{1})}$ and $Y_B \in \polarPSD{(\sA_{2})}$, we have the following equations,
\begin{align}
    \tr[(X_R \ox Y_B) \cN_{A\to B}(\rho_{RA})] & = \tr[(X_R \ox \cN^\dagger(Y_B)) \rho_{RA}]\\
    & \leq \tr[(X_R \ox I_A) (\rho_{RA})]\\
    & = \tr[X_R \rho_R]\\
    & \leq 1.
\end{align}
This implies that $X_R \ox Y_B \in \polarPSD{(\sA_3)}$ and therefore $\polarPSD{(\sA_{1})} \ox \polarPSD{(\sA_{2})} \subseteq \polarPSD{(\sA_3)}$. Applying the superadditivity in ~\cite[Lemma 21, 23]{fang2024generalized}, we have the asserted result in Eq.~\eqref{eq: chain rule DM} for $\alpha \in (0,1]$. The proof for $\alpha \in (1,+\infty)$ follows in the same way. For $\alpha \in (1,\infty)$, we work with the reverse polar sets instead: if $Y_B \in (\sA_2)^{\star}_{\plus}$, then $\cN^{\dagger}(Y_B) \geq I_{A}$ and as a result, if $X_R \in (\sA_1)^{\star}_{\plus}$, we have $X_R \otimes Y_B \in (\sA_3)^{\star}_{\plus}$ and we can similarly apply~\cite[Lemma 21]{fang2024generalized}. The result in Eq.~\eqref {eq: chain rule DS} is a direct consequence of Eq.~\eqref{eq: chain rule DM}. More specifically, we have that for any $\alpha \in [1/2,\infty)$,
\begin{align}
    D_{\Sand,\alpha}(\rho^\cN_{RB}\|\sigma^\cM_{RB}) & = \lim_{n\to \infty} \frac{1}{n} D_{\Meas,\alpha}((\rho^\cN_{RB})^{\ox n}\|(\sigma^\cM_{RB})^{\ox n})\\
    & \geq \lim_{n\to \infty} \frac{1}{n} D_{\Meas,\alpha}((\rho_R)^{\ox n}\|(\sigma_{B})^{\ox n}) + \lim_{n\to \infty} \frac{1}{n} D_{\Meas,\alpha}^{\inf}(\cN^{\ox n}\|\cM^{\ox n})\\
    & = D_{\Sand,\alpha}(\rho_R\|\sigma_R) + D_{\Sand,\alpha}^{\inf,\reg}(\cN\|\cM),
\end{align}
where the first line follows from~\cite[Lemma 16, 17]{fang2024generalized}, the second line follows from Eq.~\eqref{eq: chain rule DM} and the last line follows from~\cite[Lemma 28]{fang2024generalized}.
\end{proof}

\subsection{Tightness of the chain rules}

In the following, we introduce the notion of the amortized minimum output channel divergence and show that it coincides with the regularized divergence,  being an analog result for the best-case channel divergence~\cite{fang2020chain}. This, in turn, demonstrates the tightness of our chain rule properties.


Similar to the amortized channel divergence used in the existing literature~\cite{wilde2020amortized}, we can define the minimum output version as follows.
Let $\DD$ be a quantum divergence between states. Let $\cN \in \CPTP(A\!:\!B)$ and $\cM \in \CP(A\!:\!B)$. Then the amortized minimum output channel divergence is defined by
\begin{align}
    \DD^{\inf, \amo}(\cN\|\cM):= \inf_{\substack{\rho\in \density(RA)\\ \sigma \in \density(RA)}} \DD(\cN_{A\to B}(\rho_{RA})\|\cM_{A\to B}(\sigma_{RA})) - \DD(\rho_R\|\sigma_R).
\end{align}



\begin{lemma}
Let $\alpha \in [1/2,\infty)$. For any $\cN\in \CPTP(A\!:\!B)$, $\cM \in \CP(A\!:\!B)$, it holds that
\begin{align}
D_{\Sand,\alpha}^{\inf, \amo}(\cN\|\cM) & = D_{\Sand,\alpha}^{\inf,\reg}(\cN\|\cM).
\end{align}     
Equivalently, for any $\cN\in \CPTP(A\!:\!B)$, $\cM \in \CP(A\!:\!B)$ and any $\ve \in (0,1)$, there exists $\rho,\sigma\in \density(RA)$, such that \begin{align}
    D_{\Sand,\alpha}^{\inf,\infty}(\cN\|\cM) \leq D_{\Sand,\alpha}(\cN_{A\to B}(\rho_{RA})\|\cM_{A\to B}(\sigma_{RA})) - D_{\Sand,\alpha}(\rho_R\|\sigma_R)  \leq D_{\Sand,\alpha}^{\inf,\infty}(\cN\|\cM) + \ve.
\end{align}
\end{lemma}

\begin{proof}
We prove the result for the quantum relative entropy ($\alpha = 1$) and the same argument works for the sandwiched \Renyi divergence of order $\alpha \neq 1$ as well. Note that the chain rule property in Lemma~\ref{lem: chain rule DM} is equivalent to $D^{\inf, \amo}(\cN\|\cM) \allowbreak \geq D^{\inf,\reg}(\cN\|\cM)$.
Now we prove the reverse direction. For this, we will first show the superadditivity of the amortized divergence under tensor product. That is, 
\begin{align}\label{eq: amortized worst case superadditivity}
D^{\inf, \amo}(\cN_1 \ox \cN_2 \|\cM_1\ox \cM_2) \geq D^{\inf, \amo}(\cN_1\|\cM_1) + D^{\inf, \amo}(\cN_2\|\cM_2),
\end{align}
for any quantum channels $\cN_1 \in \CPTP(A_1\!:\!B_1)$, $\cN_2\in \CPTP(A_2\!:\!B_2)$, CP maps $\cM_1 \in \CP(A_1\!:\!B_1)$, $\cM_2\in \CP(A_2\!:\!B_2)$. 
To see this, let $(\rho_{RA_1A_2}, \sigma_{RA_1A_2})$ be any feasible solution to the optimization on the left-hand side of Eq.~\eqref{eq: amortized worst case superadditivity} and denote its corresponding objective value by
\begin{align}
    \delta_{12} := D(\cN_1 \ox \cN_2(\rho_{RA_1A_2})\|\cM_1 \ox \cM_2(\sigma_{RA_1A_2})) - D(\rho_R\|\sigma_R).
\end{align}
Let $\omega_{RA_2B_1} = \cN_1(\rho_{RA_1A_2})$ and $\gamma_{RA_2B_1} = \cM_1(\sigma_{RA_1A_2})$. We can check that $(\rho_{RA_1},\sigma_{RA_1})$ and $(\omega_{RA_2B_1},\allowbreak \gamma_{RA_2B_1})$ are feasible solutions to the amortized divergence on the right-hand side of Eq.~\eqref{eq: amortized worst case superadditivity}, respectively, with the corresponding objective values by
\begin{align}
    \delta_1 := &  D(\cN_1(\rho_{RA_1})\|\cM_1(\sigma_{RA_1})) - D(\rho_R\|\sigma_R) \geq D^{\inf, \amo}(\cN_1\|\cM_1)\\
    \delta_2 := & D(\cN_2(\omega_{RA_2B_1})\|\cM_2(\gamma_{RA_2B_1})) - D(\omega_{RB_1}\|\gamma_{RB_1}) \geq D^{\inf, \amo}(\cN_2\|\cM_2).
\end{align}
Noting that $\omega_{RB_1} = \cN_1(\rho_{RA_1})$ and $\gamma_{RB_1} = \cM_1(\sigma_{RA_1})$, we have $\delta_{12} = \delta_1 + \delta_2$. This implies
\begin{align}
    \delta_{12} \geq D^{\inf, \amo}(\cN_1\|\cM_1) + D^{\inf, \amo}(\cN_2\|\cM_2).
\end{align}
As this holds for any feasible solution $(\rho_{RA_1A_2}, \sigma_{RA_1A_2})$, we have the asserted result in Eq.~\eqref{eq: amortized worst case superadditivity}.

By trivializing the reference system in the amortized divergence, we get $D^{\inf, \amo}(\cN\|\cM) \leq D^{\inf}(\cN\|\cM)$. Then we have
\begin{align}
    D^{\inf, \amo}(\cN\|\cM) \leq \frac{1}{n} D^{\inf, \amo}(\cN^{\ox n}\|\cM^{\ox n}) \leq \frac{1}{n} D^{\inf}(\cN^{\ox n}\|\cM^{\ox n}),
\end{align}
where the first inequality follows from Eq.~\eqref{eq: amortized worst case superadditivity}. As the above holds for any $n$, we can take $n\to \infty$ on the right-hand side and conclude that $D^{\inf, \amo}(\cN\|\cM) \leq D^{\inf,\reg}(\cN\|\cM)$. This completes the proof.
\end{proof}

\subsection{Counter-example to a potential improvement of the chain rule}
\label{sec: Counter-example to a potential improvement of the chain rule}


The quantum channel divergence studied in most existing literatures~\cite{leditzky2018approaches} use the same test states for both channels. So it may be expected that we can enhance the chain rules by using the same test states as well. However, we show here that this is not possible by giving a counter-example. That is, the chain rule cannot be enhanced to 
\begin{align}\label{eq: chain rule enhancement}
D_{\Meas}(\cN_{A\to B}(\rho_{RA})\|\cM_{A\to B}(\sigma_{RA})) \geq D_{\Meas}(\rho_R\|\sigma_R) + D_{\Meas}^{\inf'}(\cN\|\cM)
\end{align} 
where the channel divergence takes the same input state
\begin{align}
D_{\Meas}^{\inf'}(\cN\|\cM):= \inf_{\rho\in \density(A)} D_{\Meas}(\cN_{A\to B}(\rho_{A})\| \cM_{A \to B}(\rho_{A})).
\end{align}
To see this, consider the generalized amplitude damping (GAD) channel, which is defined as
\begin{align}
    \cA_{\gamma, N}(\rho)  = \sum_{i=1}^4 A_i \rho A_i^\dagger, \quad \gamma, N \in [0,1],
\end{align}
with the Kraus operator
\begin{alignat}{2}
    A_1 & = \sqrt{1-N}(\ket{0}\bra{0} + \sqrt{1-\gamma}\ket{1}\bra{1}), \qquad && A_2  = \sqrt{\gamma(1-N)} \ket{0}\bra{1},\\  
    A_3 & = \sqrt{N}(\sqrt{1-\gamma} \ket{0}\bra{0} + \ket{1}\bra{1}), \qquad
    && A_4 =  \sqrt{\gamma N} \ket{1}\bra{0}.
\end{alignat}

Using convex optimization, we can numerically evaluate each terms $D_{\Meas}(\cN_{A\to B}(\rho_{RA})\|\cM_{A\to B}(\sigma_{RA}))$, $D_{\Meas}(\rho_R\|\sigma_R)$ and $D_{\Meas}^{\inf'}(\cN\|\cM)$. Then in Figure~\ref{fig: chain rule enhancement}(a), we show that the channel divergence $D_{\Meas}^{\inf'}$ is subadditive under tensor product of channels. That is, it does not inherit the properties of the state divergence, making it not a suitable channel extension. Moreover, in Figure~\ref{fig: chain rule enhancement}(b), we show that the chain rule property in Eq.~\eqref{eq: chain rule enhancement} does not hold, as there are cases such that $y < x_2$ in the plot.

\begin{figure}[h]
    \centering
    \includegraphics[width=0.9\linewidth]{SM-chain_rule_enhancement}
    \caption{(a) Subadditivity for the channel divergence $D^{\Meas,\inf'}$ where $\cA_{0.5, 0}$ and $\cA_{p, 0.9}$ are the GAD channels and $p$ ranges from $0$ to $1$; (b) Random test for the chain rule property, where the quantum channels are chosen as $\cA_{0.5, 0}$ and $\cA_{0.5, 0.9}$, the quantum states are 500 randomly generated quantum states with real entries,  $x_1 = D_{\Meas}(\rho_R\|\sigma_R) + D_{\Meas}^{\inf}(\cA_{0.5, 0}\|\cA_{0.5, 0.9})$ and $x_2 = D_{\Meas}(\rho_R\|\sigma_R) + D_{\Meas}^{\inf'}(\cA_{0.5, 0}\|\cA_{0.5, 0.9})$.}
    \label{fig: chain rule enhancement}
\end{figure}

\section{Proof of the adversarial quantum Stein's lemma}

Since non-adaptive strategies are a specific type of adaptive strategy, we have the inclusions that $\sA_n' \subseteq \sA_n \quad \text{and} \quad \sB_n' \subseteq \sB_n$.
This gives the relations for the type-I and type-II errors by $\alpha(\sA_n', M_n) \leq \alpha(\sA_n, M_n)$ and $\beta(\sB_n', M_n) \leq \beta(\sB_n, M_n)$.
So we have the general relation that 
$\beta_{n,\ve}'(\cN\|\cM)  := \inf \{\beta(\sB_n', M_n): 0\leq M_n\leq I, \alpha(\sA_n', M_n) \leq \ve \} \leq  \beta_{n,\ve}(\cN\|\cM)$
where the inequality holds because the right-hand side represents the infimum of a larger objective value over a smaller feasible set. We can also rewrite the optimal type-II errors as the hypothesis testing relative entropy between two sets,
\begin{align}
    -\log \beta_{n,\ve}(\cN\|\cM) & = D_{\Hypo,\ve}(\sA_n\|\sB_n),\\
    -\log \beta_{n,\ve}'(\cN\|\cM) & = D_{\Hypo,\ve}(\sA_n'\|\sB_n'),
\end{align} 
where $D_{\Hypo,\ve}(\rho\|\sigma):=-\log\{\tr[\sigma M]: \tr[\rho(I-M)] \leq \ve, 0 \leq M \leq I\}$. This can be done by showing that $\sA_n (\sA_n')$ and $\sB_n (\sB_n')$ are convex sets (see Lemma~\ref{lem: ad channel state convex} below) and applying~\cite[Lemma 31]{fang2024generalized}. After this, the proof for the adversarial quantum Stein's lemma then contains two parts, as shown in the main text. The converse part makes use of the chain rule property to show that 
\begin{align}
\liminf_{n\to \infty} \frac{1}{n} D_{\Hypo,\ve}(\sA_n\|\sB_n) \geq D^{\inf,\reg}(\cN\|\cM),
\end{align}
while the achievable part aims to show that \begin{align}
\limsup_{n\to \infty} \frac{1}{n} D_{\Hypo,\ve}(\sA_n'\|\sB_n') \leq D^{\inf,\reg}(\cN\|\cM),
\end{align}
by applying the generalized quantum asymptotic equipartition (AEP) property in~\cite[Theorem 25]{fang2024generalized} to $\sA_n'$ and $\sB_n'$. 

\begin{lemma}(Convexity.)\label{lem: ad channel state convex}
    The sets $\{\sA_n\}_{n\in \NN}$ and $\{\sB_n\}_{n\in \NN}$ defined in the main text are convex.
\end{lemma}
\begin{proof}
We prove the assumptions for $\{\sA_n\}_{n\in \NN}$ and the same reasoning works for $\{\sB_n\}_{n\in \NN}$ as well.   
Let $\{\cP^i\}_{i=1}^n$ with systems $R_1, \dots, R_n$ and $\{\bar{\cP}^i\}_{i=1}^n$ with systems $R_1, \dots, R_n$ be two strategies and $\lambda \in [0,1]$. Note that we may assume both strategies have the same systems $R_i$ as we can always increase the dimension of the systems $R_i$ by extending the action of the channel in an arbitrary way without affecting the output.
Let us now define another strategy $\{\bar{\bar{\cP}}^i\}_{i=1}^n$ as follows. Let $\bar{\bar{R}}_i = R_i \otimes C$ for all $i=1,\dots,n$ where $C$ is a two-dimensional system. Then define 
\begin{align}
    \bar{\bar{\cP}}^1(\cdot) = \lambda \cP^1(\cdot) \ox \proj{0}_C + (1-\lambda) \bar{\cP}^1(\cdot) \ox \proj{1}_C
\end{align}
and for $i \geq 2$, define 
\begin{align}
    \bar{\bar{\cP}}^i(X) = (\cP^i \circ \cC_0(X)) \ox \proj{0}_C + (\bar{\cP}^i \circ \cC_1(X)) \ox \proj{1}_C
\end{align}
where $\cC_0(X) = \<0|_C X |0\>_C$ and $\cC_1(X) = \<1|_C X |1\>_C$. Since $\cC_0, \cC_1, \cP^i, \bar{\cP}^i$ are all CP maps, we know that $\bar{\bar{\cP}}^i$ is also a CP map. Moreover, if $\cP^i, \bar{\cP}^i$ are trace-preserving, then $\bar{\bar{\cP}}^i$ is also trace-preserving. It is easy to check the following relations,
\begin{alignat}{3}
    \cC_0 \circ \bar{\bar{\cP}}^1 & = \lambda \cP^1 \quad & \text{and} \quad \cC_1 \circ \bar{\bar{\cP}}^1 & = (1-\lambda) \bar{\cP}^1,\label{eq: ad convex tmp1}\\
    \cC_0 \circ \bar{\bar{\cP}}^i & = \cP^i \circ \cC_0 \quad & \text{and} \quad \cC_1 \circ \bar{\bar{\cP}}^i & = \bar{\cP}^i \circ \cC_1, \quad \forall i \geq 2.\label{eq: ad convex tmp2}
\end{alignat}
Noting that $\tr_C$ commutes with $\cU$ as they are acting on different systems, we have 
\begin{align}\label{eq: ad convex tmp3}
\tr_C \circ \prod_{i=1}^n \cU \circ \bar{\bar{\cP}}^i 
    & = \cU \circ \cP^n \circ \cC_0 \circ \prod_{i=1}^{n-1} \cU \circ \bar{\bar{\cP}}^i + \cU \circ \bar{\cP}^n \circ \cC_1 \circ \prod_{i=1}^{n-1} \cU \circ \bar{\bar{\cP}}^i.
\end{align}
Also noting that $\cC_0$ and $\cC_1$ both commute with $\cU$ as they are acting on different systems and using the relations in Eqs.~\eqref{eq: ad convex tmp1} and~\eqref{eq: ad convex tmp2}, we have 
\begin{align}
    \cU \circ \cP^n \circ \cC_0 \circ \prod_{i=1}^{n-1} \cU \circ \bar{\bar{\cP}}^i & = \lambda\, \cU \circ \cP^n \circ \prod_{i=1}^{n-1} \cU \circ {{\cP}}^i = \lambda\, \prod_{i=1}^{n} \cU \circ {{\cP}}^i,\\
    \cU \circ \bar{\cP}^n \circ \cC_1 \circ \prod_{i=1}^{n-1} \cU \circ \bar{\bar{\cP}}^i & = (1-\lambda)\, \cU \circ \cP^n \circ \prod_{i=1}^{n-1} \cU \circ {\bar{\cP}}^i = (1-\lambda)\, \prod_{i=1}^{n} \cU \circ {\bar{\cP}}^i.
\end{align}
Taking these into Eq.~\eqref{eq: ad convex tmp3}, we have 
\begin{align}
    \tr_{\bar{\bar{R}}_n E_n} \circ \prod_{i=1}^n \cU \circ \bar{\bar{\cP}}^i = \lambda\, \tr_{R_n E_n} \circ  \prod_{i=1}^{n} \cU \circ {{\cP}}^i + (1-\lambda)\, \tr_{R_n E_n} \circ  \prod_{i=1}^{n} \cU \circ {\bar{\cP}}^i
\end{align}
This shows that any mixture of the reduced states on $B_1\cdots B_n$ by the strategies $\{\cP^i\}_{i=1}^n$ and $\{\bar{\cP}^i\}_{i=1}^n$ is also given by the reduced state of another strategy $\{\bar{\bar{\cP}}^i\}_{i=1}^{n}$ which proves the convexity of $\sA_n$. 
\end{proof}




\section{Relative entropy accumulation}
\label{sec: Application 3: entropy accumulation theorem}

The entropy accumulation theorem~\cite{dupuis2020entropy,metger2022generalised} is a technique to find bounds on the operationally relevant uncertainty (entropy) present in the outputs of a sequential process as a sum of the worst case uncertainties (entropies) of each step. It has been widely used in quantum cryptography~\cite{arnon2018practical,liu2018device,george2022finite}. This naturally raises the question of whether such a statement can be generalized to divergences between arbitrary sequential processes of channels, rather than being restricted only to entropies. This was first asked as an open question in~\cite{metger2022generalised} for the max-relative entropy.

More specifically, the operational setting for relative entropy accumulation is depicted in Figure~\ref{fig:eat setting}. Consider two states $\rho_{A_1}$ and $\sigma_{A_1}$ and quantum channels $\cN_i \in \CPTP(A_i\!:\!A_{i+1} B_i)$ and $\cM_i \in \CP(A_i\!:\!A_{i+1} B_i)$ that are applied sequentially from $i=1$ to $i=n$ and generating the systems $B_i$. The systems $A_i$ should be seen as an internal memory system that we do not control. The key question in the relative entropy accumulation asks: \emph{Can we bound the operationally relevant divergence between the obtained states as the sum of the contributions of each step?}

\begin{figure}[H]
    \centering
    \includegraphics[width=0.6\linewidth]{SM-REAT}
    \caption{Illustration of the setting of the relative entropy accumulation.}
    \label{fig:eat setting}
\end{figure}

Similar to the adversarial channel discrimination in the main text, we denote the Stinespring dilations of $\cN_i$ and $\cM_i$ as $U_i$ and $V_i$, respectively, with the environmental system denoting as $T_i$. Denote also the corresponding channel as $\cU_i(\cdot)=U_i(\cdot)U_i^\dagger$ and $\cV_i(\cdot) = V_i(\cdot)V_i^\dagger$. Note that $U_i$ is an isometry because $\cN_i$ is trace-preserving, but this is not necessarily the case for $V_i$. Then the setting in Figure~\ref{fig:eat setting} is equivalent to the diagram in Figure~\ref{fig:eat setting dilation}. 

\begin{figure}[h]
    \centering
    \includegraphics[width=0.6\linewidth]{SM-REAT-dilation}
    \caption{Illustration of the setting of the relative entropy accumulation with Stinespring dilation.}
    \label{fig:eat setting dilation}
\end{figure}

By extending the adversarial channel discrimination framework to allow different channels $\cN_i$ and $\cM_i$ at each round, we can unify the relative entropy accumulation within this broader framework. More specifically, using a similar notation in the main text, we denote the Stinespring dilation of $\cN_i$ and $\cM_i$ as $U_i$ and $V_i$, respectively. Denote also the corresponding channel as $\cU_i(\cdot)=U_i(\cdot)U_i^\dagger$ and $\cV_i(\cdot) = V_i(\cdot)V_i^\dagger$. An illustrative figure is given in Figure~\ref{fig:extended channel discrimination}. Then, taking a particular choice,
\begin{align}
    \dim R_i & = 1,\\
    E_i & = A_{i+1}T_i\\
    \cP^1 & = \rho_{A_1},\\
    \cQ^1 & = \sigma_{A_1},\\
    \cP^i & = \cQ^i = \tr_{T_{i-1}}, \quad \forall i \geq 2,
\end{align}
the adversarial discrimination framework in Figure~\ref{fig:extended channel discrimination} reduces to the relative entropy accumulation in Figure~\ref{fig:eat setting dilation}.

\begin{figure}[H]
    \centering
    \includegraphics[width=0.62\linewidth]{SM-channel_discrimination}
    \caption{Illustration of an extended setting of adversarial quantum channel discrimination. 
    }
    \label{fig:extended channel discrimination}
\end{figure}

This new perspective enables us to establish a relative entropy accumulation theorem for $D_{\Hypo, \ve}$ (a smoothed form of the min-relative entropy), giving an answer to the dual formulation of the open question in~\cite{metger2022generalised}. Specifically, we generalize the converse part of the adversarial quantum Stein's lemma in two ways: we allow the channels applied at different steps to vary, and we compute explicit finite-size bounds. 

We state the relative entropy accumulation theorem in this more general setting depicted in Figure~\ref{fig:extended channel discrimination}. From the above discussion, it is clear that the version stated in the main text is a special case.
\begin{theorem}
\label{thm:reat}(Relative entropy accumulation.)
Consider two sequences of maps $\cU_{i} \in \CPTP(A_i\!:\!B_i E_{i})$ and $\cV_i \in \CP(A_i\!:\!B_i E_{i})$ for $i \in \{1,\dots,n\}$ and let $\cP^i, \cQ^{i} \in \CPTP(E_{i-1}R_{i-1}, A_iR_{i})$ as illustrated in Figure~\ref{fig:extended channel discrimination}.
Let $\ve \in (0,1)$ and assume for all $i\in \{1, \dots, n\}$ and $m \geq 2$,
\begin{align}
\label{eq: assumptionC N M}
     \forall \alpha \in [1/2,1]: \; D_{\Petz,3/2}(\rho^{(\alpha)}_m \| \sigma^{(\alpha)}_m) \leq \frac{C}{4}m \; \text{ and } \; \forall \sigma \in \density(A_i) : \; \log \tr(\cV_i(\sigma)) \leq \frac{C}{4}, 
\end{align}
where 
$\rho^{(\alpha)}_m, \sigma^{(\alpha)}_m$ are outputs of the channels $(\tr_{E_{i}} \circ \cU_i)^{\otimes m},(\tr_{E_{i}} \circ \cV_i)^{\otimes m}$ (respectively) and achieve the minimum $D_{\Petz,\alpha}(\rho_m^{(\alpha)} \| \sigma_m^{(\alpha)}) = D^{\inf}_{\Petz,\alpha}( (\tr_{E_{i}} \circ \cU_i)^{\otimes m} \| (\tr_{E_{i}} \circ \cV_i)^{\otimes m})$. 
Then letting $\rho_n = \tr_{R_nE_n} \prod_{i=1}^n \cU_{i} \circ \cP^{i}$ and $\sigma_n = \tr_{R_n E_n} \prod_{i=1}^n \cV_{i} \circ \cQ^{i}$, we have
\begin{align}
\label{eq: reat eq}
D_{\Hypo, \ve} & \left(\rho_n  \bigg\| \sigma_n\right)  \geq \sum_{i=1}^n D^{\inf,\reg}(\tr_{E_{i}} \circ \cU_i \| \tr_{E_{i}} \circ \cV_i) - C' n^{2/3} \log n \log^{1/3} \frac{1}{\ve}, 
\end{align}
where $C'$ is a constant that only depends on $d = \max_{i} \dim B_i$ and $C$.
\end{theorem}


\begin{proof}
The proof below is basically the same as the converse part of the adversarial quantum Stein's lemma in the main text. We start as usual by bounding the hypothesis testing relative entropy with a R\'enyi divergence of order $\alpha \in (0,1)$:
\begin{align}
D_{\Hypo, \ve}\left(\rho_n \bigg\| \sigma_n \right) 
\geq D_{\Sand,\alpha}\left(\rho_n \bigg\| \sigma_n \right) + \frac{\alpha}{\alpha-1}\log(1/\ve).
\end{align}
We can now introduce $\rho'_n = \tr_{R_n} \circ \cP^n \circ \prod_{i=1}^{n-1} \cU_i \circ \cP^i$ and $\sigma'_n = \tr_{R_n} \circ \cQ^n \circ \prod_{i=1}^{n-1} \cV_i \circ \cQ^i$ the joint states before the $n$-th use the channel $\cU_{i}/\cV_{i}$. We have $\rho_n = (\tr_{E_{n}} \circ \cU_{n})(\rho'_n)$ We use the chain rule for sandwiched relative entropy to bound 
\begin{align}
D_{\Sand,\alpha}\left( (\tr_{E_n} \circ \cU_{n})(\rho'_n) \bigg\| (\tr_{E_n} \circ \cV_n)(\sigma'_n)\right) &\geq D_{\Sand,\alpha}\left( \tr_{A_n} \rho'_n \bigg\| \tr_{A_n} \sigma'_n \right) + D^{\inf, \infty}_{\Sand,\alpha}(\tr_{E_n} \circ \cU_{n} \| \tr_{E_n} \circ \cV_n).
\end{align}
Now note that $\tr_{A_n} \rho'_n = \rho_{n-1}$ where $\rho_{n-1} = \tr_{R_{n-1}E_{n-1}} \prod_{i=1}^{n-1} \cU_{i} \circ \cP^{i}$ and similarly for $\sigma$. As a result, applying the chain rule $n-1$ times, we get
\begin{align}
D_{\Sand,\alpha}\left( \rho_n \bigg\| \sigma_n \right)
&\geq \sum_{i=1}^n D^{\inf,\infty}_{\Sand,\alpha}(\tr_{E_{i}} \circ \cU_i \| \tr_{E_{i}} \circ \cV_i) \\
&= \sum_{i=1}^n D^{\inf,\infty}_{\Meas,\alpha}(\tr_{E_{i}} \circ \cU_i \| \tr_{E_{i}} \circ \cV_i) \\
&\geq \sum_{i=1}^n \frac{1}{m} D^{\inf}_{\Meas,\alpha}((\tr_{E_{i}} \circ \cU_i)^{\otimes m} \| (\tr_{E_{i}} \circ \cV_i)^{\otimes m})
\end{align}
where $m \geq 2$ and we used~\cite[Lemma 28]{fang2024generalized} for the equality and the superadditivity of $D_{\Meas, \alpha}$ in~\cite[Lemma 21]{fang2024generalized} for the last inequality. Note that both of these results were applied for the family of states $\sA_m'' = (\tr_{E_{i}} \circ \cU_i)^{\otimes m}(\density)$ and $\sB_m'' = (\tr_{E_{i}} \circ \cV_i)^{\otimes m}(\density)$ which satisfies~\cite[Assumption 24]{fang2024generalized}, as shown in the proof of the adversarial quantum Stein's lemma.

Observe that assumption~\eqref{eq: assumptionC N M} implies assumption ($*$) in \cite[Lemma 30]{fang2024generalized} as $\log \tr(\cV_i^{\otimes m}(\sigma)) \leq m \log \lambda_{\max}(\cV_i^{\dagger}(I)) \leq \frac{C}{4} m$. As a result, \cite[Lemma 30]{fang2024generalized} gives
\begin{align}
    \frac{1}{m} D^{\inf}_{\Meas,\alpha}&((\tr_{E_{i}} \circ \cU_i)^{\otimes m} \| (\tr_{E_{i}} \circ \cV_i)^{\otimes m})\notag \\
    &\geq D^{\inf, \infty}(\tr_{E_{i}} \circ \cU_i \| \tr_{E_{i}} \circ \cV_i) - (1-\alpha) (2+C)^2 m - \frac{2(d^2+d) \log(m+d)}{m},
\end{align}
for $1-\frac{1}{(2+C)m} < \alpha < 1$. Let us now choose $1-\alpha = \frac{8d^2 \log m}{(2+C)^2 m^2}$ and assume that $m \geq \max\left(d,\left(\frac{16 d^2}{2+C}\right)^2\right)$ so that the condition $\alpha \geq 1 - \frac{1}{(2+C)m}$ is satisfied and $\log(m+d) \leq 2 \log m$. 

Putting everything together, we get
\begin{align}
D_{\Hypo, \ve}  \left(\rho_n \bigg\| \sigma_n \right) \geq \sum_{i=1}^n D^{\inf,\reg}(\tr_{E_{i}} \circ \cU_{i} \| \tr_{E_{i}} \circ \cV_{i}) - n \frac{16d^2 \log m}{m} - \frac{(2+C)^2 m^2}{8d^2\log m}\log \frac{1}{\ve}.
\end{align}
We now choose $m = \left(\frac{64 d^4 n }{(2+C)^2 \log \frac{1}{\ve} }\right)^{1/3} $.  With this choice
\begin{align}
D_{\Hypo, \ve}\left(\rho_n \bigg\| \sigma_n \right)
&\geq \sum_{i=1}^n D^{\inf,\reg}(\tr_{E_{i}} \circ \cU_{i} \| \tr_{E_{i}} \circ \cV_{i}) - C' n^{2/3} \log n \log^{1/3} \frac{1}{\ve},
\end{align}
for a constant $C'$ that only depends on $C$ and $d$.
\end{proof}


\begin{figure}[H]
    \centering
    \includegraphics[width=0.6\linewidth]{SM-EAT.pdf}
    \caption{Illustration of the setting of the entropy accumulation.}
    \label{fig:setting EAT}
\end{figure}

As a corollary, we get a weak form of the entropy accumulation statement for the smoothed max-entropy obtained in~\cite{metger2022generalised}. We recall that the smoothed max-entropy is defined as
\begin{align}
    H_{\max}^{\ve}(B|C)_{\rho} = \log \inf_{\substack{\tilde{\rho}_{BC} \in \PSD(BC) \\ \tr(\tilde{\rho}) \leq 1 \\ P(\rho, \tilde{\rho}) \leq \ve}} \sup_{\sigma_C \in \density(C)} \left\| \tilde{\rho}_{BC}^{\frac{1}{2}} \id_{B} \otimes \sigma_C^{\frac{1}{2}} \right\|_1^2,
\end{align}
where $P(\rho,\sigma) = \sqrt{1-F(\rho,\sigma)^2}$ is the purifided distance with $F(\rho,\sigma) := \|\sqrt{\rho}\sqrt{\sigma}\|_1 + \sqrt{(1-\tr\rho)(1-\tr\sigma)}$.

\begin{corollary}($H_{\max}$-entropy accumulation.)
    Let $\cN_i' \in \CPTP(Y_{i-1}\!:\!S_i C_i Y_{i})$ be quantum channels and $\rho_{Y_0} \in \density(Y_0)$ be a quantum state. Define the state $\rho_{S_1 \dots S_n C_1 \dots C_n Y_n} = \prod_{i=1}^n \cN_i' (\rho_{Y_0})$. We have for $\ve \in [0,1/2]$,
    \begin{align}
        H_{\max}^{\ve}(S_1 \dots S_n | C_1 \dots C_n)_{\rho} \leq \sum_{i=1}^n \sup_{\omega \in \density(Y_{i-1})} H(S_i | C_i)_{\cN'(\omega)} + K n^{2/3} \log n \log^{1/3} \frac{1}{\ve},
    \end{align}
    where $K$ is a constant only depending on $\max_{i} \dim S_i C_i$.
\end{corollary}

\begin{proof}
We apply the relative entropy accumulation theorem as stated in the main text with the following replacements: letting $C'_i$ be isomorphic to $C_i$, we set $A_{i+1} \leftarrow Y_{i} C'_{i+1} \dots C'_n$ for $i=0$ to $n-1$, $A_{n+1} \leftarrow Y_n$,  $B_i \leftarrow S_i C_i$ for $i=1$ to $n$, $\cN_i \leftarrow \cN_{i}' \otimes \tr_{C'_{i}} \otimes \operatorname{id}_{C'_{i+1} \dots C'_n}$ (here, $\operatorname{id}$ refers to the identity map) and finally $\cM_i$ is defined as $\cM_i(X_{Y_{i-1}C'_i \dots C'_n}) = \id_{S_i} \otimes X_{C_i C'_{i+1} \dots C'_{n}} \otimes \proj{0}_{Y_i}$, where $\proj{0}_{Y_i}$ is an arbitrary fixed state in $\density(Y_i)$. An illustrative figure is given in Figure~\ref{fig:setting EAT}.

Theorem~\ref{thm:reat} gives for the left hand side of~\eqref{eq: reat eq} and any $\sigma \in \density(C_1' \dots C_n')$:
\begin{align}
D_{\Hypo, \ve}&\left(\tr_{A_{n+1}} \circ \prod_{i=1}^n \cN_i (\rho_{Y_0} \otimes \sigma_{C'_1 \dots C'_n}) \bigg\| \tr_{A_{n+1}} \circ \prod_{i=1}^n \cM_i (\proj{0}_{Y_0} \otimes \sigma_{C'_1 \dots C'_n})\right)\notag \\
    &= D_{\Hypo, \ve}(\rho_{S_1 \dots S_n C_1 \dots C_n} \| \id_{S_1 \dots S_n} \otimes \sigma_{C_1 \dots C_n}).
\end{align}
As the right hand side of~\eqref{eq: reat eq} does not depend on $\sigma$, we can take an infimum over $\sigma$ and use~Proposition~\ref{prop: DH Hmax} to get the following
\begin{align}
\inf_{\sigma} D_{\Hypo, \ve}&\left(\tr_{A_{n+1}} \circ \prod_{i=1}^n \cN_i (\rho_{Y_0} \otimes \sigma_{C'_1 \dots C'_n}) \bigg\| \tr_{A_{n+1}} \circ \prod_{i=1}^n \cM_i (\proj{0}_{Y_0} \otimes \sigma_{C'_1 \dots C'_n})\right) \notag\\
    &\leq - H_{\max}^{\sqrt{2\ve}}(S_1 \dots S_n | C_1 \dots C_n)_{\rho}.
\end{align}

On the right hand side of~\eqref{eq: reat eq}, we have terms of the form $D^{\inf,\reg}(\tr_{A_{i+1}} \circ \cN_i \| \tr_{A_{i+1}} \circ \cM_i)$. Note that for $\omega \in \density(Y_{i-1}C'_{i} \dots C'_n)$, we have $(\tr_{A_{i+1}} \circ \cN_i)(\omega) = \tr_{Y_i}\cN_i'(\omega_{Y_{i-1}})$ and $(\tr_{A_{i+1}} \circ \cM_i)(\omega) = \id_{S_i} \otimes \omega_{C_i}$. As a result, $D^{\inf}(\tr_{A_{i+1}} \circ \cN_i \| \tr_{A_{i+1}} \circ \cM_i) = \inf_{\omega \in \density(Y_{i-1})} - H(S_i | C_i)_{\cN_i'(\omega)}$, where we used the fact that $-H(B|C)_{\rho} = \inf_{\sigma \in \density(C)} D(\rho_{BC} \| \id_{B} \otimes \sigma_{C})$. We now need to evaluate the regularization:
\begin{align}
    D^{\inf,\reg}&(\tr_{A_{i+1}} \circ \cN_i \| \tr_{A_{i+1}} \circ \cM_i) \notag \\
    &= \inf_{m \geq 1} \frac{1}{m}  \inf_{\substack{\omega \in \density((Y_{i-1})^{\otimes m}) \\ \sigma \in \density((C_{i} \dots C_n)^{\otimes m})}} D((\tr_{Y_i}\circ\cN_i')^{\otimes m}(\omega) \| \id_{S_{i,1} \dots S_{1,m}} \otimes \sigma_{C_{i,1} \dots C_{i,m}}) \\
    &= - \sup_{m \geq 1} \sup_{\omega} \frac{1}{m} H(S_{i,1} \dots S_{i,m} | C_{i,1} \dots C_{i,m})_{\cN_i'^{\otimes m}(\omega)} \\
    &= - \sup_{m \geq 1} \sup_{\omega} \frac{1}{m} \sum_{j=1}^m H(S_{i,j} | C_{i,1} \dots C_{i,m} S_{i,1} \dots S_{i,j-1})_{\cN_i'^{\otimes m}(\omega)} \\
    &\geq - \sup_{m \geq 1} \sup_{\omega} \frac{1}{m} \sum_{j=1}^m H(S_{i,j} | C_{i,j} )_{\cN_i'(\omega_{Y_{i,j}})},
\end{align}
where we used the chain rule and then strong subadditivity of the von Neumann entropy.
Now note that each term $H(S_{i,j} | C_{i,j} )_{\cN_i'(\omega_{Y_{i,j}})} \leq \sup_{\omega} H(S_i | C_i)_{\cN'_i(\omega)}$. As a result, $D^{\inf,\reg}(\tr_{A_{i+1}} \circ \cN_i \| \tr_{A_{i+1}} \circ \cM_i) \geq - \sup_{\omega \in \density(Y_{i-1})} H(S_i | C_i)_{\cN_i'(\omega)}$
which shows that in this case, the regularization is not needed. In order to apply Theorem~\ref{thm:reat}, we need to check condition~\eqref{eq: assumptionC N M}. First, we have for any $\omega \in \density(Y_i)$, $\tr(\cM_i(\omega)) = \dim S_i$. In addition, for $\alpha \in [1/2,1]$, we have
\begin{align}
    D^{\inf}_{\Petz,\alpha}&((\tr_{A_{i+1}} \circ \cN_i)^{\otimes m} \| (\tr_{A_{i+1}} \circ \cM_i)^{\otimes m}) \notag\\
    &=\inf_{\substack{\omega \in \density((Y_{i-1})^{\otimes m}) \\ \sigma \in \density((C_{i} \dots C_n)^{\otimes m})}} D_{\Petz, \alpha}((\tr_{Y_i}\cN_i')^{\otimes m}(\omega_{Y_{i-1,1} \dots Y_{i-1,m}}) \| \id_{S_{i,1} \dots S_{1,m}} \otimes \sigma_{C_{i,1} \dots C_{i,m}}) \label{eq:expression-dalpha-opt} \\
    &= - \sup_{\omega} H^{\uparrow}_{\Petz, \alpha}(S_{i,1} \dots S_{i,m} | C_{i,1} \dots C_{i,m})_{\cN_i'^{\otimes m}(\omega)},
\end{align}
using the notation $H^{\uparrow}_{\Petz, \alpha}(D| E)_{\rho} = -\inf_{\sigma \in \density(E)}D_{\Petz,\alpha}(\rho_{DE} \| \id_{D} \otimes \sigma_E)$ from~\cite{tomamichel2014relating}. It is shown in~\cite[Lemma 1]{tomamichel2014relating}, that an explicit choice of $\sigma$ achieves this infimum namely $\sigma^{(\alpha)}_{E} = \frac{(\tr_D \rho_{DE}^{\alpha})^{1/\alpha}}{\tr(\tr_D \rho_{DE}^{\alpha})^{1/\alpha}}$. But in~Lemma~\ref{lem: assumptionC for cond entr}, we showed that for this choice $D_{\Petz,3/2}(\rho_{DE} \| \id_{D} \otimes \sigma^{(\alpha)}_{E}) \leq 4 \log \dim D$. Applying this to the state $\rho = (\tr_{A_{i+1}} \circ \cN_i)^{\otimes m}(\omega)$, an optimal choice for $\sigma$ in~\eqref{eq:expression-dalpha-opt} is given by $\sigma_{m}^{(\alpha)} = \frac{(\tr_{B_{i}^{\otimes m}} \rho^{\alpha})^{1/\alpha}}{\tr(\tr_{B_{i}^{\otimes m}} \rho^{\alpha})^{1/\alpha}}$. We get that for any $\omega \in \density(R_{i-1}^{\otimes m})$,
\begin{align}
    D_{\Petz,3/2}((\tr_{A_{i+1}} \circ \cN_i)^{\otimes m}(\omega) \| \id_{S_i}^{\otimes m} \otimes \sigma^{(\alpha)}_{m}) \leq 4 m \log \dim S_i.
\end{align}
This means that choosing $C = 16 \max_{i} \log \dim S_i$ satisfies condition~\eqref{eq: assumptionC N M}.
\end{proof}

\smallskip

Note that the second order term we achieve with our proof technique is worse than the one achieved in~\cite{dupuis2020entropy} and~\cite{metger2022generalised}. In addition, the statement of~\cite{metger2022generalised} is stronger in that it also includes conditioning on the system $Y_i$ provided a non-signalling assumption is satisfied. Nevertheless, we believe that our new proof technique, which is more naturally adapted to find upper bounds on the max-entropy $H_{\max}$ (as opposed to the techniques of~\cite{metger2022generalised} which naturally apply to the min-entropy $H_{\min}$) could lead to insights and improvements for the applications of entropy accumulation. However, this is outside the scope of this paper and we leave it for future work.

\section{Useful properties}

\begin{lemma}
\label{lem: assumptionC for cond entr}
    Let $\alpha \in [1/2,1]$, $\rho_{AB} \in \density(AB)$ and $\sigma^{(\alpha)}_B = \frac{\left(\tr_A\rho_{AB}^{\alpha}\right)^{\frac{1}{\alpha}}}{Z}$, where $Z = \tr \left(\left(\tr_A\rho_{AB}^{\alpha}\right)^{\frac{1}{\alpha}}\right)$. Let $d_A = \dim A$. Then it holds that
    \begin{align}
        D_{\Petz,\frac{3}{2}}(\rho_{AB} \| \id_{A} \otimes \sigma_{B}^{(\alpha)}) \leq 4\log d_A.
    \end{align}
\end{lemma}
Note that the choice of the parameter $\frac{3}{2}$ is not arbitrary and this lemma does not hold for higher values. See the discussion in the proof of ~\cite[Corollary III.5]{dupuis2019entropySecondOrder}.

\smallskip
\begin{proof}
    We have
    \begin{align}
        \tr\left(\rho_{AB}^{3/2} (\id_{A} \otimes \sigma_{B}^{(\alpha)})^{-1/2}\right)
        &= Z^{1/2} \tr\left(\rho_{AB}^{3/2} \id_{A} \otimes (\tr_{A} \rho_{AB}^{\alpha})^{-\frac{1}{2\alpha}}\right).
    \end{align}
    We start by showing that $Z \leq d_{A}$. In fact, we use the operator Jensen inequality for the operator concave function $x \mapsto x^{\alpha}$ as follows:
    \begin{align}
        \tr_{A}(\rho_{AB}^{\alpha}) 
        &= d_A \sum_{a} \frac{\bra{a}}{\sqrt{d_A}} \rho_{AB}^{\alpha} \frac{\ket{a}}{\sqrt{d_A}} \\
        &\leq d_A \left(\sum_{a} \frac{\bra{a}}{\sqrt{d_A}} \rho_{AB} \frac{\ket{a}}{\sqrt{d_A}}\right)^{\alpha} \\
        &= d_A^{1-\alpha} \rho_B^{\alpha}.
    \end{align}
    As a result, we get
    \begin{align}
        Z &\leq \tr( (d_A^{1-\alpha} \rho_B^{\alpha})^{\frac{1}{\alpha}}) = d_{A}^{\frac{1-\alpha}{\alpha}} \leq d_A.
    \end{align}
    For the inequality, we used the fact that the function $x \mapsto x^{1/\alpha}$ is monotone and continuous and thus $X \mapsto \tr(X^{\frac{1}{\alpha}})$ is monotone (see e.g.,~\cite[Section 2.2]{carlen2010trace}).

    Now let us consider 
    \begin{align}
    \tr\left(\rho_{AB}^{3/2} \id_{A} \otimes (\tr_{A} \rho_{AB}^{\alpha})^{\frac{1}{\alpha}}\right) 
    &\leq \tr\left(\rho_{AB} \id_{A} \otimes (\tr_{A} \rho_{AB})^{-\frac{1}{2\alpha}}\right) \\
    &\leq \tr(\rho_{AB} \rho_{B}^{-1}) \\
    &\leq d_A,
    \end{align}
    where we used for the first inequality the fact that $\rho_{AB}^{3/2} \leq \rho_{AB}$, $\rho_{AB}^{\alpha} \geq \rho_{AB}$ and the operator anti-monotonicity of the function $x \mapsto x^{-\frac{1}{2\alpha}}$, and for the second inequality the fact that $\rho_{B}^{\frac{1}{2\alpha}} \geq \rho_{B}$. As a result,
    \begin{align}
        D_{\Petz,\frac{3}{2}}(\rho_{AB} \| \id_{A} \otimes \sigma_B^{(\alpha)}) \leq 2 \log (d_A^{1/2} d_A) \leq 4 \log d_A.
    \end{align}
\end{proof}

\begin{proposition}
\label{prop: DH Hmax}
    For $0 \leq \ve < \frac{1}{2}$, we have
    \begin{align}
    H_{\max}^{\sqrt{2\ve}}(B|C)_{\rho} \leq - \inf_{\sigma_{C} \in \density(C)} D_{\Hypo, \ve}(\rho_{BC} \| \id_{B} \otimes \sigma_C).
\end{align}
\end{proposition}
\begin{proof}
Using \cite[Lemma 31]{fang2024generalized} with $\sA = \{\rho_{BC}\}$ and $\sB = \{\id_{B} \otimes \sigma_C : \sigma_{C} \in \density(C)\}$, we can write
\begin{align}
    -\inf_{\sigma_{C} \in \density(C)} D_{\Hypo, \ve}(\rho_{BC} \| \id_{B} \otimes \sigma_C) = \log \inf_{0 \leq M \leq I} \left\{ \sup_{\sigma_{C} \in \density(C)} \{\tr(M_{BC} I_B \otimes \sigma_C) : \tr(M_{BC} \rho_{BC}) \geq 1- \ve \right\}.
\end{align}
Let $M_{BC}$ be such that $\tr(M_{BC}\rho_{BC}) \geq 1-\ve$, define $\tilde{\rho}_{BC} = \sqrt{M_{BC}} \rho_{BC} \sqrt{M_{BC}}$. Then, by the gentle measurement lemma, we have $P(\rho, \tilde{\rho}) \leq \sqrt{2\ve}$ (see e.g.,~\cite[Lemma A.3]{dupuis2014generalized}). Then, using Lemma~\ref{lem:bound on fidelity}, we get
\begin{align}
    \sup_{\sigma_{C}\in \density(C)} \left\| (\sqrt{M_{BC}} \rho_{BC} \sqrt{M_{BC}})^{\frac{1}{2}} \id_B \otimes \sigma_C^{\frac{1}{2}} \right\|_1^2 \leq \sup_{\sigma_C} \tr(M_{BC} I_B \otimes \sigma_C)
\end{align}
As such,
\begin{align}
    -\inf_{\sigma_{C}  \in \density(C)} & D_{\Hypo, \ve}(\rho_{BC} \| \id_{B} \otimes \sigma_C) \notag \\
    &\geq \log \inf_{0 \leq M \leq I}  \sup_{\sigma_{C}} \left\{ \left\| (\sqrt{M_{BC}} \rho_{BC} \sqrt{M_{BC}})^{\frac{1}{2}} \id_B \otimes \sigma_C^{\frac{1}{2}} \right\|_1^2 : \tr(M_{BC} \rho_{BC}) \geq 1- \ve \right\} \\
    &\geq \log \inf_{\substack{\tilde{\rho}_{BC} \in \PSD(BC) \\ \tr(\tilde{\rho}) \leq 1 \\ P(\rho, \tilde{\rho}) \leq \sqrt{2\ve}}} \sup_{\sigma_C \in \density(C)} \left\| \tilde{\rho}_{BC}^{\frac{1}{2}} \id_{B} \otimes \sigma_C^{\frac{1}{2}} \right\|_1^2\\
    &= H_{\max}^{\sqrt{2\ve}}(B|C)_{\rho}.
\end{align}
\end{proof}
\begin{lemma}
\label{lem:bound on fidelity}
    Let $\rho \in \density(A)$ and $\sigma, M \in \PSD(A)$. Then it holds that
    \begin{align}
        \left\| (\sqrt{M}\rho\sqrt{M})^{\frac{1}{2}} \sigma^{\frac{1}{2}} \right\|_1^2 \leq \tr(M \sigma).
    \end{align}
\end{lemma}
\begin{proof}
    This fact is used in~\cite[Proposition 4.2]{dupuis2014generalized}. It uses the semidefinite program for the fidelity $\| \sqrt{\omega} \sqrt{\theta} \|_{1}^2 = \min\{ \tr(Z \theta) : \omega_{AE} \leq Z \otimes I_E, Z \geq 0\}$~\cite[Section 5]{watrous2009semidefinite}, where $\omega_{AE}$ is a purification of $\omega$. Let $\rho_{AE}$ be a purification of $\rho_A$. Then we have $\sqrt{M_A} \rho_{AE} \sqrt{M_A} \leq M_A \otimes I_{E}$ and $\sqrt{M_A} \rho_{AE} \sqrt{M_A}$ is a purification of $\sqrt{M} \rho_A \sqrt{M}$. As a result $Z = M$ is feasible for the semidefinite program above and we get the desired result.
\end{proof}



