\section{Proof of \texorpdfstring{\cref{prop:delay_violation}}{Proposition~\ref{prop:delay_violation}}}\label{app:proof:prop:delay_violation}
We will prove \cref{prop:delay_violation} by first establishing a lower bound on the conditional probability $\Pr(T_{\mathrm{tot},t}\le T \,|\, D_{\mathrm{ul},t},D_{\mathrm{dl},t},g_{l,k})$, and then use it to bound the desired marginal probability $\Pr(T_{\mathrm{tot},t}> T \,|\, g_{l,k})$.
We first present the bound on $\Pr(T_{\mathrm{tot},t}\le T \,|\, D_{\mathrm{ul},t},D_{\mathrm{dl},t},g_{l,k})$.
\begin{lemma}\label{lemma:conditional_lb}
  For a composite model $g_{l,k}$ satisfying $\tau_{\mathrm{ul},l}+\tau_{f_k}\le T$, the conditional probability of satisfying the deadline given $D_{\mathrm{ul},t}$ and $D_{\mathrm{dl},t}$ is lower bounded as
  \begin{align*}
    &\Pr(T_{\mathrm{tot},t}\le T \,|\, D_{\mathrm{ul},t},D_{\mathrm{dl},t},g_{l,k})\nonumber\\
    &\quad\ge \exp\left(\left(\textsf{SNR}_{\mathrm{ul}}^{-1}+\textsf{SNR}_{\mathrm{dl}}^{-1}\right)\left(1-2^\frac{D_{\mathrm{ul},t}+D_{\mathrm{dl},t}}{B(T-\tau_{\mathrm{ul},l}-\tau_{f_k})}\right)\right).
  \end{align*}
\end{lemma}
\begin{IEEEproof}
  See \cref{app:proof:lemma:conditional_lb}.
\end{IEEEproof}

We now proceed to bound $\Pr(T_{\mathrm{tot},t}> T \,|\, g_{l,k})$.
From the law of total probability,
\begin{align*}
  &\Pr(T_{\mathrm{tot},t} > T\,|\,g_{l,k})\nonumber\\
  &\quad=1-\int_{0}^{\infty}\int_{0}^{\infty} \Pr(T_{\mathrm{tot},t} \le T \,|\, D_{\mathrm{ul},t}=\xi, D_{\mathrm{dl},t}=\psi,g_{l,k})\nonumber\\
  &\quad\qquad\quad\times p(D_{\mathrm{ul},t}=\xi,D_{\mathrm{dl},t}=\psi \,|\, g_{l,k})\,\mathrm{d}\xi\,\mathrm{d}\psi.
\end{align*}
Since the CDF is non-negative, restricting the domain of integration yields a lower bound on the integral. Thus, for any $D_{\mathrm{ul},t}'$ and $D_{\mathrm{dl},t}'$,
\begin{align}
  &\Pr(T_{\mathrm{tot},t} > T \,|\, g_{l,k})\nonumber\\
  &\quad\le\! 1\!-\! \int_{0}^{D_{\mathrm{ul},t}'}\!\int_{0}^{D_{\mathrm{dl},t}'}\!\Pr(T_{\mathrm{tot},t}\! \le\! T| D_{\mathrm{ul},t}\!=\!\xi,D_{\mathrm{dl},t}\!=\!\psi,g_{l,k})\nonumber\\
  &\quad\qquad\quad\times p(D_{\mathrm{ul},t}=\xi,D_{\mathrm{dl},t}=\psi \,|\, g_{l,k})\,\mathrm{d}\xi\,\mathrm{d}\psi\nonumber \\
  &\quad\overset{(a)}{\le} 1- \Pr(T_{\mathrm{tot},t} \le T \,|\, D_{\mathrm{ul},t}=D_{\mathrm{ul},t}',D_{\mathrm{dl},t}=D_{\mathrm{dl},t}',g_{l,k})\nonumber\\
  &\quad\qquad\quad\times \int_{0}^{D_{\mathrm{ul},t}'}\!\int_{0}^{D_{\mathrm{dl},t}'}\!p(D_{\mathrm{ul},t}\!=\!\xi,D_{\mathrm{dl},t}\!=\!\psi | g_{l,k})\,\mathrm{d}\xi\,\mathrm{d}\psi\nonumber\\
  &\quad\overset{(b)}{=} 1-\Pr(T_{\mathrm{tot},t} \le T \,|\, D_{\mathrm{ul},t}=D_{\mathrm{ul},t}',D_{\mathrm{dl},t}=D_{\mathrm{dl},t}',g_{l,k})\nonumber\\
  &\quad\qquad\quad\times \Pr(D_{\mathrm{ul},t}\le D_{\mathrm{ul},t}',D_{\mathrm{dl},t}\le D_{\mathrm{dl},t}' \,|\, g_{l,k}).\label{eq:lemma_marginal_bound_tmp0}
\end{align}
Here, inequality $(a)$ follows from the fact that $\Pr(T_{\mathrm{tot},t} \le T \,|\, D_{\mathrm{ul},t},D_{\mathrm{dl},t},g_{l,k})$ is nonincreasing in $D_{\mathrm{ul},t}$ and $D_{\mathrm{dl},t}$, and equality $(b)$ is obtained by noting that the integral evaluates to the joint CDF.

Let $L(D_{\mathrm{ul},t},D_{\mathrm{dl},t},l,k)$ denote the lower bound given in \cref{lemma:conditional_lb}, i.e.,
\begin{align*}
  &L(D_{\mathrm{ul},t},D_{\mathrm{dl},t},l,k)\nonumber\\
  &\quad=\exp\left(\left(\textsf{SNR}_{\mathrm{ul}}^{-1}+\textsf{SNR}_{\mathrm{dl}}^{-1}\right)\left(1-2^\frac{D_{\mathrm{ul},t}+D_{\mathrm{dl},t}}{B(T-\tau_{\mathrm{ul},l}-\tau_{f_k})}\right)\right).
\end{align*}
Substituting into \eqref{eq:lemma_marginal_bound_tmp0} gives us the bound
\begin{align}
  &\Pr(T_{\mathrm{tot},t} > T \,|\, g_{l,k})\nonumber\\
  &\quad\le 1- L(D_{\mathrm{ul},t}', D_{\mathrm{dl},t}',l,k)\nonumber\\
  &\quad\qquad\quad\times\Pr(D_{\mathrm{ul},t}\le D_{\mathrm{ul},t}',D_{\mathrm{dl},t}\le D_{\mathrm{dl},t}' \,|\, g_{l,k}).\label{eq:lemma_marginal_bound_tmp1}
\end{align}

The probability $\Pr(D_{\mathrm{ul},t}\le D_{\mathrm{ul},t}',D_{\mathrm{dl},t}\le D_{\mathrm{dl},t}' \,|\, g_{l,k})$ is unknown as it depends on the black-box encoder/decoder models $(e_l,d_l)$ and the edge model $f_k$ and the unknown distribution $P_{X}$. Furthermore, since $D_{\mathrm{ul},t}$ and $D_{\mathrm{dl},t}$ depend on the same input, they are in general not independent.
Instead, we proceed to derive a lower bound on $\Pr(D_{\mathrm{ul},t}\le D_{\mathrm{ul},t}',D_{\mathrm{dl},t}\le D_{\mathrm{dl},t}' \,|\, g_{l,k})$ using the unlabeled calibration dataset $\mathcal{U}$. The bound is presented in the following lemma.
\begin{lemma}\label{lemma:joint_size_lb}
  Let $\bar{D}_{\mathrm{ul},l}(n)$ and $\bar{D}_{\mathrm{dl},l,k}(m)$ be defined as in \cref{eq:def_bar_d_ul,eq:def_bar_d_dl}. Then, for any $n,m\in\{1,\ldots,N_{\mathcal{U}}\}$,
  \begin{align*}
    &\Pr(D_{\mathrm{ul},t}\!\le\! \bar{D}_{\mathrm{ul},l}(n),D_{\mathrm{dl},t}\!\le\! \bar{D}_{\mathrm{dl},l,k}(m) \,|\, g_{l,k})\!\ge\! \frac{n+m}{N_{\mathcal{U}}+1}-1,
  \end{align*}
  where the probability is over $X\sim P_{X}$.
\end{lemma}
\begin{IEEEproof}
  See \cref{app:proof:lemma:joint_size_lb}.
\end{IEEEproof}

Combining \cref{lemma:joint_size_lb} with \cref{eq:lemma_marginal_bound_tmp1}, and setting $D_{\mathrm{ul},t}'=\bar{D}_{\mathrm{ul},l}(n)$ and $D_{\mathrm{dl},t}'=\bar{D}_{\mathrm{dl},l,k}(m)$ yields
\begin{align*}
  &\Pr(T_{\mathrm{tot},t} > T \,|\, g_{l,k})\nonumber\\
  &\quad\textstyle\le 1- L\left(\bar{D}_{\mathrm{ul},l}(n), \bar{D}_{\mathrm{dl},l,k}(m),l,k\right)\left(\frac{n}{N_{\mathcal{U}}+1}+\frac{m}{N_{\mathcal{U}}+1}-1\right)\\
  &\quad\textstyle=1- L\left(\bar{D}_{\mathrm{ul},l}(n), \bar{D}_{\mathrm{dl},l,k}(m),l,k\right)
  \left(\frac{n+m}{N_{\mathcal{U}}+1}-1\right).      
\end{align*}
for any $n,m\in\{1,\ldots,N_{\mathcal{U}}\}$. To complete the proof, define
\begin{align*}
  \textstyle\bar{\beta}_{\mathrm{cal}}(l,k,n,m)&=\ln L\left(\bar{D}_{\mathrm{ul},l}(n), \bar{D}_{\mathrm{dl},l,k}(m),l,k\right)\\
  &\textstyle=\!\!\left(\!\textsf{SNR}_{\mathrm{ul}}^{-1}\!\!+\!\textsf{SNR}_{\mathrm{dl}}^{-1}\!\right)\!\left(\!1\!\!-\!\!2^\frac{\bar{D}_{\mathrm{ul},l}(n)+\bar{D}_{\mathrm{dl},l,k}(m)}{B(T-\tau_{\mathrm{ul},l}-\tau_{f_k})}\!\right),
\end{align*}
and choose $n$ and $m$ such that the bound is minimized.



\section{Proof of \texorpdfstring{\cref{lemma:conditional_lb}}{Lemma~\ref{lemma:conditional_lb}}}\label{app:proof:lemma:conditional_lb}
For any $0\le \phi\le T$ we have
\begin{align*}
  &\Pr(T_{\mathrm{tot},t}\le T\,|\,D_{\mathrm{ul},t},D_{\mathrm{dl},t},g_{l,k})\nonumber\\
  &\quad=\Pr(T_{\mathrm{ul},t}+T_{\mathrm{dl},t}\le T\,|\,D_{\mathrm{ul},t},D_{\mathrm{dl},t},g_{l,k})\\
  &\quad\ge \Pr(T_{\mathrm{ul},t}\le T-\phi, T_{\mathrm{dl},t}\le \phi\, |\,D_{\mathrm{ul},t},D_{\mathrm{dl},t},g_{l,k})\\
  &\quad= \Pr(T_{\mathrm{ul},t}\le T-\phi \,|\, D_{\mathrm{ul},t},g_{l,k})\Pr(T_{\mathrm{dl},t}\le \phi\,|\,D_{\mathrm{dl},t},g_{l,k}),
\end{align*}
where the second inequality follows from the fact that $T_{\mathrm{ul},t}$ and $T_{\mathrm{dl},t}$ are conditionally independent given $D_{\mathrm{ul},t},D_{\mathrm{dl},t},g_{l,k}$ (since $h_{\mathrm{ul},t}$ and $h_{\mathrm{dl},t}$ are independent), and that $T_{\mathrm{ul},t}$ is independent of $D_{\mathrm{dl},t}$, while $T_{\mathrm{dl},t}$ is independent of $D_{\mathrm{dl},t}$.
Expanding the terms first using \cref{eq:T_ul,eq:T_dl} and then using \cref{eq:capacity_ul,eq:capacity_dl} yields
\begin{align}
  &\Pr(T_{\mathrm{ul},t}\le T-\phi \,|\, D_{\mathrm{ul},t},g_{l,k})\Pr(T_{\mathrm{dl},t}\le \phi\,|\,D_{\mathrm{dl},t},g_{l,k})\nonumber\\
  &\quad\textstyle= \Pr\left(R_{\mathrm{ul},t}\!\ge\! \frac{D_{\mathrm{ul},t}}{T-\phi-\tau_{\mathrm{ul},l}} \,\middle|\, D_{\mathrm{ul},t}\right)\!\Pr\left(R_{\mathrm{dl},t}\!\ge\!\frac{D_{\mathrm{dl},t}}{\phi-\tau_{f_{k}}} \,\middle|\, D_{\mathrm{dl},t}\right)\nonumber\\
  &\quad\textstyle\overset{(a)}{=} \Pr\left(|h_{\mathrm{ul},t}|^2\ge \frac{2^{\frac{D_{\mathrm{ul},t}}{B\left(T-\phi-\tau_{\mathrm{ul},l}\right)}}-1}{\textsf{SNR}_{\mathrm{ul}}} \,\middle|\, D_{\mathrm{ul},t}\right)\nonumber\\
  &\qquad\quad\textstyle\times\Pr\left(|h_{\mathrm{dl},t}|^2\ge \frac{2^{\frac{D_{\mathrm{dl},t}}{B\left(\phi-\tau_{f_{k}}\right)}}-1}{\textsf{SNR}_{\mathrm{dl}}} \,\middle|\, D_{\mathrm{dl},t}\right)\nonumber\\
  &\quad\textstyle= \exp\left(\frac{1-2^{\frac{D_{\mathrm{ul},t}}{B(T-\phi-\tau_{\mathrm{ul},l})}}}{\textsf{SNR}_{\mathrm{ul}}}\right)
  \exp\left(\frac{1-2^{\frac{D_{\mathrm{dl},t}}{B(\phi-\tau_{f_k})}}}{\textsf{SNR}_{\mathrm{dl}}}\right)\nonumber\\
  &\quad=\textstyle \exp\left(\frac{1-2^{\frac{D_{\mathrm{ul},t}}{B(T-\phi-\tau_{\mathrm{ul},l})}}}{\textsf{SNR}_{\mathrm{ul}}}+\frac{1-2^{\frac{D_{\mathrm{dl},t}}{B(\phi-\tau_{f_k})}}}{\textsf{SNR}_{\mathrm{dl}}}\right),\label{eq:T_ul_bound_tmp}
\end{align}
where equality $(a)$ comes from the fact that $|h_{\text{ul},t}|^2$ and $|h_{\text{dl},t}|^2$ are exponentially distributed following the assumption of Rayleigh fading.

The best bound is obtained by maximizing $\phi\in [0,T]$. The derivative of the logarithm of \eqref{eq:T_ul_bound_tmp} is
\begin{align}
  &\frac{\mathrm{d}}{\mathrm{d}\phi}\left(\frac{1-2^{\frac{D_{\mathrm{ul},t}}{B(T-\phi-\tau_{\mathrm{ul},l})}}}{\textsf{SNR}_{\mathrm{ul}}}+\frac{1-2^{\frac{D_{\mathrm{dl},t}}{B(\phi-\tau_{f_k})}}}{\textsf{SNR}_{\mathrm{dl}}}\right)\nonumber\\
  &\quad\textstyle=-\textsf{SNR}_{\mathrm{ul}}^{-1}\frac{\mathrm{d}}{\mathrm{d}\phi}\left(2^{\frac{D_{\mathrm{ul},t}}{B(T-\phi-\tau_{\mathrm{ul},l})}}\right)\!-\! \textsf{SNR}_{\mathrm{dl}}^{-1}\frac{\mathrm{d}}{\mathrm{d}\phi}\left(2^{\frac{D_{\mathrm{dl},t}}{B(\phi-\tau_{f_k})}}\right)\nonumber\\
  &\quad\textstyle=-\textsf{SNR}_{\mathrm{ul}}^{-1}D_{\mathrm{ul},t}\log_2(D_{\mathrm{ul},t})\left(\frac{2^{\frac{D_{\mathrm{ul},t}}{B(T-\phi-\tau_{\mathrm{ul},l})}}}{B(T-\phi-\tau_{\mathrm{ul},l})^2}\right)\nonumber\\
  &\quad\qquad\textstyle+\textsf{SNR}_{\mathrm{dl}}^{-1}D_{\mathrm{dl},t}\log_2(D_{\mathrm{dl},t})\left(\frac{2^{\frac{D_{\mathrm{dl},t}}{B(\phi-\tau_{f_k})}}}{B(\phi-\tau_{f_k})^2}\right)\label{eq:T_ul_bound_tmp2}
\end{align}
The $\phi$ that maximizes~\eqref{eq:T_ul_bound_tmp} is given by a root in this equation, which does not have a closed-form solution. Instead we aim to pick $\phi$ such that we obtain a closed-form solution that still provides a good bound. 
To this end, note that \cref{eq:T_ul_bound_tmp2} is dominated by the exponents, and thus a reasonable strategy would be to pick $\phi$ to balance the exponents, i.e., to satisfy $\frac{D_{\mathrm{ul},t}}{B(T-\phi-\tau_{\mathrm{ul},l})}=\frac{D_{\mathrm{dl},t}}{B(\phi-\tau_{f_k})}$.
By isolating $\phi$ we obtain
\begin{align*}
  \phi=\frac{D_{\mathrm{ul},t}\tau_{f_k}+D_{\mathrm{dl},t}(T-\tau_{\mathrm{ul},l})}{D_{\mathrm{ul},t}+D_{\mathrm{dl},t}}.
\end{align*}
Substituting this into~\eqref{eq:T_ul_bound_tmp} yields
\begin{align*}
  &\Pr(T_{\mathrm{tot},t}\le T\,|\,D_{\mathrm{ul},t},D_{\mathrm{dl},t},g_{l,k})\nonumber\\
  &\quad\ge \exp\left(\frac{1-2^{\frac{D_{\mathrm{ul},t}+D_{\mathrm{dl},t}}{B(T-\tau_{\mathrm{ul},l}-\tau_{f_k})}}}{\textsf{SNR}_{\mathrm{ul}}}+\frac{1-2^{\frac{D_{\mathrm{ul},t}+D_{\mathrm{dl},t}}{B(T-\tau_{\mathrm{ul},l}-\tau_{f_k})}}}{\textsf{SNR}_{\mathrm{dl}}}\right)\\
  &\quad= \exp\left(\left(\textsf{SNR}_{\mathrm{ul}}^{-1}+\textsf{SNR}_{\mathrm{dl}}^{-1}\right)\left(1-2^{\frac{D_{\mathrm{ul},t}+D_{\mathrm{dl},t}}{B(T-\tau_{\mathrm{ul},l}-\tau_{f_k})}}\right)\right),
\end{align*}
which is the desired expression.

\section{Proof of \texorpdfstring{\cref{lemma:joint_size_lb}}{Lemma~\ref{lemma:joint_size_lb}}}\label{app:proof:lemma:joint_size_lb}
From Boole's inequality,
\begin{align}
  &\Pr(D_{\mathrm{ul},t}\le \bar{D}_{\mathrm{ul},l}(n),D_{\mathrm{dl},t}\le \bar{D}_{\mathrm{dl},l,k}(m) \,|\, g_{l,k})\nonumber\\
  &\quad\ge \Pr(D_{\mathrm{ul},t}\le \bar{D}_{\mathrm{ul},l}(n) \,|\, g_{l,k})\nonumber\\
  &\quad\quad+ Pr(D_{\mathrm{dl},t}\le \bar{D}_{\mathrm{dl},l,k}(m) \,|\, g_{l,k}) - 1.\label{eq:lemma_marginal_bound_tmp2}
\end{align}

Conditioned on the threshold $\lambda_{l,k}$ and the model choice $g_{l,k}$, the marginal data size samples $\{D_{\mathrm{ul},l}(X_n^{(\mathcal{U})})\}_{n=1}^{N_{\mathcal{U}}}$ and $\{D_{\mathrm{dl},l,k}(X_n^{(\mathcal{U})})\}_{n=1}^{N_{\mathcal{U}}}$ are each a collection of independent samples drawn from the marginal distributions $p(D_{\mathrm{ul},l}(X_n) \,|\, g_{l,k})$ and $p(D_{\mathrm{dl},l,k}(X_n) \,|\, g_{l,k})$, respectively. The data sizes $D_{\mathrm{ul},l}(X)$ and $D_{\mathrm{dl},l,k}(X)$ of a new sample $X\sim P_{X}$ are equally likely to fall in anywhere between the calibration samples, i.e.,
\begin{align*}
  \Pr(D_{\mathrm{ul},l}(X)\le \bar{D}_{\mathrm{ul},l}(n) \,|\, g_{l,k}) &= \frac{n}{N_{\mathcal{U}}+1},\\
  \Pr(D_{\mathrm{dl},l,k}(X)\le \bar{D}_{\mathrm{dl},l,k}(m) \,|\, g_{l,k}) &= \frac{m}{N_{\mathcal{U}}+1},
\end{align*}
for any integers $n,m\in\{1,\ldots,N_{\mathcal{U}}\}$ (see e.g.,~\cite[Appendix D]{conformal}).
Note that this probability is taken over $X\sim P_{X}$, since the data sizes given $X$ and the model choice $g_{l,k}$ are deterministic.

Combining this result with \cref{eq:lemma_marginal_bound_tmp2} yields
\begin{align*}
  &\Pr(D_{\mathrm{ul},t}\le \bar{D}_{\mathrm{ul},l}(n),D_{\mathrm{dl},t}\le \bar{D}_{\mathrm{dl},l,k}(m) \,|\, g_{l,k})\nonumber\\
  &\quad\ge \frac{n}{N_{\mathcal{U}}+1}+\frac{m}{N_{\mathcal{U}}+1}-1\\
  &\quad= \frac{n+m}{N_{\mathcal{U}}+1}-1.
\end{align*}
for any $n,m\in\{1,\ldots,N_{\mathcal{U}}\}$. This completes the proof.

\section{Proof of \texorpdfstring{\cref{prop:delay_violation_dynamic}}{Proposition~\ref{prop:delay_violation_dynamic}}}\label{app:proof:prop:delay_violation_dynamic}
The proof is similar to that of \cref{prop:delay_violation}. We first have the following bound similar to \cref{lemma:conditional_lb}.
\begin{lemma}\label{lemma:conditional_lb_dynamic}
  For a composite model $g_{l,k}$ satisfying $\tau_{\mathrm{ul},l}+\tau_{f_k}\le T$, the conditional probability of satisfying the deadline given $D_{\mathrm{ul},t}$, $D_{\mathrm{dl},t}$, and $R_{\mathrm{ul},t}$ is lower bounded as
  \begin{align*}
    &\Pr(T_{\mathrm{tot},t}\le T \,|\, D_{\mathrm{ul},t},D_{\mathrm{dl},t},R_{\mathrm{ul},t},g_{l,k})\nonumber\\
    &\quad\ge \exp\left(\textsf{SNR}_{\mathrm{dl}}^{-1}\left(1-2^\frac{D_{\mathrm{dl},t}}{B(T-\tau_{\mathrm{ul},l}-\tau_{f_k}-D_{\mathrm{ul},t}/R_{\mathrm{ul},t})}\right)\right).
  \end{align*}
\end{lemma}
\begin{IEEEproof}
  See \cref{app:proof:lemma:conditional_lb_dynamic}.
\end{IEEEproof}
The remainder of the proof proceeds exactly as the proof of \cref{prop:delay_violation}, but using the bound in \cref{lemma:conditional_lb_dynamic} instead of \cref{lemma:conditional_lb}. Specifically, using the fact that $D_{\mathrm{ul},t}$ and $D_{\mathrm{ul},t}$ are independent of $R_{\mathrm{ul},t}$, for any $D_{\mathrm{ul},t}'$ and $D_{\mathrm{dl},t}'$ we have
\begin{align*}
  &\Pr(T_{\mathrm{tot},t} > T \,|\, R_{\mathrm{ul},t},g_{l,k})\nonumber\\
  &\quad\le 1\!-\!\Pr(T_{\mathrm{tot},t}\!\le\! T |D_{\mathrm{ul},t}\!=\!D_{\mathrm{ul},t}',D_{\mathrm{dl},t}\!=\!D_{\mathrm{dl},t}',R_{\mathrm{ul},t},g_{l,k})\nonumber\\
  &\quad\qquad\quad\times \Pr(D_{\mathrm{ul},t}\le D_{\mathrm{ul},t}',D_{\mathrm{dl},t}\le D_{\mathrm{dl},t}' \,|\,g_{l,k})\\
  &\quad\le  1- \hat{L}(D_{\mathrm{ul},t}', D_{\mathrm{dl},t}',R_{\mathrm{ul},t},l,k)\nonumber\\
  &\quad\qquad\quad\times\Pr(D_{\mathrm{ul},t}\le D_{\mathrm{ul},t}',D_{\mathrm{dl},t}\le D_{\mathrm{dl},t}' \,|\, g_{l,k}),
\end{align*}
  where
\begin{align*}
  &\hat{L}(D_{\mathrm{ul},t},D_{\mathrm{dl},t},R_{\mathrm{ul},t},l,k)\nonumber\\
  &\quad=\exp\left(\textsf{SNR}_{\mathrm{dl}}^{-1}\left(1-2^\frac{D_{\mathrm{dl},t}}{B(T-\tau_{\mathrm{ul},l}-\tau_{f_k}-D_{\mathrm{ul},t}/R_{\mathrm{ul},t})}\right)\right).
\end{align*}
Using \cref{lemma:joint_size_lb}, we obtain
  \begin{align*}
  &\Pr(T_{\mathrm{tot},t} > T \,|\, R_{\mathrm{ul},t},g_{l,k})\nonumber\\
  &\quad\le 1- \hat{L}\left(\bar{D}_{\mathrm{ul},l}(n), \bar{D}_{\mathrm{dl},l,k}(m),R_{\mathrm{ul},t},l,k\right)\nonumber\\
  &\quad\qquad\quad\times\left(\frac{n+m}{N_{\mathcal{U}}+1}-1\right)
\end{align*}
for any $n,m\in\{1,\ldots,N_{\mathcal{U}}\}$,
where 
$\bar{D}_{\mathrm{ul},l}(n)$ and $\bar{D}_{\mathrm{dl},l,k}(m)$ are defined as in \cref{eq:def_bar_d_ul_dynamic,eq:def_bar_d_dl_dynamic}, respectively.
The proof is completed by defining
\begin{align*}
  \textstyle\hat{\beta}_{\mathrm{cal}}(l,k,n,m)&=\ln \hat{L}\left(\bar{D}_{\mathrm{ul},l}(n), \bar{D}_{\mathrm{dl},l,k}(m),R_{\mathrm{ul},t},l,k\right)\\
  &=\textstyle\textsf{SNR}_{\mathrm{dl}}^{-1}\!\left(\!1\!-\!2^\frac{\bar{D}_{\mathrm{dl},l,k}(m)}{B(T-\tau_{\mathrm{ul},l}-\tau_{f_k}-\bar{D}_{\mathrm{ul},l}(n)/R_{\mathrm{ul},t})}\right),
\end{align*}
and minimizing over $n$ and $m$.

\section{Proof of \texorpdfstring{\cref{lemma:conditional_lb_dynamic}}{Lemma~\ref{lemma:conditional_lb_dynamic}}}\label{app:proof:lemma:conditional_lb_dynamic}
The proof is similar to that of \cref{lemma:conditional_lb}. For any $0\le \phi\le T$ we have
\begin{align*}
  &\Pr(T_{\mathrm{tot},t}\le T\,|\,D_{\mathrm{ul},t},D_{\mathrm{dl},t},R_{\mathrm{ul},t},g_{l,k})\nonumber\\
  &\quad\ge \Pr(T_{\mathrm{ul},t}\le T-\phi \,|\, D_{\mathrm{ul},t},R_{\mathrm{ul},t},g_{l,k})\nonumber\\
  &\qquad\quad\times\Pr(T_{\mathrm{dl},t}\le \phi\,|\,D_{\mathrm{dl},t},g_{l,k}),
\end{align*}
where we used that $T_{\mathrm{dl},t}$ is independent of $R_{\mathrm{ul},t}$.
Expanding the terms first using \cref{eq:T_ul,eq:T_dl} and then using \cref{eq:capacity_ul,eq:capacity_dl} yields
\begin{align*}
  &\Pr(T_{\mathrm{ul},t}\le T-\phi \,|\, D_{\mathrm{ul},t},R_{\mathrm{ul},t},g_{l,k})\Pr(T_{\mathrm{dl},t}\le \phi\,|\,D_{\mathrm{dl},t},g_{l,k})\\
  &\quad\textstyle= \mathbbm{1}\left[R_{\mathrm{ul},t}\ge \frac{D_{\mathrm{ul},t}}{T-\phi-\tau_{\mathrm{ul},l}}\right]\Pr\left(R_{\mathrm{dl},t}\ge \frac{D_{\mathrm{dl},t}}{\phi-\tau_{f_{k}}} \,\middle|\, D_{\mathrm{dl},t}\right)\\
  &\quad\textstyle=\mathbbm{1}\left[R_{\mathrm{ul},t}\!\ge\! \frac{D_{\mathrm{ul},t}}{T-\phi-\tau_{\mathrm{ul},l}}\right]\Pr\left(\!|h_{\mathrm{dl},t}|^2\!\ge\! \frac{2^{\frac{D_{\mathrm{dl},t}}{B\left(\phi-\tau_{f_{k}}\right)}}-1}{\textsf{SNR}_{\mathrm{dl}}} \middle| D_{\mathrm{dl},t}\!\right)\\
  &\quad\textstyle= \mathbbm{1}\left[R_{\mathrm{ul},t}\ge \frac{D_{\mathrm{ul},t}}{T-\phi-\tau_{\mathrm{ul},l}}\right]
  \exp\left(\frac{1-2^{\frac{D_{\mathrm{dl},t}}{B(\phi-\tau_{f_k})}}}{\textsf{SNR}_{\mathrm{dl}}}\right).
  \end{align*}
  As in the proof of \cref{lemma:conditional_lb}, the best bound is obtained by maximizing the expression over $\phi\in[0,T]$. Since the exponential factor is monotonically increasing in $\phi$, this happens at the largest value of $\phi$ that satisfies the condition in the indicator function, i.e., $\phi= T-\tau_{\mathrm{ul},l}-D_{\mathrm{ul},t}/R_{\mathrm{ul},t}$. By substituting this into the bound, we obtain
  \begin{align*}
  &\Pr(T_{\mathrm{tot},t}\le T\,|\,D_{\mathrm{ul},t},D_{\mathrm{dl},t},R_{\mathrm{ul},t},g_{l,k})\nonumber\\
  &\quad\textstyle\ge
  \exp\left(\frac{1-2^{\frac{D_{\mathrm{dl},t}}{B(T-\tau_{\mathrm{ul},l}-D_{\mathrm{ul},t}/R_{\mathrm{ul},t}-\tau_{f_k})}}}{\textsf{SNR}_{\mathrm{dl}}}\right).
\end{align*}
Rearranging yields the desired result.

