\section{Method}
\label{sec:method}
\vspace{-1mm}


%%% NOTATION

\subsection{Problem Setup}\label{subsec:problem-setup}
Let $\scenario \in \scenariospace$ denote a random variable with probability distribution $\scenariodist$ over some environmental conditions. Let $\metric \in \metricspace$ be a random variable corresponding to the value of a metric of interest, with conditional distribution $\scenariodist$.
For example, $\scenario$ may represent the environmental conditions for a driving scenario (road geometry, location of road agents, road agent intents), and $\metric$ could represent the minimum time-to-collision experienced by an AV planner when rolled out in the scenario. 
Our goal is to estimate the expected value of $\metric$ over the joint distribution of $(\scenario, \metric)$,
\begin{align}
\mu \equiv \underset{\scenario \sim \scenariodist}{\mathbb{E}}\left[\underset{\metric \sim \metricdist}{\mathbb{E}}[\metric \mid \scenario]\right].
\end{align}
We assume that we have a measurement of $F$ on $\npaired$ samples from $P_X$, $\{(\scenario_i, \metric_i)\}_{i=1}^{\npaired}$. A na\"ive Monte Carlo estimator of $\mu$ corresponds to the empirical mean,
\begin{align}
\label{eq:mc_estimator}
    \hat{\mu}_\mathrm{MC} &:= \frac1n\sum_{i=1}^\npaired \metric_i, & \Var[\hat{\mu}_\mathrm{MC}] &= \frac1n \Var[ \metric ] \approx \frac{1}{n^2} \sum_{i=1}^N ( F_i - \hat{\mu}_\mathrm{MC} )^2.
\end{align}

Cheaper surrogate test platforms, e.g. log-replay simulation, allow us to measure surrogate metrics $\surrogate$ conditioned on a scenario $\scenario$. These surrogate measurements may be stochastic themselves, so we model them as a random vector in $\surrogatespace$ with conditional distribution $\surrogatedist$. Importantly, we assume that we can obtain surrogate measurements both on the $\npaired$ scenarios for which we have a measurement of $\metric$, as well as on additional logged scenarios, e.g., those sampled during tests of other systems or in human-operated data collection. 
Ultimately, we assume that we have $\npaired$ paired samples $\paireddata = \{(X_i, \metric_i, \surrogate_i\}_{i=1}^\npaired$, and $\nsurrogate$ surrogate-only samples, $\surrogatedata = \{(\scenario'_j, \surrogate'_j)\}_{j=1}^\nsurrogate$, where 
\begin{align*}
    \scenario_i \sim \scenariodist \quad &\forall\,i=1,\dots,\npaired 
    & \scenario'_j \sim \scenariodist \quad & \forall\,j=1,\dots,\nsurrogate \\
    \metric_i \sim \metricdist(\cdot \mid \scenario_i) \quad &\forall\,i=1,\dots,\npaired \\
    \surrogate_i \sim \surrogatedist(\cdot \mid \scenario_i) \quad &\forall\,i=1,\dots,\npaired
    & \surrogate'_j \sim \surrogatedist(\cdot \mid \scenario'_j) \quad &\forall\,j=1,\dots,\nsurrogate
\end{align*}


Our goal is to strategically leverage the surrogate metric observations to achieve a tighter estimate for $\mu$. Critically, we make no a priori assumptions on the relationship between $\metricdist$ and $\surrogatedist$; we treat the surrogate test platforms as a black box. Nevertheless, as we will demonstrate, a surrogate platform where $\surrogate$ is highly correlated with $\metric$ can enable more efficient, lower variance statistical estimators for $\mu$.

\vspace{-1mm}
\subsection{Control Variate Framework with Surrogate Data}

\begin{figure}[t!]
    \centering
    \begin{subfigure}[t]{0.69\linewidth}
    \centering
    \includegraphics[width=\textwidth]{figures/simulator_correlation-method.pdf}
    \end{subfigure}%
    ~
    \begin{subfigure}[t]{0.3\linewidth}
