% \begin{equation}
% F\vf = A\vc
% \end{equation}

% where $F$ is the linear operator applying different discrete cosine transforms on the samples to obtain the vector $b$.

\paragraph{Higher dimensions}
To see how this phenomenon impacts higher dimensions, we generalize the above relations from scalars in $[-1,1]$ to vectors $[-1,1]^D$. 
Chebyshev interpolation of a function $f:[-1,1]^D \to \mathbb{R}$ involves tensor-products of Chebyshev polynomials and replacing the single index $n$ with multi-index $\vn=(n_1, \hdots, n_D) \in \mathbb{N}^D$:
\begin{align*}
f(\vx) \approx p(\vx) = \sum_{\vn \in \mathcal{N}} c_\vn T_\vn(\vx), &\quad \vx \in [-1,1]^D, \;\\
&\quad c_\vn = \frac{2 - \delta_0(n)}{\pi}\int_{[-1,1]^D} \frac{T_\vn(\vx)f(\vx)}{\sqrt{\vector{1}-\vx^2}} d\vx,
\end{align*}
where $T_\vn(\vx) = T_{n_1}(x_1)T_{n_2}(x_2)\dots T_{n_d}(x_D)$, and $\mathcal{N}$ consists of the set of the multi-indices of the non-zero coefficients of the interpolant $p(\cdot)$. In general, for interpolation purposes, $\mathcal{N}$ corresponds to $ \mathcal{S}^1_{d,D}$ or $ \mathcal{S}^2_{d,D}$ (see \Cref{sec:preliminary}).

We apply the same change of variables in each dimension as in the one-dimensional case, producing
\begin{align}
p(\cos(\theta_1), ..., \cos(\theta_D)) ) &= \sum_{\vn \in \mathcal{N}} c_\vn\cos(\vn\vtheta), \quad \vtheta \in [0,\pi]^D, \\
c_\vn &= \int_{[0,\pi]^D} \cos(\vn\vtheta)f(\cos(\theta_1), ..., \cos(\theta_D)) d\vtheta
\label{eq:poly_approx_nd}
\end{align}
with $\vtheta = (\theta_1,\hdots, \theta_D) \in [0, \pi]^D$ and \
$\cos(\vn\vtheta) = \cos(n_1\theta_1)\cos(n_2\theta_2) \dots \cos(n_D\theta_D)$. Combining the two parts of \Cref{eq:poly_approx_nd}, we obtain
\begin{align}
c_\vn 
% & \sum_{\vm \in \mathcal{N} } c_\vm\int_{[0,\pi]^D} \cos(\vn\vtheta) \cos(\vm\vtheta) d\vtheta \\
%=& \sum_{\vm \in \mathcal{N}} c_\vm\int_{[0,\pi]^D} \left(\prod_{i=0}^D\cos(n_i\theta_i)\right)\left(\prod_{i=0}^D \cos(m_i\theta_i)\right) d\vtheta  \\
=& \sum_{\vm \in \mathcal{N} }c_\vm\prod_{i=0}^D\int_0^\pi \cos(n_i\theta_i)\cos(m_i\theta_i) d\theta_i.\label{eq:inner_product_nd} 
\end{align}

% MJM I think this isn't right...
%Discretizing the integral in \cref{eq:inner_product_nd} using $(N+1)^D$ equispaced points in $[0, \pi]^D$, we produce a tensor of samples $\vThetc_\vk$ indexed by the multi-index $\vk=(k_1, \hdots, k_D)$:
%\begin{equation}
%    \vThetc_\vk = \frac{\left(\vk + \frac{1}{2}\right)\pi}{\vN+1}, \quad \vk=\vzero,\hdots, \vN \in \{\vk\in \mathbb{N}^D\mid 0\leq k_i \leq N,\,\, i = 0, \hdots D\}.
%\end{equation}
Discretizing the integral in \Cref{eq:inner_product_nd}, using $N_i + 1$ points in each dimension $i$, provides the multi-dimensional analogue of \Cref{eq:quad_1D}:
\begin{align}
b_{\vn, \vN} &=
\sum_{\vm\in \mathcal{N}}
c_\vm
\prod_{i=0}^D
\left(\frac{1}{ N_i}
\sum_{k_i =0}^{N_i} 
\cos(n_i \, \theta_{i,k_i} ) \cos(m_i \, \theta_{i,k_i}) 
\right) \\
&= \sum_{k_1=0}^{N_1}  ... \sum_{k_D=0}^{N_D}  \, \left ( \frac{1}{\prod_{i=1}^D N_i} \,  \prod_{i=0}^D \cos(n_i\theta_{i,k_i}) \right ) \, p \left (\cos(\theta_{1,k_1}), \,  ..., \, \cos(\theta_{D,k_D}) 
\right ).
\label{eq:quad_nd}
\end{align}
In particular, note that if we sample on a grid where $N_i \geq \max_{n\in \mathcal{N}} (\max_i n_i)$ as is done traditionally, then $b_{\vn,\vN} = c_\vn$. However, as the number of samples increases exponentially in higher dimensions, this traditional approach becomes prohibitively expensive computationally. To alleviate this issue, we perform a form of under-sampling, leveraging the aliasing result of \Cref{lem:aliasing}; i.e., we use grids with $N_i$ points per dimension $i$, chosen in such a way that the total size $\prod_{i=1}^D N_i$ is roughly equal to $\lvert \mathcal{N} \rvert$ (see \Cref{sec:sampling_schedule} for details). Following \Cref{lem:aliasing}, this results in a linear system of the form
\begin{align}
b_{\vn, \vN} &= \sum_{\vm \in \mathcal{N}} 
c_\vm
\prod_{i=0}^D
\left(
\frac{1}{2}\Delta_{N_i}(m_i+n_i) + \frac{1}{2}\Delta_{N_i} (m_i-n_i)
\right)\\
&= \sum_{k_1=0}^{N_1}  ... \sum_{k_D=0}^{N_D}  \, \left (  \prod_{i=0}^D \cos(n_i\theta_{i,k_i}) \right ) \, p \left (\cos(\theta_{1,k_1}), \,  ..., \, \cos(\theta_{D,k_D}) 
\right ),
\label{eq:quad_nd_matrix} 
\end{align}
which may be written as
\begin{equation}
b_{\vN}  = A_{\mathcal{N}, \vN} \vc = F_{\vN} \vp_\vN.
\label{eq:multi_dim_dct}
\end{equation}
Here, $\vc$ is the vector of Chebyshev coefficients of the polynomial with multi-index corresponding to elements of $\mathcal{N}$, $\vp_\vN$ contains polynomial values from the non-uniform grid with $N_i+1$ samples per dimension, $F_{\vN}$  corresponds to a non-uniform Discrete Cosine Transform (DCT) with $N_i+1$ samples per dimension, and $A_{\mathcal{N}, \vN}$ is a size-$O(\lvert \mathcal{N} \rvert)  \times \lvert \mathcal{N} \rvert $ matrix with rows corresponding to elements of the non-uniform grid and columns corresponding to elements of the set $\mathcal{N}$ with entries
\begin{equation}
   A_{\vn, \vm}= \prod_{i=1}^D \, A^{(i)}_{n_i, m_i}  = \prod_{i=0}^D \left(\frac{1}{2}\Delta_{N_i}(m_i+n_i) + \frac{1}{2}\Delta_{N_i}(m_i-n_i)\right).   \label{eq:aliasing_matrix_nd_diff}
\end{equation}
In particular, the size of this system is \emph{linear} in the number of Chebyshev coefficients ($\lvert \mathcal{N} \rvert$), which leads to computational efficiency. Further, the matrix $A$ can be computed efficiently by considering the products of non-zero elements of lower-dimensional sparse aliasing matrices only.

