\section{Proofs} 
\subsection{Proof of aliasing identity}
\label{sec:lemma_proof}
% \lipsum[71]

\begin{lemma}
 Let $ 1 < N \in \mathbb{N}$. Then, 
 \begin{align}
    &\frac{1}{N} \, \sum_{k=0}^{N-1} \, \cos \left ( \frac{n (k+1/2) \pi}{N} \right ) \, \cos \left ( \frac{m (k+1/2) \pi}{N} \right )  &=\frac{1}{2} \Delta(m+n) + \frac{1}{2}\Delta(m-n) 
    % \frac{\cos( \pi (m+n) /2N) \,}{2} \Delta(m+n) + \frac{\cos( \pi (m-n) /2N) \,}{2}\Delta(m-n) 
\end{align}
where,
\begin{equation}
    \label{eq:aliasing_delta_app}
   \Delta(l)  = 
\left\{
	\begin{array}{ll}
		1  & \mbox{if } l \, \mathrm{mod} \, (4N) \equiv 0 \\
        -1  & \mbox{if } l \, \mathrm{mod} \, (4N) \equiv 2N \\
		0 & \mbox{o.w. }
	\end{array}
\right.
\end{equation}
\end{lemma}
\begin{proof}
Consider,
\begin{align}
    &\frac{1}{N} \, \sum_{n=0}^{N-1} \, \cos \left ( \frac{m (n+1/2) \pi}{N} \right ) \, \cos \left ( \frac{k (n+1/2) \pi}{N} \right ) \\
    &=\frac{1}{N} \, \sum_{n=0}^{N-1} \, \left [ \frac{1}{2} \cos \left ( \frac{(n+1/2) (m+k) \pi}{N} \right )  + \frac{1}{2}  \cos \left ( \frac{ (n+1/2) (m-k) \pi}{N} \right )  \right ] 
\end{align}
Then, consider,
\begin{align}
     \sum_{n=0}^{N-1} \, \cos \left ( \frac{(n+1/2) l \pi}{N} \right ) &= \frac{e^{i \frac{\pi}{2N} l}}{2} \, \sum_{n=0}^{N-1}e^{i \frac{\pi}{N} n \, l} + \frac{e^{-i \frac{\pi}{2N} l}}{2} \, \sum_{n=0}^{N-1}e^{-i \frac{\pi}{N} n \, l}  \\
    &= \left ( \frac{e^{i \frac{\pi}{2} l}}{2} + \frac{e^{-i \frac{\pi}{2} l}}{2}  \right ) \, \frac{\sin(\pi l/2) }{\sin( \pi l /(2N) )}
    \\
    &= \cos( \pi l /2) \, \frac{\sin(\pi l/2) }{\sin( \pi l /(2N) )}
    \\
    &=  \frac{1}{2} \, \frac{\sin(\pi l) }{\sin( \pi l /(2N) )}
\end{align}
since (Dirichlet kernel),
\begin{equation}
    \sum_{n=0}^{N-1} e^{i n \, x}  = e^{i \frac{N-1}{2} x} \, \frac{\sin(N x/2) }{\sin( x/2)}
\end{equation}
and since,
\begin{equation}
    \cos( \pi l /2) \, \sin(\pi l/2) = \frac{1}{2} \sin(\pi l) + \frac{1}{2} \sin(0)= \frac{1}{2} \sin(\pi l) 
\end{equation}
Therefore,
\begin{align}
    &\frac{1}{N} \, \sum_{n=0}^{N-1} \, \left [ \frac{1}{2} \cos \left ( \frac{(n+1/2) (m+k) \pi}{N} \right )  + \frac{1}{2}  \cos \left ( \frac{ (n+1/2) (m-k) \pi}{N} \right )  \right ] \\
    &= \frac{1}{2}  \, \left ( \frac{1}{2N}\, \frac{\sin(\pi (m+k)) }{\sin( \pi (m+k) /(2N) )} + \frac{1}{2N}\, \frac{\sin(\pi (m-k)) }{\sin( \pi (m-k) /(2N) )} \right )  \\
    &= \frac{1}{2} \, \Delta(m+k) + \frac{1}{2} \, \Delta(m-k) 
\end{align}
and the result follows after defining,
\begin{equation}
  \Delta(l) :=   \frac{1}{2N}\, \frac{\sin(\pi l) }{\sin( \pi l /(2N) )} = 
\left\{
	\begin{array}{ll}
		1  & \mbox{if } l \, \mathrm{mod} \, (4N) \equiv 0 \\
        -1  & \mbox{if } l \, \mathrm{mod} \, (4N) \equiv 2N \\
		0 & \mbox{o.w. }
	\end{array}
	\right.
\end{equation}
for all $l \in \mathbb{Z}$.
\end{proof}




