\title{WVSC: Wireless Video Semantic Communication with Multi-frame Compensation}
\author{Bingyan Xie, Yongpeng Wu, Yuxuan Shi, Biqian Feng, Wenjun Zhang, Jihong Park, Tony Q.S. Quek

	\thanks{Bingyan Xie, Yongpeng Wu, Biqian Feng, and Wenjun Zhang are with the Department of Electronic Engineering, Shanghai Jiao Tong University, Shanghai 200240, China (e-mail:bingyanxie, yongpeng.wu, fengbiqian, zhangwenjun@sjtu.edu.cn).}% <-this % stops a space
