\subsection{Proof of \cref{triangle-free-Hamiltonian-DIN-main}}
The proof of \cref{triangle-free-Hamiltonian-DIN-main} involves several intermediate steps that allow us to 
state relationships among the variants of intersection representations introduced above. 
Here, we present these steps and the relationships they involve among variants of IN and DIN, and defer the proofs to the following subsections.

Our first lemma shows that in the case of Hamiltonian DAGs, the notions of weak directed intersection representation and directed intersection representation coincide.

\begin{restatable}{lemma}{dindinleq}\label{lemma:DAG-weakDAG-Hamiltonian}
Let $D = (V, A)$ be a DAG. 
Then, every weak directed intersection representation of $D$ is a directed intersection representation.
Moreover, if $D$ is Hamiltonian, then every directed intersection representation of $D$ is a weak directed intersection representation, and $\DIN(D) = \WDIN(D)$.
\end{restatable}

Next, we show that weak directed intersection representations of a DAG $D$ correspond to intersection representations of a partially ordered graph $(G, \preceq)$, where $G$ is the underlying graph of $D$ and the partial order $\preceq$ is defined by the reachability relation in~$D$.

\begin{restatable}{lemma}{dinleqin}\label{leqDIN-preceqIN}
Let $D = (V, A)$ be a DAG. 
Let $G = (V, E)$ be the underlying graph of $D$ and let $\preceq$ be the partial order on $V$ defined by setting $u\preceq v$ if and only if there exists a $u,v$-path in $D$.
Then, every weak directed intersection representation of the DAG $D$ is an intersection representation of the partially ordered graph $(G, \preceq)$, and vice versa.
In particular, $\WDIN(D) = \IN(G, \preceq)$.
\end{restatable}

Then, we show that for a triangle-free graph $G$, and any given partial order $\preceq$ on the vertices of $G$, the computation of an intersection representation for the partially ordered graph $(G, \preceq)$ can be reduced to the computation of an $\ell$-constrained intersection representation of $G$ for some polynomially computable demand function $\ell$.

\begin{restatable}{theorem}{potolbtri}\label{fromPO-to-LBtri-free-graphs} 
Let $(G,\preceq)$ be a partially ordered graph such that $G = (V,E)$ is triangle-free.
Then, the $\alpha$-ranking $\ell:V\to \mathbb{Z}_+$ of $(G,\preceq)$ can be computed in linear time, and every optimal $\ell$-constrained intersection representation $(U,\varphi)$ of $G$ can be transformed to an optimal $\ell$-constrained intersection representation $(U,\psi)$ of $G$ that is also an optimal intersection representation of $(G,\preceq)$.
In particular, we have $\IN(G, \preceq) = \IN(G,\ell)$.
Moreover, this transformation can be done in time $\mathcal{O}(|U| \cdot |V|+|E| \cdot \max_{v\in V}|\varphi(v)|)$.
\end{restatable}

In fact, we derive \cref{fromPO-to-LBtri-free-graphs} from a more general result for the class of diamond-free graphs (\cref{fromPO-to-LBdiam-free-graphs}).
The analogue of \cref{fromPO-to-LBtri-free-graphs} for diamond-free graphs is given as~\cref{thm:diamond-free}.

Next, we show how to compute an optimal $\ell$-constrained intersection representation of a triangle-free graph $G$.

\begin{restatable}{theorem}{trianglefreelconstrained}\label{triangle-free-l-constrainedIN} 
Let $G = (V,E)$ be a triangle-free graph and $\ell:V\to \mathbb{Z}_+$ be a demand function on the vertices of $G$.
Let $b:V\to \mathbb{Z}_+$ be a capacity function on the vertices of $G$ defined by setting 
$b(v) = \max\{\ell(v) - \deg(v), 0\}$ for all $v\in V$.
Then $\IN(G, \ell) = |E| + b(V) - \nu(G,b)$
%
and an optimal $\ell$-constrained intersection representation $(U,\varphi)$ of $G$ such that $|\varphi(v)|\le \max\{\ell(v),\deg(v)\}$, for all $v\in V$, can be computed in time $\O(|V| \cdot \log L+\sum_{v\in V}\ell(v)+\min\{L \cdot |V|^2, |E|^2 \cdot \log |V| \cdot \log L\})$, where $L = 1+\max_{v\in V}\ell(v)$.
\end{restatable}

As a consequence of \cref{fromPO-to-LBtri-free-graphs,triangle-free-l-constrainedIN}, we obtain a characterization of the intersection number of a partially ordered triangle-free graph, along with a polynomial-time algorithm for its computation. 

\begin{restatable}{theorem}{trianglegreepreceqin}\label{triangle-free-preceqIN}
Let $(G,\preceq)$ be a partially ordered graph such that $G = (V,E)$ is triangle-free.
Let $M$ be the set of minimal elements in the poset $(V, \preceq)$.
Let $b:V\to \mathbb{Z}_+$ be the capacity function on the vertices of $G$ defined by setting
\begin{equation}\label{definition-of-b}
b(v) = \begin{cases}
 0 & \textrm{if } v \in M\,,\\
  \max\left\{1-\deg(v)+\max\limits_{u\colon  u \prec v} (b(u)+\deg(u))\,,0\right\} &
  \textrm{if } v \not\in M\,.
\end{cases}
\end{equation}
Then $\IN(G, \preceq) = |E| + b(V) - \nu(G,b)$ and an optimal intersection representation of $(G,\preceq)$ can be computed in time $\mathcal{O}(|V|^3)$.
\end{restatable}

