\begin{algorithm*}
  \caption{MASTER Interaction Mechanism}
  \label{alg:MASTER}
  \textbf{Input:} 
  \begin{itemize}
    \item Task $T$,
    \item MAS topology graph $G = (V, E)$ with adjacency matrix $A$,
    \item Starting agent $v_s$ with system setting $S_s$,
    \item Memory modules $\{M_i^{(0)}\}_{v_i \in V}$,
    \item Maximum iterations $N$.
  \end{itemize}

  \BlankLine
  \textbf{Initialization:}
  \begin{equation*}
    R_s^{(0)} = (e_s^{(0)}, a_s^{(0)}, r_s^{(0)}) \gets v_s(S_s, T) \quad 
  \end{equation*}

  \BlankLine
  \For{iteration $t$ from $1$ to $N$}{
    \textbf{1. Input Construction for Each Agent:}
    \For{each $v_i \in V \setminus \{v_s\}$}{
      $O_i^{(t)} \gets \bigcup_{\substack{j \neq i \\ A_{ji}=1}} R_j^{(t-1)}$ \tcp*{Collect neighbor responses}
      \If{$O_i^{(t)} \neq \emptyset$}{
        $\mathcal{P}_i^{(t)} \gets T \cup O_i^{(t-1)} \cup R_i^{(t-1)} \cup M_i^{(t-1)}$ \tcp*{Construct input}
      }
      \Else{
        $v_i$ remains inactive \tcp*{Sleep if no inputs}
      }
    }

    \BlankLine
    \textbf{2. Response Generation \& Memory Update:}
    \For{each active $v_i$}{
      $R_i^{(t)} = (a_i^{(t)}, r_i^{(t)}, m_i^{(t)}) \gets v_i(S_i, \mathcal{P}_i^{(t)})$ \tcp*{Generate response}
      $M_i^{(t)} \gets U(M_i^{(t-1)}, R_i^{(t)})$ \tcp*{Update memory}
    }
  }

  \BlankLine
  \textbf{Output:} 
  \begin{itemize}
    \item Final responses $\{R_i^{(N)}\}_{v_i \in V}$,
    \item Updated memories $\{M_i^{(N)}\}_{v_i \in V}$.
  \end{itemize}
\end{algorithm*}




