\begin{lemma}\label{lem:series_algebra}
For any $x_1,x_2,\dots,x_K \in [0,1]$ with $\sum_{k=1}^K x_k \in [0,1]$, we have
\begin{align*}
 1-\prod_{k = 1}^K(1-x_{k}) \geq \left[ 1-\left(1-\frac{1}{K}\right)^K \right] \cdot 
 \sum_{k = 1}^K x_{k}.
\end{align*}
\end{lemma}

\proof{Proof.} For $y_1,\dots,y_K \geq 0$, the AM-GM inequality implies ${(\frac{1}{K} \sum_{k =1}^K y_k)}^K \geq \prod_{k =1}^K y_k$. Taking $y_k = 1 - x_k$  yields $(1-\bar{x})^K \geq \prod_{k=1}^K ( 1- x_k)$ where $\bar{x} = \frac{1}{K} \sum_{k =1}^K x_k$.  It follows that 
\begin{align*}
    1 - \prod_{k=1}^K (1 - x_k) \geq 1 - (1 - \bar{x})^K.
\end{align*}
Note that $\bar{x} \in [0,\frac{1}{K}]$. If $\bar{x} = 0$, the inequality in the lemma statement holds trivially. Hence, assume $\bar{x} > 0$.  Letting $F(x) \coloneq \frac{1-(1-x)^K}{K x}$, we obtain
\begin{align*}
\frac{1-\prod_{k=1}^K(1-x_{k})}{\sum_{k=1}^K x_{k}} \geq \frac{1-(1-\bar{x})^K}{K \bar{x}} = F(\bar{x}). 
\end{align*}
The function $F$ is decreasing on $(0,1/K]$. Thus, $F(\bar{x}) \geq F(1/K) = 1-{\left(1-1/K\right)}^K$, and hence
\begin{align*}
    1 - \prod_{k=1}^K (1 - x_k) \geq 1 - (1 - \bar{x})^K \geq K \bar{x} F(\bar{x}) \geq \left[ 1-{\left(1-\frac{1}{K}\right)}^K \right] \cdot \sum_{k=1}^K x_k.
\end{align*}
This proves the lemma.
\Halmos\endproof


\begin{lemma}\label{lem:s1k-implications} Suppose that $\sigma \in \mathcal{D}(\sign)$ is a decentralized signaling mechanism for the system analyzed in Theorem~\ref{thm:correlated-upper-bound}. Let $x_{i}^k(j) = \sigma_k(j|i)$ for $i \in \{0, \pm 1\}$, $j \in \sign_k$, and $k \in \comp$. Let $\exsign^k$ be as defined in the proof of Theorem~\ref{thm:correlated-upper-bound}. 
For all $k \in \comp$ and all $s \in \exsign^k$, we
have the following:
\begin{enumerate}
    \item For any $\omega \in \Omega$ with $\omega_{k} = -1$, we have
    $\sigma(s| \omega) = 0$. In particular, for all $\ell \neq k$,
    \begin{align}\label{eq:minus-one-sigma-2}
      x^k_{-1}(s_k) x^\ell_0(s_\ell) \prod_{m \neq k, \ell} x^m_{-1}(s_m) = 0.
    \end{align}


  \item We have
    \begin{align}
        \label{eq:one-zero-sigma}
      x^k_0(s_k) \prod_{\ell \neq k} x^\ell_{-1}(s_\ell)  \ \leq \  x^k_1(s_k) \prod_{\ell \neq k} x^\ell_0(s_\ell).
    \end{align}

  \item Finally, we have
      \textup{(a)} $x^k_1(s_k)> 0$, \textup{(b)} $x^k_0(s_k) > 0$, \textup{(c)} $x^k_{-1}(s_k) = 0$, and also \textup{(d)} $x^\ell_0(s_\ell) > 0$ for all $\ell \neq k$, \textup{(e)} $x^\ell_{-1}(s_\ell) > 0$
    for all $\ell \neq k$.
\end{enumerate}
\end{lemma}

  \proof{Proof.} Fix $k \in \comp$ and $s = (s_1, \dots, s_K) \in \exsign^k$.

    \textsf{Part 1.} Since $f$ is optimal and $f(k|s) = 1$, we obtain
    that $\expec^\sigma[ h_k(\hat{\omega}_k) | \hat{s} = s] \geq 0$.
    For this to hold, it must be that
    $\prob^\sigma( \hat{\omega}_k = -1 | \hat{s} = s) = 0$, which
    implies that
    $\prob^\sigma( \hat{s} = s | \hat{\omega}_k = -1 ) = 0$. This
    implies that $\sigma(s|\omega) = 0$ for all $\omega$ with
    $\omega_k = -1$.
    For any $\ell \neq k$, and $\omega$ with
    $\omega_{\ell} = 0$ and $\omega_{-\ell} = -\one_{K-1}$,
    $\sigma(s|\omega) =0$ implies~\eqref{eq:minus-one-sigma-2}.


    \textsf{Part 2.} Because $f(k|s) = 1$, we have
    $\expec^\sigma[ h_k(\hat{\omega}_k) | \hat{s} = s] \geq 0$. This
    implies
    \begin{align*}
      \prob^\sigma( \hat{\omega}_k = 1 | \hat{s} = s) \cdot K + \prob^\sigma( \hat{\omega}_k = 0 | \hat{s} = s) (-1) \geq 0.
    \end{align*}
    Note that
    $\prob^\sigma( \hat{\omega}_k =1 | \hat{s} = s) = \prob^\sigma (
    \hat{\omega}_{-k} = \zero_{K-1} , \hat{\omega}_k = 1 | \hat{s} =
    s)$, and
    $\prob^\sigma( \hat{\omega}_k = 0 | \hat{s} = s) = \prob^\sigma(
    \hat{\omega}_{-k} = -\one_{K-1}, \hat{\omega}_k = 0 | \hat{s} = s)
    + \sum_{\ell \neq k} \prob^\sigma( \hat{\omega}_{-\ell} =
    \zero_{K-1}, \hat{\omega}_\ell = 1 | \hat{s} = s) $. Thus, we
    have
    \begin{align*}
      \prob^\sigma( \hat{\omega}_{-k} = \zero_{K-1}, \hat{\omega}_k = 1 | \hat{s} = s) \cdot K
      &+       \prob^\sigma( \hat{\omega}_{-k} = -\one_{K-1}, \hat{\omega}_k = 0 | \hat{s} = s) (-1)\\
      &+ \sum_{\ell \neq k} \prob^\sigma( \hat{\omega}_{-\ell} =
    \zero_{K-1}, \hat{\omega}_\ell = 1 | \hat{s}
    = s) (-1) \geq 0.
    \end{align*}    
which implies
    \begin{align*}
      \prob^\sigma( \hat{\omega}_{-k} = \zero_{K-1}, \hat{\omega}_k = 1 | \hat{s} = s) \cdot K 
       +       \prob^\sigma( \hat{\omega}_{-k} = -\one_{K-1}, \hat{\omega}_k = 0 | \hat{s} = s) (-1) \ \geq \ 0.
    \end{align*}  
    Using the fact that $\prob^\sigma(\hat{s} = s) > 0$ and Bayes' rule, we obtain
    \begin{align*}
      &\prob^\sigma( \hat{s} = s | \hat{\omega}_{-k} = \zero_{K-1}, \hat{\omega}_k = 1 ) \cdot \prob(\hat{\omega}_{-k} = \zero_{K-1}, \hat{\omega}_k = 1)  \cdot K\\
      &+       \prob^\sigma( \hat{s} = s | \hat{\omega}_{-k} = -\one_{K-1}, \hat{\omega}_k = 0 ) \cdot \prob(\hat{\omega}_{-k} = -\one_{K-1}, \hat{\omega}_k = 0) \cdot (-1) \geq 0.
%      &+ \sum_{\ell \neq k} \prob^\sigma( \hat{s} = s | \hat{\omega}_{-\ell} =
%        \zero_{K-1}, \hat{\omega}_\ell = 1) \cdot \prob(\hat{\omega}_{-\ell} =
%        \zero_{K-1}, \hat{\omega}_\ell = 1) \cdot (-1) \geq 0.
    \end{align*}
    From the definition of $\mu$, we have
    \begin{align*}
      &\prob^\sigma( \hat{s} = s | \hat{\omega}_{-k} = \zero_{K-1}, \hat{\omega}_k = 1 ) \cdot \frac{1}{K(K+1)}  \cdot K\\
      &+       \prob^\sigma( \hat{s} = s | \hat{\omega}_{-k} = -\one_{K-1}, \hat{\omega}_k = 0 ) \cdot \frac{K}{K(K+1)}\cdot (-1) \ge 0, 
%      &+ \sum_{\ell \neq k} \prob^\sigma( \hat{s} = s | \hat{\omega}_{-\ell} =
%        \zero_{K-1}, \hat{\omega}_\ell = 1) \cdot \frac{1}{K(K+1)} \cdot (-1) \geq 0,
    \end{align*}
    which is equivalent to
      $\prob^\sigma( \hat{s} = s | \hat{\omega}_{-k} = -\one_{K-1}, \hat{\omega}_k  = 0 ) 
      \leq  \prob^\sigma( \hat{s} = s | \hat{\omega}_{-k} = \zero_{K-1}, \hat{\omega}_k = 1 )$.
    The statement in Part 2 follows by expanding each term in this inequality.


    \textsf{Part 3.} 
    Since
    $\prob^\sigma( \hat{s} = s , \hat{\theta} = 0) > 0$, we have
    \begin{align*}
      0 &<   \sum_{\omega \in \Omega} \mu_0(\omega) \prob^\sigma(\hat{s} = s | \hat{\omega} = \omega) \\
        &= \sum_{\ell \in \comp} \frac{1}{K} \prob^\sigma(\hat{s} = s | (\hat{\omega}_\ell, \omega_{-\ell})  = (0, -\one_{K-1})) \\
        &= \frac{1}{K} \sum_{\ell \in \comp} x^\ell_0(s_\ell) \prod_{m \neq \ell} x^m_{-1}(s_m) \\
        &= \frac{1}{K} x^k_0(s_k) \prod_{\ell \neq k} x^\ell_{-1}(s_\ell) + \frac{1}{K} \sum_{\ell \neq k } x^\ell_0(s_\ell) x^k_{-1}(s_k) \prod_{m \neq \ell,k} x^m_{-1}(s_m) \\
      &= \frac{1}{K} x^k_0(s_k) \prod_{\ell \neq k} x^\ell_{-1}(s_\ell),
    \end{align*} 
    where the final equality follows from
    \eqref{eq:minus-one-sigma-2}. This yields 
    \begin{align}\label{eq:fsign-s}
      x^k_0(s_k) \prod_{\ell \neq k} x^\ell_{-1}(s_\ell) > 0.
    \end{align}

    Comparing \eqref{eq:minus-one-sigma-2} and
    \eqref{eq:fsign-s}, we obtain,
    \begin{align*}
      \prod_{m \neq \ell, k} x^m_{-1}(s_m) &> 0 \quad \text{for all
                                           $\ell \neq k$,}\\
      x^k_0(s_k)x^\ell_{-1}(s_\ell) &> 0 \quad \text{for all $\ell \neq k$,}\\
      x^k_{-1}(s_k)x^\ell_0(s_\ell) &= 0 \quad \text{for all $\ell \neq k$.}
    \end{align*}
    From this, we conclude that $x^k_0(s_k) > 0$ and that $x^\ell_{-1}(s_\ell) >0$ for all $\ell \neq k$. This establishes (b) and (e) in Part 3. From the above we also have for each $\ell \neq k$ that
    \begin{align}
      x^\ell_0(s_\ell) = 0 \ \ \text{ or } \ \ x^k_{-1}(s_k) = 0 .\label{eq:alternative-sigma}
    \end{align}
    From \eqref{eq:fsign-s}, we know the 
    left side of \eqref{eq:one-zero-sigma} is strictly positive, and hence so is the
    right side. This implies that $x^k_1(s_k) > 0$ and $x^\ell_0(s_\ell) > 0$ for
    all $\ell \neq k$. Therefore, (a) and (d) hold. In turn, from \eqref{eq:alternative-sigma}, we
    conclude that $x^k_{-1}(s_k) = 0$, which proves (c).
\Halmos\endproof








\begin{lemma}\label{lem:u-suffices} 
Consider the problem $ \max_{u \in [0,1]^K} F(u)$ where $F(\cdot)$ is defined in \eqref{eq:F}. It suffices to consider only $u \in
  [0,1]^K$ satisfying \textup{\textsf{(a)}} $A(u) = \comp$ where $A(\cdot)$ is defined in \eqref{eq:A}; and \textup{\textsf{(b)}} $u_k = u_\ell$ for all
  $k, \ell \in \comp$.
\end{lemma}
\proof{Proof.}
  \textsf{Part (a).} For $u \in [0,1]^K$, if $|A^c(u)| \geq 2$, then we have for all $k \in A^c(u)$,
\begin{align*}
  u_k > \left(1 - \frac{1}{K-1} \sum_{\ell \neq k} u_\ell\right)^{K-1} \geq 0,
\end{align*}
and
$F(u) = \sum_{k \in A(u)} u_k + \sum_{k \in A^c(u)} \left(1 - \frac{1}{K-1} \sum_{\ell \neq k}
  u_\ell\right)^{K-1}$. Letting $\one_{A^c(u)}$ be the vector with $1$ at each component $k \in A^c(u)$ and $0$ otherwise, it is straightforward to see that $v := u - \epsilon \one_{A^c(u)}$ is in $[0,1]^K$ for small enough $\epsilon>0$, and $A(v) = A(u)$. Furthermore, we have
 $F(v) = F(u - \epsilon \one_{A^c(u)}) > F(u)$ for small enough $\epsilon >0$, since each term in $F$ corresponding to a $k \in A^c(v)$ increases (while those corresponding to $k \in A(u)$ remain the same). Hence, such $u$ cannot be optimal.

Next, suppose $u \in [0,1]^K$ is such that $|A^c(u)| = 1$. Without loss of generality, assume $A(u) = \{1, \dots, K-1\}$ and $A^c(u) = \{K\}$. Then we have
\begin{align*}
u_k &\leq \left( 1 - \frac{1}{K-1} \sum_{\ell \neq k} u_\ell\right)^{K-1} \quad \text{for $k < K$,}\\
u_K  &> \left( 1 - \frac{1}{K-1} \sum_{\ell \neq K} u_\ell\right)^{K-1}.
\end{align*}
Observe that $u_K > 0$, and hence $u_k < 1$ for all $k < K$. Define $v \in [0,1]^K$ as follows:
\begin{align*}
    v_k \coloneq \begin{cases} u_k + \epsilon_1 & \text{if $k < K$;}\\
    u_K - \epsilon_2 & \text{if $k = K$.}
    \end{cases}
\end{align*}
for small positive $\{\epsilon_i : i =1,2\}$. Since, $u_K > 0$ and $u_k < 1$ for all $k < K$, we note that indeed $v \in [0,1]^K$ for all small enough $\{ \epsilon_i : i =1,2\}$. 

We have for $k < K$,
\begin{align*}
    v_k - \left( 1 - \frac{1}{K-1} \sum_{\ell \neq k} v_\ell\right)^{K-1} 
       = \ \ u_k + \epsilon_1 - \left( 1 - \frac{1}{K-1} \sum_{\ell \neq k} u_\ell - \frac{K-2}{K-1}\epsilon_1  + \frac{1}{K-1}\epsilon_2\right)^{K-1} 
     \leq \ \ 0,
\end{align*}
for small enough $\epsilon_i > 0$ with $\epsilon_2 > (K-2) \epsilon_1$. Thus, $k \in A(v)$. On the other hand, from continuity arguments, we have
\begin{align*}
    v_K - \left( 1 - \frac{1}{K-1} \sum_{\ell \neq K} v_\ell\right)^{K-1} 
    &  = \ \ u_K - \epsilon_2 - \left( 1 - \frac{1}{K-1} \sum_{\ell \neq K} u_\ell - \epsilon_1\right)^{K-1} 
     > \ \ 0,
\end{align*}
for small enough $\epsilon_i > 0$. Thus, we obtain $K \in A^c(v)$. Thus, we conclude that $A(u) = A(v)$. Finally, for small enough $\epsilon_1$, we have
\begin{align*}
    F(v) &= \sum_{k \in A(v)} v_k + \sum_{k \in A^c(v)} \left( 1 - \frac{1}{K-1} \sum_{\ell \neq k} v_\ell\right)^{K-1} \\
    &= \sum_{k =1}^{K-1} u_k + (K-1) \epsilon_1 + \left( 1 - \frac{1}{K-1} \sum_{\ell \neq K} u_\ell - \epsilon_1\right)^{K-1} \\
    &> \sum_{k =1}^{K-1} u_k +  \left( 1 - \frac{1}{K-1} \sum_{\ell \neq K} u_\ell \right)^{K-1}\\ 
    &= F(u).
\end{align*}
Here, in the inequality, we have used the fact that $\frac{1}{K-1}\sum_{\ell \neq K} u_\ell < 1$. The above implies that any $u \in [0,1]^K$ with $|A^c(u)| = 1$ cannot be optimal either. Thus, we conclude that it suffices to consider $u \in [0,1]^K$ with $|A^c(u)| = 0$, i.e.,  $A(u) = \comp$.  






\textsf{Part (b).} Consider any $u \in [0,1]^K$ with $A(u) = \comp$. Let $u_{\min} \coloneq \min_{k \in \comp} u_k$ and $u_{\max} \coloneq \max_{k \in \comp} u_k$. If $u_{\min} = u_{\max}$, then $u$ already meets the condition \textsf{(b)}. So, let $u_{\min} < u_{\max}$. Then,  
\begin{align*}
    u_k &\leq \left( 1 - \frac{1}{K-1}   \sum_{\ell \neq k} u_\ell \right)^{K-1} \quad \text{for all $k\in \comp$.}
\end{align*}
Define the function $G$ as follows:
\begin{align*}
    G(x) &\coloneq x - \left( 1 - \frac{1}{K-1} \sum_{\ell \in \comp} u_\ell  + \frac{x}{K-1}\right)^{K-1}
\end{align*}
Note that $G(u_k)\leq 0$ for all $k \in \comp$. For all $x \in [u_{\min}, u_{\max}]$, we have
\begin{align*}
    G'(x) = 1 - \left( 1 - \frac{1}{K-1} \sum_{\ell \in \comp} u_\ell + \frac{x}{K-1}\right)^{K-2} \geq 0.
\end{align*}
Since $G$ is increasing over $x \in [u_{\min}, u_{\max}]$ and $G(u_{\max}) \leq 0$, we conclude that $G(x) \leq 0$ for all $x \in [u_{\min}, u_{\max}]$. 



Define $v \coloneq \left(\frac{1}{K}  \sum_{\ell \in K} u_\ell\right) \one_K$. We have  $v_k \in [u_{\min}, u_{\max}]$ for all $k \in \comp$, and hence 
\begin{align*}
    0 \geq  G(v_k) = v_k - \left( 1 - \frac{1}{K-1} \sum_{\ell \in \comp} u_\ell  + \frac{v_k}{K-1}\right)^{K-1}. 
\end{align*} 
Since $\sum_{\ell \in \comp} u_\ell = \sum_{\ell \in \comp} v_\ell$, this implies $k \in A(v)$.  Thus, 
$A(v) = A(u) = \comp$. It is easy to see that $F(v) = F(u)$. Hence,
it suffices to consider $u \in [0,1]^K$ with $u_k = u_\ell$ for all
$k, \ell \in \comp$.
\Halmos\endproof

