	\paragraph{Local types as protocol} 
	Let $\GG$ be a global type and $\procA$ be a participant. 
	The protocol describing the implementation of $\procA$ for $\GG$, denoted $\mathcal{S}_\procA$, is defined directly in terms of the projection by erasure automaton for $\procA$ as: 
	\[
	\mathcal{S}_\procA =
	\bigl(
	Q_\GG,
	\Alphabet_\procA \dunion \set{\emptystring},
	\wprojerasuretrans
	\bigr)
	\]
	where 
	$\wprojerasuretrans \is
	\set{q \xrightarrow{\SyncToAsync(a) \wproj_{\Alphabet_\procA}} q'
		\mid q \xrightarrow{a} q' \in \delta_{\GG}}$.

	\paragraph{Implementation model}
	Communicating state machines belong to a restricted class of LTS with finitely many states. 
	Their definition can be directly adapted by replacing the finite state machine for each participant with a LTS for each participant.  
	In addition, we include the execution trace of the CSM in the LTS state. 
	LTS states are thus subsets of $\prod_{\procA \in \Procs} s_\procA \times  \channels \rightarrow \MsgVals^* \times \AlphAsync^*$. 
	We denote the LTS of a CSM $\CSM{A}$ as $\mathcal {S}_{\procA \in \Procs}$. 
	We say that $\mathcal{S}_{\procA \in \Procs}$ is deadlock-free if every reachable configuration is either final or has outgoing transitions. 

	\begin{definition}[Reachable LTS states]
		$\text{reachable} \subseteq  (\prod_{\procA \in \Procs} s_\procA \times  \channels \rightarrow \MsgVals^* \times \AlphAsync^*) \times (\prod_{\procA \in \Procs} s_\procA \times  \channels \rightarrow \MsgVals^* \times \AlphAsync^*)$
		\\ 
		$\text{reachable} \is 
		\set{((\vec{s}, \xi, w), (\vec{s'}, \xi, wx)) \mid \ldots}
		$
	\end{definition}

	\paragraph{Implementability by LTS} 
	A global type $\GG$ is implementable if there exists a LTS $\mathcal{S}_{\procA \in \Procs}$ such that the following two properties hold: 
	\begin{inparaenum}[(i)]
		\item 
		\emph{protocol fidelity:} $\lang(\mathcal{S}_{\procA \in \Procs}) = \lang(\GG)$, and
		\item 
		\emph{deadlock freedom:} $\mathcal{S}_{\procA \in \Procs}$ is deadlock-free.
	\end{inparaenum}

