	\label{lm:rcvIntersectionSetEquality}
	Let $\mathcal{S}$ be a protocol satisfying \Characterization, and let $\CLTS{T}$ be a canonical implementation for $\mathcal{S}$.  
	Let $wx$ be a trace of $\CLTS{T}$ such that $x \in \Alphabet_?$. 
	Then, $I(w) = I(wx)$. 
\end{restatable}
\begin{restatable}[Send events preserve run prefixes]{lemma}{sndPreservation}
	\label{lm:sndPrefixPreservation}
	Let $\mathcal{S}$ be a protocol satisfying \Characterization and $\CLTS{T}$ be a canonical implementation for $\mathcal{S}$.  
	Let $wx$ be a trace of
	$\CLTS{T}$ such that $x \in \Alphabet_{\procA,!}$

	for some $\procA \in \Procs$.
	Let $\rho$ be a run in $I(w)$, and $\alpha \cdot s_{pre} \xrightarrow{l} s_{post} \cdot \beta$ be the unique splitting of $\rho$ for $\procA$ with respect to $w$.
