Finally, we show that protocols that satisfy \Characterization and intersection set non-emptiness have deadlock-free canonical implementations. The proof follows immediately from the following lemma and the fact that CLTS are deterministic, and is thus omitted. 
\begin{restatable}[Channel compliance and intersection set non-emptiness implies prefix]{lemma}{ccIPrefix}
	\label{lm:cc-intersection-nonemptiness-implies-prefix}
	Let $\mathcal{S} = (S, \AlphSyncSubscript, T, s_0, F)$ be a protocol and let $w \in \AlphAsyncSubscript^*$ be a word such that 


	(i) $w$ is channel-compliant, and 
	(ii) $I(w) \neq \emptyset$.
	Then, $w \in \pref(\lang(\mathcal{S}))$.
\end{restatable} 
\begin{lemma}[Canonical implementation deadlock freedom]
	Let $\mathcal{S} = (S, \AlphSyncSubscript, T, s_0, F)$ be a protocol satisfying \Characterization and let $\CLTS{T}$ be a canonical implementation for $\mathcal{S}$ such that for all $w \in \AlphAsyncSubscript^*$, if $w$ is a trace of $\CLTS{T}$, then $I(w) \neq \emptyset$. 
	Then, $\CLTS{T}$ is deadlock-free. 
\end{lemma}
Soundness thus follows from the three conditions above. 
\begin{restatable}[Soundness of \Characterization]{lemma}{soundnessThm}
	Let $\mathcal{S}$

	be a protocol.
	If $\mathcal{S}$ satisfies \Characterization, then $\mathcal{S}$ is implementable. 
\end{restatable}
